/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240228-14","meetingId":"r06-cm02","date":"2024年2月28日","dateIso":"2024-02-28","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時３９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"私から２点確認をさせていただきたいのですが、１基で大丈夫なのかという、その辺をお伺いしたいと思います。今現在では２か所、夜間入口と本庁舎１階の駐車場から入れるような形になっているのですが、どのような構造になるのか説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"現在検討しているところではありますけれども、Ｂ－２地区の今後の整備なども含めて、今後広く地区として考えてまいりたいと考えています。今３か所、このうちのどこか１か所ないし２か所を夜間出入口として整備することで、今検討を進めているところです。","id":"exchange-001"},{"speaker":"松永委員","kind":"質問","question":"近隣のＪＲのところをお借りするということなのですが、これは一回上がって、またそこの区役所に向かうという形になるのでしょうか。そのまま地下から移動できるという感じは考えていないということでよろしいか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"庁舎の利用という形での利用ができるかというところにつきましては、今現在のところの調整では、できるという確約があるものではございません。現庁舎が２００台程度であるのが１５０台となるというところで、周辺の駐車場利用も含めて…","id":"exchange-002"},{"speaker":"松永委員","kind":"質問","question":"今現在、１５０台のうち、職員の割合と一般の割合というのを考えていらっしゃるのでしょうか。どのくらいなのか説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"現庁舎の割合ですけれども、現庁舎では公用車が１１０台程度、一般車が９０台程度という割合になってあります。今後ですけれども、整備するところといたしましては、公用車が１００台程度、一般車が５０台程度の内訳となる想定で考えてあります。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"提案","question":"今の松永委員の説明のところで、１００台が公用車ということで伺ったのですが、公用車というのは何を指すのかというところを教えていただきたい。我々、トイレトレーナーなどというのも導入を提案していますので…","respondent":"大友新庁舎建設担当課長","answer":"高さにつきましては、こちら、３.２ｍの高さまで出入りができるところで考えているところです。そこについては天井がないところになりますので、高さの制限がないというところも一部確保はあります。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"現状、公用車は何台なのかというところですが、本庁舎と、今このエリアで今回改築になる部分で、どれぐらい公用車が。１５０台のうち１００台は公用車で、訪問する方については５０台という、こういうことの理解でいいのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"公用車の台数につきましては、こちらが今ぴったり最新の状況かというところはあるのですけれども、１１０台あまりの台数と把握しています。この公用車の台数につきましては、東京都が管理する、利用する車両等も含まれてあります。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"公用車の部分は、そういうふうに指定されている場合もあるのですけれども、いわゆる来庁者分としては４０台という理解でいいのでしょうか。そういう説明はこれからされるのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"約１５０台を検討しているところではありますけれども、公用車の台数につきましては、今現在。そこを踏まえて、一般利用の台数をできるだけ確保していくという形で考えていきたいと思ってあります。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"結論は分かったのですが、もう一回お伺いしたいのですが、現状では一般車両、来庁者の車の台数はどれぐらい確保しているのか、分かれば説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"現状は９０台です。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"一般来庁者の車が９０台で、４０台前後ぐらいになる可能性があるということで、半分以下になる可能性があるということなのですが。そういう理解でいいのか、区民がそれで理解していただけるのかどうかというところで、もう一回確認させてください。","respondent":"大友新庁舎建設担当課長","answer":"とめられる台数のところにつきましてですが、一般利用者の確保のところにつきましては、今後設計や運用の中で、また引き続き精査してまいりたいと考えているところです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"年度末とか、そこのところは区民の理解を得られるように、最大限一般の来庁者の台数というのは確保していただきたいということを要望します。資料１の４ページ、大地震時にも主要な機能を確保し、免震構造のことは先日もお伺いしましたけれども。","respondent":"大友新庁舎建設担当課長","answer":"免震構造の点と絡めまして、耐震安全性能のところについても少し触れてご説明をさせていただきたいと思います。今回震度７とか、今回、免震構造および構造体Ｉ類というところで設定をさせていただいたです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後の質問をしてしまいますが、右側のバックアップ性能の６階部分に機械室、水没しないように６階に上げてあるという説明がありましたけれども。これについては、大体真ん中ぐらいにこういうものを置くというのが今スタンダードなのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"使い勝手等を考えたときに、６階に整備することができるというところの中で、６階の整備を考えているところです。オイルという発火するようなものというところにおきましては、建物外に整備するというところで、敷地の中ですが建物の外に整備しています。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"６階まで上げなければいけないというところで、専門的なところが分からないので、そこのところがもし分かれば教えていただきたいということです。最初の部分だけお答えいただけるとありがたいです。","respondent":"大友新庁舎建設担当課長","answer":"地下に持ってきたオイルタンク、オイルを発電機まで持っていく手法といたしまして、検討自体、具体的な設計はこれからになるのですけれども、その耐震性能等、万が一のときに破損等ないような形での設計を進めてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"約６２.２ｍで、３ページで言うと、どこの部分にその防災設備が現れてくるのかというのを教えていただきたいのが１点です。特殊要因で２０億円というのが事業費として示されていますけれども、どういう対策を考えておられるのかというのを教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"屋上設備などの設置箇所というところにつきましては、アンテナとか屋上に来る空調設備等の機器の設備が屋上に今後載ってくるという形になります。そういうような計測費などが積み重なってくるのかなと思ってあります。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、２点目のりんかい線のところも関連すると思うのですけれども。この２０億円というところで見ると、どの程度内訳として見込んでいるのかというのを教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"今回掘削する範囲におきましても、掘削するレベルにおいてもう水が出るというところで、地下水対策は見込んでおります。地下水対策、ポップアップになるとは思うのですけれども、具体的な金額をこの場でお示しすることはなかなか難しいのかなと考えているところです。","id":"exchange-013"},{"speaker":"松本委員","kind":"意見","question":"例えば、区内の区が持っているほかの駐車場に移動させて、ある程度空きをつくるというふうな運用が想定できるのかというのが１点。今２時間以内であれば、例えば２時間使う分には無料という運用をこれからお願いする感じになると思うのですが、２点お願いしますとの意見を述べました。","respondent":"大友新庁舎建設担当課長、黒田新庁舎整備担当部長","answer":"様々な運用検討はしているところではありますけれども、実際に外の駐車場に公用車を出して、精査がまだ終わっているというところではございません。引き続き検討はしていきたいというところで考えているところです。 現庁舎との比較の中で、使い勝手が悪くなるのではないかといったご懸念があるということは、質疑の中でも重々私ども受け止めております。区民の皆様がご利用しやすいような庁舎になるようにというところも含めて…","id":"exchange-014"},{"speaker":"松本委員","kind":"意見","question":"基本設計の段階なので、どこまで想定するかというのはありますし、今日のご答弁を受けまして、これからというところも理解はできました。例えば６０とか７０とか街宣車が動く、運用も頭に入れていただきながら、いろいろ想定していただければなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"筒井委員","kind":"意見","question":"そうしたことも、完成する２０２９年においては、ある程度充実させていかなくてはいけないなと考えているのですけれども。その点、区としては、駐車場の充電設備とか、そうした環境対応をどうお考えになっているのかをお知らせくださいとの意見を述べました。","respondent":"大友新庁舎建設担当課長","answer":"駐車場の充電設備というところの環境対策についてご回答させていただければと思います。エコカーといいますか、ＥＶ車といいますか、そのような車の充電できる設備を設ける形で検討を進めているところです。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"補助２６号線に向けて歩行者専用通路が幾つか、２号、３号、４号、補助２６号線に出る側の通路があるのですが、確認させていただきたいのですが。立ち退きとか、そうしたこととか、そうした再編を考えられているのか、説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"一部お店がなくなるところなども出てまいりますけれども、どういった構造で抜いていくかとか、そういった協議を重ねているところです。回遊性の向上に向けて、引き続き取り組んでまいりたいと考えています。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"当事者、関係者の皆様のご納得を得られるような方法で、そうしたお話を進めていっていただきたいと考えております。広町地区２４０ｍの範囲、これは都市計画法上の最低限の範囲なのか、範囲もこの程度のものなのかということを確認させてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"この説明会を実施するに当たりましては、基本的な考えでいきますと、建物の高さから２倍の範囲で今回周知をするということで考えているところです。ちなみに、この範囲につきまして、少し補足なのですが、中高層の紛争予防条例に基づいて実施していくです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"かなり煮詰まってきている状況かなと思っているので、もう少し説明を広域にしてもいいのかなということも考えているのですけれど。今後の周知の在り方、もう少し広報していったほうがいいのかなと考えているのですけれど、その点いかがお考えか尋ねました。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"区民周知につきましては、今後、基本設計等が取りまとまった段階で、また広く実施していきたいと考えています。 ただいまご質問がございましたこちらの近隣説明会の実施等につきましては、広報しながわ等の掲載によりまして周知を図ってまいりたいと考えています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"説明会の周知とともに、ある程度ここまでかなり具体的にお話が出てきているので、そうした全体の概要というのも広報しながわで周知していったらいいのかなとは考えているのですけれど、その点いかがお考えか尋ねました。","respondent":"山下新庁舎整備課長","answer":"今現在考えておりますのは、こちらの開催、実施をするよということの周知ということで、紙面等の制約等から今調整に臨んでいるところでございまして、現段階での検討としては、そのような状況です。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"当然、説明会の開催告知ですから、今回資料に示されたようなイメージ図とか、そうしたこともそろそろ出していくというお考えか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"イメージ等も固まってきて、建物概要も固まってきている段階です。さらに基本設計の後段といたしまして、全体周知ということで、区民の皆様にまたご説明できる機会を新たに設けていきたいと考えているところです。","id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問","question":"１点、私も駐車場に触れようと思っていまして。そもそもこの区画道路がＴの字にあって、駐車場の入り口というのは、この区画道路のＴの縦棒のところに入るのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"駐車場の出入口の箇所につきましては、南北道路、新たに整備される縦の道路、そちらのほうから車に入っていただく形を想定しています。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問","question":"だから、例えば、地下は２階しか掘れないし、これ以上はできない。そうなのか、例えば、ＤＸ化が進む中で、そもそも車での来庁者数というのが減るという見込みなのか、そこら辺を説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"見込み等の想定もしているところではありますけれども、上乗せで１５０台整備していきたいという考えに基づいて、今回整備を進めているところです。","id":"exchange-023"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば、こんなすてきな広場ができれば、やはり車で来たいなと。ほかのところとの連携という部分を見越して想定するのではなく、ここでうまく収められるという、そういった想定ができるように要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"えのした委員","kind":"質問","question":"６階のほうは防災と重要機械室、１ページ目にも災害対策機能として、連携を強化するということで理解をしたのですけれども。議場は最上階ですから、どういった考え方でこのフロア分けをされているのか、お知らせいただけませんか。","respondent":"大友新庁舎建設担当課長","answer":"そちらのほうが届く範囲というところにおきまして、６階は届く範囲という形にはなるのですけれども、今回、運用面を中心に考えて配置をしたです。実際に非常時、消火活動や避難を考慮して、非常用エレベーターを２基設置するというところにおきましては。","id":"exchange-025"},{"speaker":"えのした委員","kind":"意見","question":"防災の面は理解しました。新庁舎で１４階建てになるときには、窓口も含めて、その階層配置はどういうふうにされたというのをご説明をお願いいたしますとの意見を述べました。","respondent":"大友新庁舎建設担当課長","answer":"６階、７階につきましては、先ほどお話をいただいたとおりの考え方での配置となっています。最上階に議場を持ってくるというところにおきましては、このフロアに議会機能を持ってきたという考えで配置をさせていただいているところです。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"別紙２の左下、何事業者ぐらい参加されるご予定なのかというのがもし分かれば教えていただきたいというところです。そういった考えから、区民の皆様のアイデアを今後、竣工までの段階で様々集めていくということはご検討されているでしょうかです。","respondent":"大友新庁舎建設担当課長","answer":"先ほどの事業者任意説明会ところにつきましては、イコール区が事業者となっているので、区が行う説明会と認識していただければと考えています。続きまして、区民の意見を踏まえた詳細設計の実施というところにつきましては、基本設計がまとまった段階で広く説明等をしていく段階…","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"この事業者の意味等、理解いたしました。今後の区民の皆様への説明の機会で、アイデアを聞いていただく場を設けたりしながら、検討を進めてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"これまでの検討状況ですけれども、パブリックコメントの実施時期に合わせまして、オープンハウス方式説明会を全３回開催いたしまして。最後に項番４、３月２２日に答申を踏まえた活用方針（案）に係る住民説明会を旧荏原第四中学校にて実施後、具体的な検討を開始してまいります。","id":"exchange-028"},{"speaker":"塚本委員","kind":"意見","question":"これを今後どういうふうに、直轄なのかとか、いろいろな議論はこれからされるのだと思うのですが。ここをどういうふうに切り盛りしていくのかというような議論というのが、区のほうでどのような状況になっているのか、説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"基本方針を策定していくというところで、跡地活用方針策定委員会の中でご議論いただいて、答申をいただいて方針を策定していくというような段階です。運営方法についてのお話がございましたけれども、どのように運営していくのが望ましいかというところ…","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"例えば、屋上を庭園として見たらどうなのだと、いろいろな話があったと思うのですが。スペースというか、地面を広くしてということで園庭の面積を確保すると、こういう考え方でよろしいのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"ぷりすくーる西五反田の園庭面積の確保ですけれども、改築を行うことで、いろいろな形で園庭面積の確保の方法はありますので、そちらについても具体的な検討を進めていくです。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"具体的なというと、現段階では、どのように確保するかはまだ確定していないというところなのでしょうか。それとも、一定程度こういうやり方でいくという方向が出ているということかなと思ったのですが、そこをもう少しお聞かせいただいて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"そうですか。大体のところで、いつ頃そういったことが見えてくるのかというようなことはどうなのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"スケジュールについても、これから線を引きましてご報告をするですけれども、保育園の利用者、シルバーセンターの利用者もありますので、そういったところは、適切な時期に分かりやすく報告をさせていただければと思ってあります。","id":"exchange-032"},{"speaker":"まつざわ委員","kind":"質問","question":"６分団というのは文庫の森でやらせていただくのですが、要は、通りでいいのです。道路側というのですか、そういった苦情の課題解決もいろいろ考えられるかなと思っているのですが、難しいか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"今後の運用というところでのお話かと思いますけれども、今後ゾーニングなども次年度以降検討していくですので、いただいた意見をどのように活かしていけるかというところは、引き続き検討していきたいと考えております。","id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"ゆたか図書館が４７年、シルバーセンターは４０年、そういった方向性も考えていく必要があるのかなと思っているのです。そこら辺、区のほうでどういった考えがあるのか、説明を求めました。","respondent":"こんの委員長、吉岡政策推進担当課長","answer":"いわゆる跡地活用の話なので、今ある既存の整備となると、なかなかお答えしにくいのかなという部分ですけれども。何かお答えできるようでしたらば。 こういった周辺施設の状況があるというところは当然認識をしていますので、次年度以降、検討するです。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"誰がご提案されて、その辺りを教えていただきたいのと、恐らく今までも何回か出てきたのですか。どういう施設になるのかというのが何かご説明できるのかというところで、どういうご説明をしようと考えていらっしゃるのか、説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"こちらは跡地活用方針策定委員会の中で委員から出された言葉でございまして、創発、なかなかどういう意味だろうというのが分かりづらい言葉です。地域に向けて説明というところなのですけれども、こういった事例がありますというところで…","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私の要望としては、この３つの大きなコンセプト、全て説明が必要なもの。要望としては、より丁寧に説明をしていただきたいということですけれども、一言お願いします。","respondent":"吉岡政策推進担当課長","answer":"ワークショップの中でも、様々な導入施設の意見をいただきましたけれども、これを全て受け入れることはできないというところはあります。理解していただくために、意見を聞いていくという姿勢が必要だと思いますので、今後とも変わらずそのような対応をしていきたいと考えていま…","id":"exchange-036"},{"speaker":"えのした委員","kind":"意見","question":"いまだに１０年経っても、避難解説のマニュアルができてはいるのですけれども、なかなか確定していない部分とかもありまして。どこまでそういった拠点の施設をつくられるのかというのは、これからだとは思いますが、現状あればお知らせくださいとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"今回は方針というところで、そういった安心・安全、そういったところに努めていきたいと考えているところです。そういった設備部分も同様です。","id":"exchange-037"},{"speaker":"えのした委員","kind":"質問・要望","question":"やはり近くの方だけでなくて、遠くの方も利用する施設になると思いますので、その辺しっかりとつくっていただければと。こちらは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"山本委員","kind":"質問・要望","question":"この交流拠点という位置づけであったり、様々な仕組みに関して、すごくよいなと考えています。課題というか、もっとこういうふうにできたのではないかみたいに思っているところなどがあれば、少しお聞かせいただきたいです。","respondent":"吉岡政策推進担当課長","answer":"オープンハウス方式説明、皆さんの意見も聞きながら方針案は策定されたのかなというところで考えているところですけれども、そういったものは引き続き検討しなければいけないなと感じたところです。","id":"exchange-039"},{"speaker":"山本委員","kind":"質問・要望","question":"様々な機会を通じて区民の皆様の意見を聞いていただいて、それを盛り込んでいただいているというのはすごくいいなと思いました。で、引き続きそういったやり方などについてもご検討いただき、今後の同じような機会に役立ててほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"伺いたいのが、これは品川区としてやっていることなので、関係する団体との関係でどうなのかなと思って。枠組みの中に入っているのか、それは別というふうな枠組みなのか、これはどちらなのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"こちら、品川区の電子申請サービスに関しましては、品川区が利用しているＬＧＷＡＮに接続する端末で受付のほうを実施しております。セキュリティ上、業務をお願いできる団体かどうかというところをしっかり見極めまして、ＩＤを発行させていただいているという状況になります。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"これはもう本当に区議会側のとても恥ずかしいことだと私は思っていて。この印刷枚数のカウントに、区議会および区議会議員向けの印刷枚数というのもデータとしては集計されているのか、伺います。","respondent":"河西情報戦略担当課長","answer":"こちらの印刷枚数になりますが、こちらは条件がございまして、１８ページ下に小さく書かせていただきました。今回、お手元にあるこちらの紙に関しましても、複合機から印刷されておりますので、対象になっているということで、ご報告します。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"そこは質問の仕方を変えさせていただいて、多分今日配られるのが３回目か４回目ぐらいで、同じ資料が結構配られていて。もうそれすらもなくて、基本的にはもうデジタルが前提となっているのか、その辺りはいかがか尋ねました。","respondent":"河西情報戦略担当課長","answer":"今は、会議を主催する所管の考えによるところもあります。理事者は端末を持っておりますので、基本的には端末を持ち寄って、その端末の中で電子データを見ながら庁内の会議は実施しています。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"こうやってご報告を受けて、本当は今日聞いていただきたいところの方がいらっしゃらないような気もするのですけれども、そこはすごく理解できました。議事録に残すということも大事だと考えていますので、聞かせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"そういう中で、これはどのような工夫をされる、通知というのはどういうことをお考えになっているのかをお聞きしたいのが一つです。この２点、お伺いしたいと思います。","respondent":"横田情報推進課長、河西情報戦略担当課長","answer":"オンラインで寄附金控除申請ができるようになるほか、返礼品の配送状況が分かるようになる予定です。４点目なのですが、マイナンバーカードの署名用電子証明書と連携して登録ができるようになって、今現在調整しているところになります。 私からは、２つ目のご質問にお答えいたします。ＲＰＡツールに関して、人手がかかっている手入力のところの対応に使えないかということですが、そういった用途に利用されております。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"提案","question":"本人確認をして、来年の事業で申し訳ないのですが、教えてください。今改めて確認させていただきましたので、ぜひ、それこそＲＰＡ化していったほうがいいのではないでしょうかということでご提案をしたいと思いますがとの意見を述べました。","respondent":"横田情報推進課長","answer":"１点目のおくやみコーナーについてのお問合せです。実際に来ていただいて、そこの当てたＩＣチップの４情報、それを自動的にいろいろな申請書に書き込んでいくというような仕組みになります。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本人確認をして、その方が行けば、もう既にそういった書類が一式そろっている。ぜひそういったことも検討していただきたいということで、最後、ご答弁をお願いしたいと思います。","respondent":"横田情報推進課長","answer":"委員ご提案の件ですが、今予定しているやり方をやってみて、どういうふうにできるかというのをいろいろ検証してみて、決めていきたいと考えております。","id":"exchange-047"},{"speaker":"山本委員","kind":"質問・要望","question":"どういった状況なのかというところで、どう受け止めていらっしゃるか、今後の利用増加の見通しのところもお伺いできればと思います。業務量が削減されたときの、例えば削減時間とかを測定するとか、そういったところが確認できるようにお考えなのかというところを説明を求めました。","respondent":"河西情報戦略担当課長","answer":"２３業務で新たに今年導入する予定なのですけれども、こちらもどういった計算の仕方ができるか今検討中ですので、こちらも。ちょうど今日、追加の研修を実施しておりますので、それが業務の効率化につながるように進めていきたいと考えております。","id":"exchange-048"},{"speaker":"山本委員","kind":"質問・要望","question":"最後に、チャットＧＰＴ、これ、毎日２０～３０名というのは、全職員の割合からするとあまり多くはないのかなというところは思っております。そして、研修をされるということですけれども、これは何名ぐらいの方を対象に、何回ぐらいご予定されているのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"追加の研修になりますが、本日午後、２コマ実施予定になっておりまして、１コマ３０名です。なので、合計で６０名の研修になります。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問","question":"３０名ぐらいということで、やはりまだまだ多くの方々に使ってもらえるような環境を整えていくことが大事なのかなというところだと思いました。それに対する考え方とか、課題と感じていらっしゃるかどうか、どのようなことが課題かとか、コメントいただけるようでしたら、お願いします。","respondent":"河西情報戦略担当課長","answer":"チャットＧＰＴのほうも日々日々進化しておりまして、新しい機能が追加になったりしております。そういったものを、そういったものを庁内のインフォメーションを使って見ていただきながら、利用のほうを促進していきたいと考えています。","id":"exchange-050"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ多くの職員の皆様に使っていただけるように、研修とともに、それ以外の様々な工夫を進めてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"各現場にどういうものがオンライン化できそうな業務ですか、手続ですかということで、出たのが最初に出ている１,２９６。それをお聞きしたいのと、まだまだ増えるよという見通しを持っていらっしゃるのか、そこについてお伺いします。","respondent":"河西情報戦略担当課長","answer":"お話ができた大田区の例でいきますと、大体３,０００手続あると。何が我々にはなくて、こういったところを注視しながら、手続に関しても漏れがないか確認していきたいと考えております。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問","question":"では、今回は現場に改めて聞いたというよりは、そういう所管のほうでホームページを検証して、この追加の手続を洗い出したと、こういうことなのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"具体的に申しますと、まず我々、情報部門のほうで手続を洗い出しまして、これは対象ではないですかという一覧を各課に配りました。その結果、これは違いますよというのを落としていただいて、最終的に集まったのが、この１,６６１になっているというところで、ご報告します。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"やることは一緒だったら、手続数は一緒だから、もしかしたら大田区ぐらい対象になるのはあるのかもしれないという見方もできるのですが。オンライン化できるような手続を対象に挙げていけるようなやり方というのは考えたほうがいいのかなとも思うのですが、今どのようにお考えか尋ねました。","respondent":"河西情報戦略担当課長","answer":"今、大田区から、どういうやり方を取られたかというお話を聞いております。ですので、それが品川区でも利用できるようであれば、まねさせていただいて、検討を進めていきたいと考えております。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に、システム標準化の状況のところなのですが、いよいよ令和７年度の末には一部のシステムが標準化で稼働するというところまで来ましたけれども。どういう理由によるものかということと、何か改善とか改修等を行うということの前提でのＲＦＩの依頼ということなのかというところでお伺いしたい。","respondent":"横田情報推進課長","answer":"令和７年度末までという短い期間になりますので、それでも引き受けられるよと答えられたのがプロポーザルを実施しているというような形になります。２点目の、これまで各自治体が、システム事業者も全てアプリをつくり直すというような形を取っております。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、今あるものがどういうものかということがネックで、事業者がもう決まってきてしまうと、こういうことなのでしょうか。そこは純粋な価格競争で、よりよいところを選定するみたいな話があるのではないかと思ったりもするのですけれども、そこのところを説明を求めました。","respondent":"横田情報推進課長","answer":"今ある現状と標準仕様書のギャップを分析して、その作業はどうしても工数はかかってしまうというところで、各事業者がなかなか厳しいというところ。今、そこで時間をどうしても要してしまうというところで…","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"４４５手続が、４４５手続全部、完全に可能とするということでよろしいのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"ですので、先ほどご説明した請求書ですとか見積書が必要な手続に関して、オンライン化できると。４４５手続記載しておりますが、あくまでも請求書と見積書に関係する手続ということで、ご回答します。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした規制だとか、規則だとか、そうしたものの改正を関係機関とか国とかに要望するということはあるのでしょうか。ぜひやっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"横田情報推進課長","answer":"押印省略化につきましては、会計事務規則の改正をしたところです。その辺りで、どういったものがデジタル化できるのかというのを、これから調査をしてまいるところです。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"６ページのマイナンバーカード交付率のところで、具体的にどのように利活用されていくのか。このことについて利活用していきますよということ、現時点で固まっているところがあれば、説明を求めました。","respondent":"横田情報推進課長","answer":"少し省略して、一応予定しているところがデジタル通知というところで、区民のスマホにデジタル的に通知するサービス。大きくは以上になります。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"９ページのところなのですが、子育て世代が８割キャッシュレスということで、非常に便利だなと思ったのですけれど。端末が１個しかないので、ぜひ端末を増やしていただきたいなと思っているのですけれども、お考えはいかがか尋ねました。","respondent":"横田情報推進課長","answer":"税務課ですとか、地域センター、大体１５～２０％ぐらいの利用率になっております。そこの辺りの利用率も含めまして、今後、台数を増やすかどうかというのを検討していきたいと思います。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問・要望","question":"１０ページの高齢者スマホ教室ですけれど、大体今、基本的な操作はできている方が増えてきているのかなと思っているのですけれど。基本的なことを教えていただく教室というのは引き続きやっていただきたいのと同時に、そのオンライン配信、いかがお考えか尋ねました。","respondent":"横田情報推進課長","answer":"こちらにつきまして、高齢者地域支援課の事業になりまして、正直、我々のほうでお答えが難しいのですが。デジタル活用支援推進事業というところで、通信キャリアに委託してショップでスマホ教室を実施していたりですとか、相談会とか。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"区の事業のついでに広報していただくとありがたいので、その点も含めて、ぜひ高齢者スマホ教室を進めていってほしいと求めました。最後に、１９ページのテレワークの実施状況で、この新システムというのは具体的にどのようなものなのか尋ねました。","respondent":"河西情報戦略担当課長","answer":"Ｗｉ－Ｆｉルーター、決まったルーターなのですけれども、そちらを使うことによって接続できると。ですので、予約する必要もないですし、取りにくる必要もないというところで、ハードルが下がったものになります。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118715?Template=document&Id=6164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":49850,"voices":160}},{"id":"r06-20240229-19","meetingId":"r06-cm02","date":"2024年2月29日","dateIso":"2024-02-29","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そして１月１８日には、それによっての課題や成果というのがあったと思うのですが、それがどういったものだったのかというのを伺いたいと思います。別紙の１ページのところで、これがどういったものなのかというところで、どういうものなのかというところを伺いたいと思います。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"４点質問いただきましたうち、マニュアルの部分と処理実行計画の部分につきましてお答えします。どのような処理方針とするのか、そういったことを定めていくという形ですので、ある程度被害の概要が見えてきた段階で作成していくです。 協定についてご説明いたします。シミュレーションをやってみても、やはり人数は足りないだろうなというところで、そういうところが課題になるのではないかということを感じました。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"状況を確認しないと、道路啓開ですとか、廃棄物処理などもできないと思うのですけれども、そこのところはいかがかと伺いたいと思います。別紙右下に地図が載っておりますけれども、町丁目ごとの発生量はどのように算出をされているのか伺います。","respondent":"品川品川区清掃事務所長、平原防災課長","answer":"７２時間で通常のごみ収集ができるかどうかというところですけれども、これは一番、道路啓開が大きく影響してくるところかと思います。計画の段階では、一定程度、あとは状況を見て判断をしていくという形になるかと思います。 平成２４年の東京都が出した被害想定のところで、町丁目ごとの建物の倒壊の見込みといったところがございまして、それをベースにした数字です。災害の危険度判定のところから考えて…","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"７２時間後に通常収集再開というのが、東京都の被害想定で考えると７２時間後には再開できるという計画なのかというところを伺いたいと思います。東京都の平成２４年の想定でやられているということなので、いろいろ見直すところが出てくるのかなと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"災害対策本部清掃部として実際の災害廃棄物処理に当たっていくということで、それをもって７２時間を目途としています。各種計画の見直しを考えてありますので、災害廃棄物処理計画につきましても、見直していくということを考えてあります。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ただ、２万５,０００ｔ以上というのが１０個ぐらいありますが、公園が町会内にないというところはどのように考えているのか伺いたいと思います。分別の徹底が重要だということで、別紙２ページの下のところにも書いてありますけれども、今の区の取組をどのようにされているのか伺います。","respondent":"平原防災課長","answer":"こちらは先ほどご説明させていただきましたとおり、区内の公園は必ずしも廃棄物のためだけではなくて、様々なことに活用用途があります。引き続きそのような形で、この重要性を区民にお知らせできればと考えています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"防災の面からも、町会に公園がないところは整備を進めるべきだと意見を述べておきたいのと、区の考えも伺いたいと思います。この計画も見直しをするということですから、実施をお願いしたいと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"継続的に出てくるというよりは、そんなに継続性はないものと考えていますので、そういった意味では性格を異にするものだと考えています。今回、その中に災害廃棄物というものを位置づけて、今後周知してまいりたいと考えています。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことを防ぐ努力はしていただきたいと思うのですけれども、その辺の対応はどのようにお考えか伺います。先ほどの、これは区民やボランティアとの協力の混乱防止のところにも関係するかと思うのですけれども、その辺をどのようにお考えか伺います。","respondent":"平原防災課長","answer":"先ほど来ご説明しています廃棄物処理計画に基づきますマニュアルであるとか、全てやらせていただきたいという計画にしております。そういう力も大きいかと思いますので、そういったことも併せて、災害廃棄物処理が適正に行われるようにしてまいりたいと考えています。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ご自分のご家庭のし尿とかは処理されたというのも伺っておりますが、そういう経験をされた方が、東京ではどうですかねと心配してくださるのです。みんなで協力して解決していくべきだと思うので、説明会を開くべきではないかと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"平原防災課長","answer":"説明会というお話でございましたけれども、災害廃棄物の説明という形でしたら、少し現実的ではないと。いろいろな場で、こちらに触れる機会というところをご紹介させていただきながら、皆様に広めてまいりたいと考えています。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"何かのときにご質問いただいたとき、この間こういうのが配られたでしょうと言うと、えっという感じです。探せば、配られた資料を有効に活かすためにも説明会は有効ではないかと思うのですが、その辺についてもう一回お答えください。","respondent":"平原防災課長","answer":"町会・自治会にはしっかりとご説明させていただきまして、まず地域の入り口のところではご説明させていただいて、そのようにやっているところです。なかなか全てに対応できるということが難しいので、様々そういったところ…","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望ですので、ぜひご検討ほしいと求めました。もし何かコメントがあったらいただきたいのですけれども、私からは要望といたします。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"あるいは、そういったところもいろいろこちらでも研究しながら、広めていく方策を考えさせていただければと思います。個別の対応というお話もございましたけれども、どのようなやり方がいいか… 説明会のお話ですけれども、少し気になるのが、防災という観点の中で説明をしていくというところは非常に大事なところかなと思います。災害のごみという区分でやっていくというのは、一ついい方法ではないかなと思いますので…","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"令和４年４月に出された品川区災害廃棄物処理計画では、候補地の選定、管理方法の検討項目として挙げられていました。令和５年度の地域防災計画では、応急仮置場についても候補地が全公園となりましたが、このようになった経緯についてお聞きできればと思います。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"地区仮置場ではなくて、仮置場というところの候補地ですので、当初から全ての仮置場の候補地として入ってございました。それを具体的に、そこに応じて考えていくということにしておりますので… ほかの自治体の事例などを見ますと、建設中の用地も借りたりとか、そういうところもあったりします。一定程度限定したような形で、とにかく被災の状況によって、どこにするかというところを選択していく…","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"警察・自衛隊・消防に災害対策本部を通じて報告となっているので、より密な連携を、さらにより一層お願いしたいと思います。３つ目が情報収集訓練、４つ目が図上訓練となっておりますが、今の実施状況といったところでお聞きできればと思います。","respondent":"品川品川区清掃事務所長","answer":"訓練というところですけれども、事実上、１月に行いました天王洲のところが初めてという形です。訓練については、様々な状況等も想定しながら、またいろいろな訓練を行っていきたいと考えております。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"大きな災害は、急に来て、急に対応せざるを得ないというのが現実だと思います。区民への啓発になると思われますので、こういった活動をしているというのも、うまく情報発信してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"は、どうやって示すのか、それをどうやって周知していくのかということを教えていただきたいです。","respondent":"平原防災課長","answer":"様々な支援情報も含んでなのですが、場合によっては、可能であれば広報車ということも考えてあります。いわゆる人力、あるいはシステム上、そういったものも含めてお知らせしていくということで、今考えているところです。","id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"３月９日に行われる防災フェアや、町会などの防災訓練でも活用できるように、マニュアルなどを作成するのもいいのではないかと。ご説明していったらいいのではないかと思うのですけれども、それについて、区の考えを説明を求めました。","respondent":"平原防災課長","answer":"先ほどご説明させていただきました品川区防災地図を配付した際に、その中身を継続的に様々な場で、まず広めていきたいという考えです。トイレの考え方あるいは使い方、実際の訓練実施につなげていけるように、次年度努めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"分かりました。一歩踏み込んで、それも活用しながらになるかとは思いますが、町会の方たちがそれぞれ説明できるような形に落とし込めるといいなという要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"こしば委員","kind":"質問・要望","question":"少し細かいことも含めて確認といいますか、質問をさせていただきたいのですけれども、家屋の中で置かれていたたんすが倒れて破損した。区民目線でそういった疑問点というのも出てくると思いますので、そこで基準がありましたら、教えてほしいと求めました。","respondent":"平原防災課長","answer":"こちらの資料３のところには、何らかの被害を受けたといったことですので、動産被害も含んでいるというご理解をいただければと思います。そういった意味で、特に家はびくともしなかったのですけれども、テレビがひっくり返りましたとか…","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問・要望","question":"町会でも、役員も少ないところもあります。区で何かその辺りのお考えといいますか、サポート体制みたいなものがあるならば、教えてほしいと求めました。","respondent":"平原防災課長","answer":"必要なところに重点的に派遣するという形で考えてありますので、そういったところに、区民のお手伝いをしていただく。別な観点でのボランティアが行くとか、そういう濃淡をつけながら対応するということを、第一義で考えているところです。","id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"さらに一歩踏み込んだアクションといいますか、お願いをしていただきたいと思うのですけれども、お考えを教えてほしいと求めました。","respondent":"平原防災課長","answer":"ご支援といいましょうか、マンション防災の考え方を大きく拡充して、ふだんどうしていきましょうというところをお示ししていきたいと考えています。今考えてありますので、今後、周知を図ってまいりたいと考えています。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"なぜなら、これ以上のものが来たらどうするのですか。一番分かるのですから、そのような方向に持っていったほうがいいと思うのですが、なぜ被害想定を毎回どんどん減らしていくのか。","respondent":"平原防災課長","answer":"発生量の数値の変更のところですが、私どもが様々考えたところ、全国的に見てもできているものだなと。いかようにも対応できるような形、対応できるような計画という形で活動を考えてありますので、私どもとしては重視しています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、それは手段として考えてほしいと求めました。ただ、悔しくて、想定を毎回下げられて、変に安全なような錯覚を起こしかねないので、別にこれは意見だけな。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"私の認識不足ですが、災害廃棄物に関しての協定を結ばれているのは、この１者が初めてで、ほかにもあるのかということをお伺いしたいと思います。どういうことをやっていただくのか、どの段階のフェーズからカムズが動かれることを想定しているのかということを教えてほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"ほぼそちらで対応は可能かとは思いますが、今進めているところの一つとして、カムズと今回やったです。そこの部分を今回、カムズに協定としてお願いしています。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問","question":"流れが分かりました。１者で協定がどうなのかなというところが心配だったのですが、品川区としては、この協定というところでよろしいのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"これはさすがに廃棄物の量、状況等によりますので、現在このカムズの中で対応できるということまでは言い切れないという状況です。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、そこは取り組んでいかないといけないのかなというところも感じるところではありますので、その辺はぜひ念頭に入れてほしいと求めました。町会を中心にしっかりと行っていただきたいと思うのですが、決まっているのかどうかというところがあれば、教えてほしいと求めました。","respondent":"平原防災課長","answer":"計画が変わったとか、何か動きがあったときには、当然ご説明することとなっております。あるいは、地区に内在しているような災害時の活動といったところもご説明させていただきながら、ご支援させていただこうと考えているところです。","id":"exchange-023"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"何点かお伺いしますが、明確に行政から示していただきたいのですけれども、改めて明確に発信をしてほしいと求めました。ぜひ想定外として想定をしていただきたいと思うのですが、まず、そこを１点説明を求めました。","respondent":"平原防災課長","answer":"私どもも地域を回って説明させていただいた際には、併せてご説明させていただいてきたところですし、強く発信してまいりたいと考えています。想定ではないようなところ、想定を超えたようなものが発生したときにどうするのかといったことで対応していこうと考えています。","id":"exchange-024"},{"speaker":"せりざわ委員","kind":"提案","question":"数点お伺いしますが、被害発生直後も含めてですが、しっかり確保できるという計算をされていらっしゃるのかをお聞かせほしいと求めました。町会加入とかということをいろいろ提案してきたので、正直なところ…","respondent":"品川品川区清掃事務所長、平原防災課長","answer":"これは現実論からいって、被災の状況によっては、確保できないという状況もあり得るかと思います。もう少し車の確保については、協定等を結んでいくとか… 地域と一緒にやっていただくということの重要性といったものを、次年度以降のマンション防災の一つの考え方の柱として進めていく所存です。どのような形がいいかというのを、これまでの災害の事例などもしっかり研究させていただきなが…","id":"exchange-025"},{"speaker":"つる委員","kind":"確認","question":"災害廃棄物処理計画ですが、ざっとしかまだ確認できていないのですけれども、災害廃棄物処理計画の中に動物に関する記述があるのか説明を求めました。","respondent":"平原防災課長","answer":"計画中に、特に動物というような形で特定して記述したものはございません。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"どうしてもここになってくるわけですけれども、動物に関する記載を、どの段階で反映していくのかなと。例えば反映していくものなのかどうかということも含めて、現段階での考え方とか方向性があれば、説明を求めました。","respondent":"平原防災課長","answer":"どう対応していくかというところを、別な形で対応していくことがよいのかというのは、そういったところをしっかりと研究して対応できるようにしてまいりたいと思います。","id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"逆に、今、さっき少し揺れが、千葉の震度３があって、ここも少し揺れた。起因するものが災害だったとしても、そうしたペットについての扱いは、現段階でどうなるのでしょうか、説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"通常の考えとしましては、いろいろ場所によって違いますけれども、対応しているというような状況です。原則、そういった対応をどういうふうに災害時において拡大をしていくかというようなことを、次回計画に対して検討していきたいというふうに思います。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"犬だけでも１万４,０００弱ぐらい、少しでも早く区民に周知できるようなことは、ぜひ考えていってほしいと求めました。すみません、あえて何か答弁があれば、お願いします。","respondent":"品川品川区清掃事務所長","answer":"やはりそういった課題点もありますので、次期計画改定に向けて検討していくことと、周知の仕方等についても同様にやっていきたいと、このように思っております。","id":"exchange-029"},{"speaker":"鈴木副委員長","kind":"質問","question":"仮置場について伺いたいのですけれども、どういうところにということが、発災してから行うということになっていくのか。２４時間後とか、最大で１３万６,０００m2が必要だと資料に書かれていたのですけれども、その点を伺いたいと思います。","respondent":"平原防災課長","answer":"１５か所ということでやっているのですけれども、検討しているところでございまして、まだ定まっているものではございません。自衛隊の方々により搬入するものになりますので、現段階で、どこが応急仮置場になりますといった計画はございません。","id":"exchange-030"},{"speaker":"鈴木副委員長","kind":"質問","question":"１５か所というのは、おおよそここら辺というのは決められているのか。この２５３m3の体積としても減っているのかなと思うのですけれども、されているのかどうか分からないのですけれども、その点も伺いたいと思います。","respondent":"平原防災課長","answer":"今、正にそういった検討を進めているところです。ということもございまして、現行計画を基本的に維持するような方向で、今後の処理方針を決めていくような形になるかと考えています。","id":"exchange-031"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"その中で１つだけ確認させていただきたいのが、固形化して焼却処理が難しくなるため、早期に収集・運搬する必要がある。そういう周知もすごく必要なのかなというふうに思ったのですけれども、実際問題どういうふうになるのかを伺いたいと思います。","respondent":"平原防災課長、品川品川区清掃事務所長","answer":"初動で３日目には１５か所開くというような方向で、検討を進めているのですけれども、検討を進めているところです。令和４年に作ったハンドブックから、ただ… し尿は、今は完全に委託化をしておりますので、２３区の災害対策を通じて、し尿収集車を配備するというような状況になろうかと思います。基本的には、燃えるごみ扱いになりますので…","id":"exchange-032"},{"speaker":"鈴木副委員長","kind":"質問","question":"簡易トイレをこれから１人２０個ずつ配布されますけれども、全くの燃えるごみと同じように出してしまっていいということなのでしょうか。それで、この災害用トイレの分別排出は、分別収集する必要というのは何を差しているのか、それももう少し説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"中身と外といいますか、要するに、そこを分別していただくというようなことが発生するかと思います。ですので、分けてし尿で収集する部分、それから、残った部分を可燃ごみで収集する部分と、そのような形になっていくかと思います。","id":"exchange-033"}]},{"id":"topic-02","title":"品川区地域防災計画の修正","agenda":"品川区地域防災計画の修正","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"２月５日に防災会議が行われたということで、ここでの意見とかがありましたら、どういった議論があったのかというところを伺いたいと思います。先ほど、この概要版を使ってということでご説明がありましたけれども、各地域に説明会を実施したりしていくということなのか伺いたいと思います。","respondent":"平原防災課長","answer":"前回ご説明のときからの変更点ですけれども、大きなところの変更点はございません。地域防災計画という形でご説明するのは、地域防災計画の説明というよりは、災害時の自助・共助の対応というような形になりますので。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々周知していただいて、区民が実際に発災時に困らないように周知をしていってほしいと求めました。防災会議で書面のやり取りがいろいろあったということで、もし紹介できるようなことがありましたら、どういった意見があったのか伺いたいと思います。","respondent":"平原防災課長","answer":"私の説明がいろいろな場であったような形なのですけれども、防災会議委員からの意見表明はございませんでした。例えばインフラ会社とか、そういった場でいただいているものでございまして、分かりづらい説明をしてしまいまして申し訳ございませんでした。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ、お聞きしたいことがあるのですが、欧米ではやっていないと。なぜ日本は、このままずっとやっていると思うのですけれども、ご見解を説明を求めました。","respondent":"平原防災課長","answer":"避難者数の違いがまず大きなところで考えられるかなということが１点と、もう１つは、やはり人口規模です。さらにはだんだん集約するなり、どうしても初動の段階では区立施設を前提にせざるを得ないのが正直な実情かと思っているところです。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に大都市で人口密集しているわけですから、被害を受けた人にとっては、やはり避難所は一番大事ではないですか。意見だけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-03","title":"令和６年度の防災訓練の変更","agenda":"令和６年度の防災訓練の変更","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど少しご説明がありましたけれども、今回変更した理由、そこをもう少し詳しく説明できるところがあれば、してほしいと求めました。今回、実際こういう実践的なことをしっかりやっていますよということもあるかと思うのですが、公開しない理由を改めて伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"実践的な訓練へ変更する理由ですが、１つは、こちらでより実践的な職員の対応能力が必要になったと考えられるところもあります。現場でお会いしてしっかりと対応する実践的な訓練を行う上で協力体制を組んでいくことが必要だろうというような声も上がってきたことも１つです。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり見せる訓練より実践的な訓練をやってほしいし、設備なども必要ならやってほしいし、本当にすばらしい画期的な変更だと考えています。ぜひこれにも区からの予算を使って、より的確なというよりも、必要な訓練を実践してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私は、２番目のところの各地区の総合防災訓練のところで幾つか質問させてほしいと求めました。(1)の全般のところに、当会派としましても、障害がある方が参加しやすい防災訓練の実施をというふうに要望させていただいているのですけれども。","respondent":"伊藤災害対策担当課長","answer":"別にしっかりとニーズに対応できるような形で訓練に参加ないしは見学をしていただいて、訓練の計画については検討してまいりたいと考えています。それから２点目の新たな要素を入れ込み実施する５地区ということで、訓練を実施する予定であるところをまず抽出いたしまして…","id":"exchange-040"},{"speaker":"ひがし委員","kind":"確認","question":"新しいものをやってみて参加したいなと思っていたので、その選定はどういうふうにされているのかという点で確認させていただきました。新たな視点を１か所でも何か入れますというような取組のほうがいいのかなと思うので、その点についてはいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"委員のおっしゃったように、ご指摘の「従来どおり」という言い方は、もしかしたら抵抗があるかもしれませんので、そちらは大変失礼いたしました。１３会場で訓練をやり、前回…","id":"exchange-041"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ前向きにほかの地区にも広がるようにしていただければなと思いますので、こちらは要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"新妻委員","kind":"提案","question":"この事業者による企画・運営支援というのは、これは東京都が提案をしているものを活用して品川区がやるということでしょうか。そこを教えていただきたいとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"今回の訓練につきましては、東京都の提案のものではございません。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"こういうことは関心があるかと思うのですが、なかなか参加できない日にちの設定であったりとか、そういうこともあるのかなとも思っています。そこをどう若い方を引き込んでいくのかは、そういうこともぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"私も今回の企画を説明するに当たりまして、いろいろ会長に回らせていただきまして、いろいろなご提案をいただいております。そちらと連携をしながら、親子世代を今回はターゲットにしてやろうと考えておりますが、考えながら実施していきたいと考えています。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"聞き漏らしていたらあれなのですけれども、この新たなほうの５地区で、事業者ですが、５地区それぞればらばらなのですか。一緒なのか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"もちろん日程は違いますけれども、１つの事業所に委託をしてやっていく予定です。それは開催までにどういったものができるかということは、同じ業者でありながらも、少しカスタマイズされたものになる可能性は高いと考えています。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"そういったところと連携したらどうですかと、もう１２年前ですけれども、ストラックアウトみたいなものです。そういうものとか、その他にいっぱいいろいろ工夫が当時あったのですけれども、そういうイメージか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"大声コンテストみたいな、「火事だ」というようなものもやったりだとか、いろいろ試してはいるような状況です。まだどういったものになるかはこれからの検討事項になってくると思うのですが、大きさ等々、いろいろ考えながらやっていきたいと考えています。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"スピーカーで流すではないですか。１,０００軒ぐらいポスティングして、こういうイベントやるので、ぜひ参加するように町会から呼びかけてくださいというお願いをできればしてほしい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-04","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今後の区の防災対策にぜひ生かしていただきたいと思うのですが、区に生かせるようなことがありましたら、伺いたいと思います。支援の要請があったということなのですが、何か品川区との関わりといいますか、要請があった理由が何かあるのかどうか伺いたいと思います。","respondent":"平原防災課長","answer":"１月４日に支援本部を開きまして、できる支援をやっていこうという中で、現地の支援状況を。それ以降については、また随時、そこで関係ができたこともございまして、物資の追加ニーズ等々も私どもに入ってくるようになったところです。","id":"exchange-048"},{"speaker":"西村委員","kind":"質問","question":"１点、お伺いさせてください。担当課をまたいで伺っていただいているのかなと思っていまして、その辺り、庁内でどのような推進をしておられるのか説明を求めました。","respondent":"平原防災課長","answer":"その中から実際の先方のニーズに応じた形で、今回、当てはめて職員を送り出させていただいたというような状況です。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"改めて伺えればと思いますし、委員からの質問にもあったのですけれども、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"公営住宅への受け入れで、これは一時提供ではないですか。でも、特に期限の定めなくというふうに、ぜひそうあっていただきたいと思うのですけれども、その辺について、何かあれば説明を求めました。","respondent":"中村都市環境部長","answer":"公営住宅をご利用していただくのは、被災を受けた方が、復興が進んで自宅に戻れるようになるというところが本来の趣旨ですので、ただ、期限の定めはございまして、原則半年、最長で１年です。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"ご相談の上、延長とかしていただきたいと思うのですが、その点についていかがか尋ねました。","respondent":"中村都市環境部長","answer":"一度入っていただいて、帰るあてがないのに出ていってくださいということはありませんので、その辺は事情をよく聞いて、話合いでしっかりと決定していきたいと思います。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"安心いたしました。ぜひそのように進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"つる委員","kind":"確認","question":"確認、３の2)の物的支援の関係なのですが、そもそも品川区が備蓄しているものからチョイスして送っている。そこを説明を求めました。","respondent":"平原防災課長","answer":"こちらにつきましては、いずれも区の備蓄品です。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"リスト等を最初に配って、これがあるからどうですかという、いろいろな聞き方があるかもしれませんけれども。１月１０日から２月２３日までの中で、ＪＰとも２年ぐらいやっている中で、この辺はどういう仕組みになっているのか説明を求めました。","respondent":"平原防災課長","answer":"今、災害が起きたときに、避難者分がありませんというような状況には至ってはおりません。〔「有効活用」と呼ぶ者あり〕 大変申し訳ございません。有効活用品を様々訓練等々で出しているところを、今回は支援物資という形で出させていただいたというような活用をさせていただいたところです。","id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"それの入れ替えのタイミングが、年度ごととか、いろいろな物によっての入れ替えの期限があろうかと思うのです。もう既にあるのだというふうに理解しているのですけれども、それはどういうふうにして、正に区としての備蓄をしていくのか尋ねました。","respondent":"平原防災課長","answer":"もう備蓄品ではなくて、有効活用した分だけ区民の災害対応力が減ってしまうという形になりますので、そういう対応をさせていただいているところです。有効活用のところから支援させていただきましたので、区の備蓄数量という形では…","id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"自分たち、今、在宅避難となっているから、どうやってそこに取りに行ったらいいのだろうというご質問などを聞くわけです。要望で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"提案","question":"少し提案も含めてなのですけれども、能登半島地震で、その災害を免れた器の展示会等を各地でやっていますというニュースを見ました。２７日までですか、区としても、どうか尋ねました。","respondent":"平原防災課長","answer":"今回ご意見があったというようなことをしっかりと所管部署に伝えさせていただきまして、様々な支援につながるように、庁内でまた検討させていただければと思います。","id":"exchange-058"},{"speaker":"こしば委員","kind":"質問","question":"３件の申込みがあって、１件、こちらは被災地の方にはどのように案内をされているのか尋ねました。","respondent":"中村都市環境部長","answer":"こちらは、区のホームページは当然載せておりますが、あと、東京都を通じて、被災地の石川県のホームページにも載せておりまして、品川区と石川県でお互いに見られて、リンクをしている、そういうような形になっております。","id":"exchange-059"},{"speaker":"こしば委員","kind":"質問","question":"この申込みが３件だったので、そこまでの移動をどうするのかということも関わってくると思うのですけれども、その辺りを教えてほしいと求めました。","respondent":"中村都市環境部長","answer":"今は１０件提供している中で３件ということで、まだ今後、まずは公営住宅で対応するという形が適切なのかなというふうには考えております。ホームページで石川県からも見られますし、そういった形で探すことには…","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/949666?Template=document&Id=6650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":57548,"voices":167}},{"id":"r06-20240229-10","meetingId":"r06-cm02","date":"2024年2月29日","dateIso":"2024-02-29","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今週の月曜日に安藤委員にお渡ししまして、あとは共産党で一部修正するのか分かりませんが、それで各会派にお願いに上がるという話は聞いております。今はそういう状況ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"作っておりますけれども、皆さんにも提案者になっていただけるように調整や事前の情報提供もしまして、ぜひ議会として出せればいいと思っています。共産党としてその中に名前を連ねるというのはもちろん当然のことだと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、やっぱりオール議会で出すのがベストだと思っているので、それに向けてまず案文を作っているということなのです。議会としての対応を求められているところでもありますから、ぜひご検討いただきたいということで、案文を作成しています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=5540#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2146,"voices":21}},{"id":"r06-20240304-3","meetingId":"r06-c-budget","date":"2024年3月4日","dateIso":"2024-03-04","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を185件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"こんの副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"歳出予算全般と、８１ページ、商店街ステップ・アップ支援事業についてお尋ねさせてほしいと求めました。しかし、事務事業評価による予算の削減とは言えないと思いますけれども、お考えを説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価によります予算削減の考え方といたしまして、数量等の見直しを行いまして、予算案に反映させたところです。今回の補正予算におきましても不燃化特区支援事業が減額補正となっておりますけれども、その目的に対する有効性なども勘案いたしまして。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"まさに行政の無駄をなくす取組を実践されたということでは、事務事業評価からの予算編成の一連の流れを私は大変評価しております。その中で確認をさせていただきたいのですけれども、改めて事務事業評価の目的を教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価の目的についてのお尋ねです。事業の不断の検証・見直し・改善等を進め、「区民の幸福」の視点から真に必要な行政サービスに資源を振り向けることを目的としております。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"確認","question":"事務事業評価の目的を確認させていただきました。２０億円の財源を捻出されたということですけれども、その辺をどういうふうにお考えなのか、お尋ねしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"行政活動の透明性の向上と説明責任を果たしていく上でも、事務事業評価の結果を分かりやすく周知していくことは非常に重要だと考えておりますので、内容についてはしっかりと検討してまいりたいと考えております。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次は、８１ページ、商店街ステップ・アップ支援事業についてお尋ねさせてほしいと求めました。つまり、一件の申請もなかったということだと私は認識しているのですけれども、その原因として何を考えているのかというお尋ねをしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"後継者育成支援事業ですけれども、この中で金額としまして、やはり若手経営者たちが企画するようなイベントに使えるような予算になってあります。まだ令和５年度の中で、コロナが明けて大変だということで、事業の申請がなかったです。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、２件を予定していたのだけれども一件もなかったということだと私は思っております。商店街に対して、当初どのような事業のＰＲをしていたのかというのもお聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"今年も２月８日・９日に実施しましたけれども、商店街の代表者を集めたような助成金の説明会、制度の説明会というものをやってあります。こういう中で、商店街に使っていただけるような施策を改めて説明したり、区で補助金の申請のお手伝いなども含めてご説明している段階です。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問","question":"コロナが５類になって、いろいろな商店街でも、お客様が来場されるという中で、今後、補助金が適当に使われるように、どのような事業改善を行っていくのかというのをお聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"商店街の支援です。全体の説明会だけではなくて、また引き続き丁寧にご説明し、支援してまいりたいと考えております。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ丁寧に説明していただいて、来年度、より一層、商店街対策、活性化に向けて取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"提案","question":"私からは、３８ページ、特別区民税、７３ページ、区立保育園費、７５ページ、私立保育園費についてお伺いしてまいります。オンラインによる申請受付を提案させていただいたところ、区の見解として、早期に電子申請を受け付けることができるように進めていく」とありましたとの意見を述べました。","respondent":"提坂税務課長","answer":"現在は、納税・課税証明のオンライン申請受付業務を令和４年１２月から開始してございまして、着実に件数が増えているところです。ほかの業務についてもオンライン化を進めていく予定ですけれども、また、オンライン化へ向けた研究をしてまいりたいと考えています。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"迅速に重要性を確認されていることなので、今後さらに進めていってほしいと求めました。被災者の罹災証明により受けることができる区民税の減免措置のオンライン化を求めますが、改めて区の見解をお聞きしたいと思います。","respondent":"提坂税務課長","answer":"令和７年１２月以降に、いわゆるｅＬＴＡＸと申しますけれども、導入する予定で準備を進めているところです。それに併せて、公的支援に関する減免申請等についても研究を重ねてまいりたいと考えています。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"続いて、７３ページ、区立保育園費、７５ページ、私立保育園費に関連して、保育園の延長保育についてお伺いしていきます。区では、区立保育園の民営化など様々な対策を取られていると思われますが、この点についてお考えをお聞きしたいと思います。","respondent":"立木保育課長、石井保育支援課長","answer":"ニーズの部分に関しましては、子ども・子育て支援事業計画等の中でも今後検討していく内容かと考えています。そうした中で、今後、区立で対応できるかどうかというのは検討してまいりたいと考えています。 私立保育園における早朝保育につきましても、やはり子育て負担の軽減というものはとても大事なところですから、補助金の範囲内で実現できるように、各私立園にも呼びかけてまいりたいと思ってあります。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"誰一人取り残さない施策を進めてほしいと求めましたが、今後、区立と私立、連携といったところも、関連を強めていってほしいと求めました。再度、改めて区の見解を頂ければと思います。","respondent":"石井保育支援課長","answer":"今後、区立保育園、私立保育園をめぐる状況については、ただいまいろいろ議論していますけれども、これまで以上に、より一層連携を密にしながら、様々な保育ニーズに応えていけるようにしていきたいと考えています。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"私からは、６３ページの公共施設整備基金積立金、６５ページの庁舎整備基金積立金について伺います。当初の工事代金の見積りから、実際に支払った金額は上昇していますか尋ねました。","respondent":"遠藤財政課長","answer":"令和３年度・４年度は、決算数値ということで確定しておりまして、令和５年度は見込みという形で出させていただいているところです。当初予算で８９億円ほど取り崩すというような形でさせていただきまして、きゅりあんなど、金額が減っているようなところがあるというのが現状で…","id":"exchange-013"},{"speaker":"山本委員","kind":"意見","question":"要因について理解いたしました。同資金は、今後の大型公共施設更新の見通し、その更新に係る資金計画に対する現状の積立金残高の認識についてお教えくださいとの意見を述べました。","respondent":"遠藤財政課長","answer":"あるいは福祉施設、保育園など、老朽化を認めているところがかなりあるというところでは事実です。そちらを勘案しながらという形になりますけれども、こちらの部分、積立金が枯渇するようなことのない形で進めているところです。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問","question":"現在の品川区公共施設等総合計画では、大阪万博の当初予算と同じ２０１７年に策定しており、策定当時からは大幅な上乗せが必要となると考えます。積立金目標額の機動的な見直しが必要であると考えますが、ご見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"令和６年度の改定に向けまして、改定作業を進めておりまして、２月には計画素案のパブリックコメントを実施したところです。社会情勢の変化、法改正等によりまして、計画の前提条件が大きく変わる場合につきましては適宜見直しを行ってまいります。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"今まさにパブリックコメントなどをやりながら検討を進めていくというところで理解いたしました。民間活力の活用などで、公共施設建て替えに係る財政上の負担軽減に対する工夫が必要と考えますが、併せてこの点についても区のご見解を伺います。","respondent":"吉岡政策推進担当課長","answer":"先ほど申し上げた公共施設等総合計画における方針の中で定めているとおり、引き続き民間活力の活用につきましても幅広く検討いたしまして、効果的・効率的な施設整備を進めてまいります。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"来年度以降の策定予算範囲を要望して、次の質問に移ります。令和６年度まで３０億円ずつ積み立てるという方針のようですが、その後の基金の積立て方針の検討状況についてはいかがか尋ねました。","respondent":"遠藤財政課長","answer":"令和６年までに１２０億円という形で、こちらは決まっておりまして、今のところ進めているところです。金額が変わったというところになりますので、そちらにつきましては改めて検討という形で、今の段階で特に決まっているというものはございません。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"国と都の分担金、国の補助金を除いた時点で、現時点での区の想定負担額はどの程度であるとお考えでしょうか。お考えを説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"現在、区分所有の割合は調整中ではありますけれども、おおむね、お見込みのとおり、国と東京都の費用負担は２割程度を想定しています。補助金につきましては、防災機能の強化によるものなど、積極的に活用を検討してまいりたいと考えているところです。","id":"exchange-018"},{"speaker":"山本委員","kind":"提案","question":"将来の不確実性を回避するため、令和６年度から積立金の増額をするのはいかがでしょうか。グリーンボンドの活用に対する区のご見解を伺いますとの意見を述べました。","respondent":"遠藤財政課長","answer":"一方で、プロジェクトというところでの評価基準や透明性というところで課題もあるのかと感じているところです。そういう部分で、今度こちらについては研究を重ねていきまして、進めていきたいと考えているところです。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"専門家のアドバイスを活用し、より具体的な検討を進めていくことを要望して、私からの質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"８５ページの不燃化特区支援事業、８９ページの住宅・建築物耐震化支援事業について、耐震化の促進を求めて質問します。併せて伺います。","respondent":"北原河川下水道課長","answer":"既に耐震性を有するなどの理由で、対策が必要な管渠が想定より少なく済んだため、減額補正を行ったものです。必要な箇所に対策を講じているという意味でして、計画が遅れているということではございません。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"上水道断水率が３０.２％、下水道被害率は６.４％となっており、避難生活が大きく改善することにもなります。上下水道の耐震化の費用というのはどのように捻出されているのか、伺います。","respondent":"北原河川下水道課長","answer":"下水道の費用についてですが、下水道料金、あと東京都の都費、あと国費も投入して事業をしているという認識です。水道については、あまり我々の所管でないところもありますが、水道料金等を投入しているものと認識しております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"本年度から３年分の特別区長会の要望事項を確認してみたのですけれども、下水道の耐震化については、要望項目に記載がありませんでした。区が２３区で連携して要望しているというのは、どういう形で何を要望したのか尋ねました。","respondent":"北原河川下水道課長","answer":"２３区では下水道事業の促進のために特別区下水道事業促進連絡会というものをつくっておりまして、そちらで東京都副知事と、あと下水道局、あと国にも事業の促進について要望しています。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"促進連絡会で要望しているということで、それは何を要望したのかというところで伺ったので、答えてほしいと求めました。それと、直近では、いつ要望したのかというところも伺いたいと思います。","respondent":"北原河川下水道課長","answer":"要望の内容についてですが、下水道の浸水対策の促進、老朽化対策の促進、災害・震災対策の促進、あと水質改善に取り組むこと、あと財源を確保することという要望をしておりまして、東京都に関しましては昨年１１月８日に要望活動を行っております。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"老朽化・震災対策についても要望されているということで、さらに公費を投入して進めていただきたいということで、要望していただきたい。実際、今、区内の上・下水道の耐震化をいつまでに１００％にする計画なのか、伺います。","respondent":"北原河川下水道課長","answer":"要望の中で、必要な措置を講ずることを要望しておりますので、引き続き要望をきちんとしていきたいと考えております。１００％という計画ではございませんが、対象施設や地区を重点化するなど、計画的に事業を行っていくものと認識しています。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、被害軽減のために耐震化を進めていくということが有効だと思いますけれども、いかがでしょうか。やはり区民生活がかかっているわけですから、１００％を目指すことを求めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"区内の水道施設や下水道施設の耐震化が早期に進むこととしては、区も重要と考えておりますが、都としても計画的に進めていると認識しておりますので、今後も引き続き情報収集に努めるとともに適切に対応してまいりたいと考えております。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ進めてほしいと思うのですけれども、現在、課題は何か、伺いたいと思います。ほかのところに回していただきたいということで、そこへ回していただきたいと思うのですが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"今回の耐震事業での減額の主な理由としましては、緊急輸送道路沿いの改修工事、あとは木造住宅の除却助成の減額となった……。〔時間切れにより答弁なし〕","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"６７ページの区民保養所経費、あと８１ページの中小企業活性化事業費、関連してお伺いいたします。令和５年度全体の補正予算なのですけれども、当初予算との比較、いわゆる当初予算との精度についてどうお考えなのか。","respondent":"遠藤財政課長","answer":"令和５年度の補正予算の考えですけれども、どちらかといいますと、既存事業の部分の収支を合わせるという部分が多くなっております。いわゆる国からの重点支援地方交付金などもありまして、補正予算の数といたしましては…","id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"改めてその確認と、現時点でどの程度お考えなのか、説明を求めました。","respondent":"遠藤財政課長","answer":"キャッシュレス決済ポイントなどをやらせていただいて、区民生活の部分について当初から切れ目のないような形で実施させていただいているところです。こちらは速やかに、また議会でご審議いただくような形で、引き続き進めていきたいと考えているところです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"適宜、対応をよろしくお願いします。それで、区民保養所に移りますけれども、２,６２３万円が減額されておりますけれども、これは一体どのような理由なのか、お知らせください。","respondent":"宮澤地域活動課長","answer":"各種設備に対しまして更新する必要性がありまして、工事に向けた設計委託に入る予定として、予算を計上していたところです。保養所につきましては、今後の方向性というのを改めて検討するというところから、その残額を減額補正したものです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"提案","question":"私としては２０１５年の第３回定例会の一般質問から予算特別委員会、５回ほど、保養所の売却ということを提案しています。令和１０年３月に更新しないかもしれないということを見込んで、ぜひご検討いただきたいと考えておりますけれども、区のご見解をお伺いいたしますとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"コロナ前と比べまして今年度、コロナ前以上の水準で客室が稼働しているというところで、一定の区民ニーズというのはあるのかと考えているところです。先ほど答弁しましたとおり、施設維持につきましては必要最小限というところで絞っておりまして…","id":"exchange-031"},{"speaker":"筒井委員","kind":"意見","question":"続いて、中小企業活性化事業費、商店街活性化事業費なのですけれども、かなり減額されております。そのほかの中小企業活性化事業費の減額などは、一体どのような理由で減額になったのか、お知らせくださいとの意見を述べました。","respondent":"小林商業・ものづくり課長","answer":"この部分につきましては、８１ページに記載がありますとおり、事業承継支援事業です。令和５年度もなのですけれども、この部分については助成金の執行はなくて、ここの部分を減額させていただいたところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。投資について具体的なお話が出なかったということは、先方があまり積極的ではなかったという理解でよろしいのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"ご指摘のとおりでございまして、相談事業やセミナーというのは我々開催しておりまして、こういったものはふだんから相談会等やっておりますけれども、事業承継に合わせて、設備投資も含めて一緒に事業承継をやるというような話が、令和５年度においてはなかったです。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"設備投資に併せてやるのは、あまりお声がなかったということで、あまりそこまで経営面的に余力がなかったということなのでしょうか。３月１５日までに導入および支払い完了というのが要件になっているかと思うのですけれども、そして、お知らせください。","respondent":"小林商業・ものづくり課長","answer":"こちらは令和５年度において補正予算事業として実施した事業です。主に商店街の飲食店などに使っていただくことが多かったと認識しておりますけれども、規模を、やりやすかったというお声を頂いたところです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"でこの事業を知らないという方もおりましたので、広報の在り方、どのように周知をされたのか。もう少ししっかり丁寧にやっていただきたいと思っているのですけれども、その点、周知の在り方についてお伺いいたします。","respondent":"小林商業・ものづくり課長","answer":"区内の事業者に全部まいている情報がありますけれども、プラスしてツイッターといったものも併せて、支援ということで情報提供をしてきたところです。経営支援窓口の中でも、それが当初考えていた３００件を超えるような…","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"新しい多様化の時代ですから、多くの中小企業、個人事業者の方々の支援策をぜひ検討していっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"この間食の費用について、区と児童側ではどのような負担割合になっていますでしょうか。間食を提供しないＡ登録と、間食を提供するＢ登録およびＣ登録の割合を伺います。","respondent":"藤村子ども育成課長","answer":"こちらにつきましては、新型コロナウイルス関連の消毒液等が不要になりましたという関係で、マイナス補正という形になっています。全学年で６２.７％という形になっておりまして、割合としては今、全体としては９０％程度〔同日後刻に「６割程度」と答弁訂正あり〕となっていま…","id":"exchange-037"},{"speaker":"せらく委員","kind":"確認","question":"間食の負担割合は、全額区で負担していただいているということで確認いたしました。質問の意図としては、お伝えしておきたいのですけれども、仕出し弁当を公費で提供してほしいという意図ではないということは先に申し上げします。","respondent":"藤村子ども育成課長","answer":"先ほど申し上げた、Ａ登録の割合は６割程度というところでした。お子様を６時以降お預かりする際に、少しでもすまいるスクールでの時間を楽しんでいただくということを目的に提供しています。","id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"業者委託ですと、飲料とスナックなどで寂しいメニューになっているということが、確認が取れました。そこで、間食の内容について、児童や保護者などにアンケートやニーズ調査を行ったことがあるか、伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"間食に限定してではないのですけれども、すまいるスクールの運営の中で、何かご要望等はないかというようなアンケートというのは取っているような形になっております。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"次に、一時保育について伺います。こちらは今回もマイナス補正ということで、内容を伺います。","respondent":"立木保育課長","answer":"委員がおっしゃられた一時保育に関しましては、現在、ＬＩＮＥで利用の申込みができるようになってあります。利用割合につきましては、今、正確な数字は出ていないのですけれども、電話ではなく、ＬＩＮＥ利用のほうが多く、ほぼそちらになってあります。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問・要望","question":"ＬＩＮＥと電話での申請では、目標としてもやはりＬＩＮＥや電子申請のほうをメインに使っていただきたいという思いなのでしょうか。区内でも様々なところでキャッシュレスの対応が進められておりますが、一時保育の支払い方法は、現在は現金のみか尋ねました。","respondent":"立木保育課長","answer":"利用の優先順位のほうは、一応、ＬＩＮＥでお申込みいただいた方を先に調整するというようなやり方で、ＬＩＮＥの利用の推進を進めているところです。キャッシュレスでの収納に向けて、条件整備をしておりまして、今後取り組んでまいる予定です。","id":"exchange-041"},{"speaker":"せらく委員","kind":"確認","question":"なかなかホームページ上で情報が確認できず、保育課長、保育支援課長より教えていただきました。こちらの区としての支援の方向性を最後に教えていただけたらと思います。","respondent":"石井保育支援課長","answer":"令和５年度よりリフレッシュでも、私立保育園で一時預かりができるようになりました。当然、多くの方のニーズがありますので、情報提供をホームページ等々で積極的に発信できるように工夫してまいりたいと考えています。","id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"そこで、まず企業のデジタル化の動向について伺います。産業ロボットや自動装置等に対して３００万円、この事業の目的や、助成金以外の支援も行っているかなど説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"これは８回連続ですけれども、あるいは企業に直接、専門家派遣を行うなどの支援も行っているところです。こうした取組を通じまして、引き続き区内中小企業のＤＸ化あるいは生産性向上、企業競争力の強化というものを進めてまいりたいと考えています。","id":"exchange-043"},{"speaker":"澤田委員","kind":"質問","question":"経済分野のデジタル化に関連し、続いて商店街のデジタル化についても伺いたいと思います。現在、品川区では６月１日から６月３０日を実施期間として、こちらの現在の準備状況やスケジュールを説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"６月１日から６月３０日までで実施予定ということで、ＰａｙＰａｙ、楽天ペイと連携したポイント還元事業ということで実施することとしております。ポイント還元額５億円を予定しておりまして、還元率２０％ですから…","id":"exchange-044"},{"speaker":"澤田委員","kind":"質問","question":"先日の一般質問でも、せりざわ委員からも質問があり、改めて品川区としてデジタル商品券の導入に関する検討状況などについて説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"一方で、店舗側の換金手数料負担や、あるいは先行自治体の例を見ますと、高齢者の方などデジタル化対応が困難な方への配慮といった課題もあります。先行事例の調査分析をきちんと行いながら、発行主体である商店街連合会との間で具体的な協議を進めてまいりたいと考えています。","id":"exchange-045"},{"speaker":"澤田委員","kind":"質問","question":"スマートフォンを活用したデジタル商品券の対応より、慣れ親しんだ紙商品券のほうが安心して使いやすいという認識があるからとも伺っております。新宿区以外の大都市などでもデジタル対応が必ずしも進んでない状況もあるようですから、品川区においても。","respondent":"川原高齢者地域支援課長","answer":"そして、はじめてのスマホ教室におきましては、令和５年度は４か所で実施、よろず相談においては５か所で実施している状況です。区といたしましては、スマホ初心者の高齢者に対しての活動を支援すべく、またフレイル予防、社会参加の支援も含めて、今後も実施していく所存です。","id":"exchange-046"},{"speaker":"澤田委員","kind":"質問・要望","question":"高齢者に対する現在の取組に加え、今までのスマホ教室の内容にとどまらず、こうした応用的な操作方法も教えていただくことは大切だと考えています。買物やクーポンの利用なども使いこなせるように、スマートフォン教室の内容の拡充を求めたいと思いますが、区のお考えを説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"高齢者ご自身のご判断に基づくものがやはり必要となってくると考えてございまして、このような個別対応とさせていただいているところです。高齢者のスマホ教室について、令和６年度も新たに教室を拡充して実施するなど…","id":"exchange-047"},{"speaker":"澤田委員","kind":"質問・要望","question":"現在でも個別の要望に対して対応してくださっているということで安心いたしました。先日、東京都独自のデジタル地域通貨プラットフォーム、仮称「Tokyo Tokyo Point」についてお伺いします。","respondent":"横田情報推進課長","answer":"区といたしましては、これまで、都のスケールメリットを活かしたデジタル地域通貨の実現について要望してきたところです。区が実施予定のデジタル商品券の状況、他区の動向などを踏まえまして、デジタル地域通貨について検討を進めてまいります。","id":"exchange-048"},{"speaker":"澤田委員","kind":"質問","question":"私からの質問は以上となります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"横山委員","kind":"質問","question":"私からは、６３ページ、国際交流推進事業、６７ページ、区民まつり経費、時間があれば７３ページ、児童相談所移管推進事業についてお伺いいたします。１点目に、国際交流推進事業についてお伺いいたします。","respondent":"勝亦総務課長","answer":"内訳といたしましては、友好協会で実施予定でありましたオークランド市からのホームステイの受け入れ、減額補正をしたものです。いずれも、先方の市で実施ができないと連絡があったため、中止しています。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"より効果的に多文化共生理解の促進や国際交流事業の前進につなげていただきたいと要望いたしますが、区のご見解をお聞かせください。２点目なのですけれども、区民まつり経費についてお伺いいたします。","respondent":"勝亦総務課長、宮澤地域活動課長","answer":"そういった中で姉妹都市以外との、国や都市との交流といったものも重要だと考えています。今後も様々な交流を図っていくために、今頂きましたような情報収集に努めて、国際交流の発展に努めてまいりたいと考えております。 区民まつりの減額の理由です。新型コロナウイルス感染症対策ということで手指消毒剤を予算計上していたところですけれども、５類移行に伴いまして、執行しなかったものです。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"新たにスタートする情報通信業は、特にスピードが求められると思いますが、多文化共生の学びの機会につながっていると考えています。現在、例えばアンケートなどで多文化共生理解に関する意見をお伺いして、品川区国際友好協会との連携を深めることのできる機会はありますか尋ねました。","respondent":"勝亦総務課長、宮澤地域活動課長","answer":"現在、実施しております交流以外にも、文化、スポーツ、教育等、いろいろ様々な交流の形があろうと考えております。具体的には、ＬＩＮＥ等を配信していますので、そういった中でアンケート等を取っていければと考えています。 その中で、熱中症対策というところに関しましても、今年度も１０月に時期をずらして実施しています。開催の時期をずらしたり、開催時間を３時以降などに遅くするというふうに検討を進めていると、実行委員会から聞いているところです。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"８９ページ、内容をお聞きしながら、また関連して伺ってまいりたいと思います。初めに、８５ページの水辺利活用事業から伺ってまいります。","respondent":"北原河川下水道課長","answer":"照明機器は設置できるものの、一部の工事を来年度実施することとしたため、減額としているものです。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"水辺利活用に関連いたしまして、ここで桟橋の整備について伺わせていただきます。そこで、桟橋の整備について伺います。","respondent":"北原河川下水道課長","answer":"こちらの桟橋についてですが、民間が設置した非動力専用の桟橋ということで、平成１８年に設置して、現在、１８年が経過していると認識しています。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"勝島運河周辺は、令和８年度に向けて人道橋の設置が進んでおりまして、また翌年には花海道の整備も進んでいます。品川区ができることをぜひお取組を頂きまして、改修を視野に入れて検討してほしいと求めましたが、見解を伺います。","respondent":"北原河川下水道課長","answer":"先ほどもご説明したように、まずは設置した経緯をもう少し詳しく調べたり、老朽化の状況等の確認を進めているところであります。今後も地元関係者の意見も伺いながら、また関係部署とも調整を図りながら、適切に対応してまいりたいと考えております。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"今日はご発言がありませんが、渡辺議長と共に、またこういうお声も一緒に頂いておりますので、ぜひ推進してほしいと求めました。こちらもマイナス補正で少し金額が大きいこともありますので、この内容をお聞きいたしまして、スケジュールへの影響を伺います。","respondent":"高梨公園課長","answer":"事業者が決まったことで、設計業務の全体工程が明らかになったことにより、今年度実施する業務の執行見込みに合わせて減額補正をするものです。当初計画していた入館者数を上回り、収入増が見込まれるために、それに合わせて減額補正をするものです。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"スケジュールへの影響はないということを確認いたしました。先ほどは勝島運河の桟橋についてお聞きいたしましたが、この桟橋としながわ水族館の関連性について伺ってまいります。","respondent":"高梨公園課長","answer":"今ある資源をしっかりと活用して、水辺からの集客といったところもしっかりと検討していこうということを考えてあります。訪れる来館者の皆様に、海からのアクセスもしっかりあるのだといったところが分かりやすく広報できるような形で検討を進めてまいりたいと思います。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこはぜひお願いしたいと思いますし、また家族連れではない、ぜひそういうことも検討してほしいと求めました。併せて、区民の声をどのように反映させていただけるのか、お伺いいたします。","respondent":"高梨公園課長","answer":"品川駅の水族館と混同されることのないよう、しっかりと独自性を出してリニューアルしてまいりたいと考えています。区民から展示についてのアイデアを募集して、それを展示に活かし、区民の方々と一緒に水族館をつくってまいりたいと考えているところです。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"現在ある東京都品川児童相談所に職員を派遣して引継ぎに当たるとお聞きしましたが、現在の施設からの職員の異動はないのでしょうか。以上、４点お伺いします。","respondent":"長谷川児童相談所開設準備課長","answer":"医療的ケアの子どもの対応につきましては、児童相談所の一時保護所においては、そういった場合には障害児施設等の利用を検討するといった状況です。児童相談所に係属する子どもが１８歳未満のお子様になりますので、教育委員会との関係性は非常に重要だと捉えております。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問・要望","question":"子どもや家庭の相談を受け付ける手順や、問題解決のためのケース管理プロセスなどはあるのでしょうか。最後に、様々な深刻な問題に直面する職員の方の心理的な負担に対してのケアは、どのように考えられているのか尋ねました。","respondent":"長谷川児童相談所開設準備課長","answer":"その中の手順に沿って対応することになろうかと思いますが、その都度、方針等を決定していきたいと考えているところです。全庁的な支援体制である看護師の活用はもとより、支援者支援の立場で、ケアする人間のケアということも注視していきたいと考えています。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"質問","question":"事業見直しや変更などでしょうか。様々な理由があると思いますが、まずは理由を説明を求めました。","respondent":"北原河川下水道課長","answer":"減額になった主な原因ですけれども、主には、目黒川でしゅんせつ工事、支障物撤去工事を行おうと当初予算時に考えていたのですが、建設局が行う工事と競合したため、規模を縮小して実施した等の理由によります。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"立会川の水質浄化機器運転費が、令和４年度にリースから買取りになったと資料にありましたが、そういった変更はよくあるのでしょうか。水質浄化の状況について説明を求めました。","respondent":"北原河川下水道課長","answer":"こういった変更はよくあるものではないのですけれども、当初令和３年度と言っていたものが令和９年度に変更となったというのを鑑みまして。水質についてですけれども、これを設置した平成２０年以降、水質がある程度保たれていることからも、効果があるものと認識しています。","id":"exchange-062"},{"speaker":"おぎの委員","kind":"質問・要望","question":"水辺のまち、品川区として、区でできることを根気よく続けていってほしいと求めました。質問は以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"えのした委員","kind":"質問","question":"私からは、７５ページのベビーシッター利用支援事業についてお伺いします。事業概要をお知らせください。","respondent":"石井保育支援課長","answer":"本事業は、ベビーシッターの利用料の一部を助成して経済的な負担軽減を図るものです。令和４年度より、東京都の補助を受けて実施しています。","id":"exchange-064"},{"speaker":"えのした委員","kind":"質問","question":"そこでお伺いします。補正予算が１億７,１２０万円と、３.８倍以上の補正予算になっておりますが、当初予算の考え方をお知らせください。","respondent":"石井保育支援課長","answer":"実際には令和４年度年度後半の伸びが著しく、令和４年度は１７０名程度の目標を掲げておりましたが、実に１,０００名以上のご利用がございました。当初予算の算定時にはそこまでの状況が想定されず、今回の補正予算となったものです。","id":"exchange-065"},{"speaker":"えのした委員","kind":"質問・要望","question":"当初は１７０名程度の見込みが、５.８倍以上、１,０００名の利用と、実績やニーズの高さが伺えました。されていない場合は要望いたしますが、区のご見解をお知らせください。","respondent":"石井保育支援課長","answer":"令和５年度においては、当初予算および補正予算を合わせて２億円を超えるものです。区としても、特別区長会が取りまとめております令和７年度東京都に対する予算要望事項として上げさせていただいているところです。","id":"exchange-066"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、ベビーシッターの確保についてお伺いします。実績を踏まえると、ベビーシッター利用支援は非常にニーズが高まっておりますが、ベビーシッターの人数は現状足りているのか尋ねました。","respondent":"石井保育支援課長","answer":"ベビーシッターの人数につきましては、現在、利用者の方々からも十分でないというお声を頂いております。本事業に従事できるベビーシッターの増員に向けて、例えば夜間や土日も含めた研修の実施などを柔軟に行う等、確保策に努めていると聞いてあります。","id":"exchange-067"},{"speaker":"えのした委員","kind":"質問・要望","question":"区民の方から十分でないとのお声があるとのこと、研修の実施も含めて優秀なベビーシッターの育成と増員を要望いたします。病児保育施設にとらわれずに、ベビーシッターも含めた様々な預け先を進めていくことが重要だと考えますが、区のご見解をお知らせください。","respondent":"石井保育支援課長","answer":"そういったベビーシッターの事業者にも活用していただけるものですので、区としてもこういった助成を利用していただけるようにＰＲしてまいりたい。そういう中で、病児保育施設に限らず、様々なニーズにお応えできたらと考えています。","id":"exchange-068"},{"speaker":"えのした委員","kind":"質問・要望","question":"病児保育施設の設置、また本事業のＰＲの拡充も要望します。周知方法についてお知らせください。","respondent":"石井保育支援課長","answer":"現在、区のホームページや各種刊行物、しながわこどもぽけっと、産後ドゥーラなど、連携した周知を行ってあります。妊娠届を出された方向けに、ご案内のリーフレットの配布等もしています。","id":"exchange-069"},{"speaker":"えのした委員","kind":"確認","question":"昨年の１０月２０日ですか、私も確認しましたが、大変評価しております。人材バンク、人材マッチングアプリ等を利用した仕組みづくりはどうお考えか尋ねました。","respondent":"石井保育支援課長","answer":"法令上、本年１０月より児童相談所を開設した後は、品川区に事業者の指導監督権限が下りてくるところです。そういった状況も踏まえまして、まずきちんと指導・監督できるような体制を整えていくことが肝要だと考えています。","id":"exchange-070"},{"speaker":"えのした委員","kind":"意見","question":"児童相談所が開設された後は、国からも指導・監督権限が下りてくるので、そういったことを踏まえて対応してほしいと求めました。コストを抑えた病児保育、保護者の自宅療養が可能になるのではと考えますが、区のご見解をお知らせくださいとの意見を述べました。","respondent":"石井保育支援課長","answer":"例えば実施スペースの確保や、ベビーシッター全体の確保といったことで課題があると考えていますが、今後も様々な子育てのニーズに応えていけるように体制を整備してまいりたいと考えています。","id":"exchange-071"},{"speaker":"えのした委員","kind":"質問・要望","question":"区民の方への安心安全な保育、また子育ての負担を軽減できる事業の安定と拡充を要望して、私からの質問を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"８９ページの応急活動対策費に関連して、災害時のペット同行避難および同伴避難、そしてキッチンカーについて伺いたいと思います。新年度予算では様々示されておりますが、直ちに活かすという姿勢や具体化について、最終補正で追加は考えられなかったのか、伺いたいと思います。","respondent":"平原防災課長","answer":"令和５年度予算につきましては、今回減額をお願いするものを除きまして、当初予算を着実に執行しています。今、令和６年度当初予算案に計上させていただいたところです関係で、今回の補正で特に追加支出ということは考えていないところです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、パンフレットの作成や品川区ホームページの充実を求めますが、いかがでしょうか。ペット防災計画がなぜ進まないのか、課題が何か、伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そちらに関しては区としても認識しています。避難所運営マニュアルの見直しも図ってまいりますので、全ての避難所でペットの受入れができるような体制を整備してまいりたいと思います。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も話を伺いましたが、玄関先で知らない人や物音がするだけで警戒するので、多くの方が行き交う避難所で過ごせるのか不安で仕方がない。様々な問題を整理して、例えば審議会なども立ち上げて、本格的にペット支援を体系立てて作成してほしいと求めましたが、改めていかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"ペット同行避難に対する今後の対応についてですけれども、地域の皆様の意見を十分お伺いしながら体制を進めてまいりたいと思います。その１つの手法といたしましては、避難所連絡会議の場で様々意見をお聞きしながら、地域の方の理解を深めてまいりたいと考えております。","id":"exchange-075"},{"speaker":"中塚委員","kind":"提案","question":"私は、保護犬の活動や被災地支援を行っているドッグトレーナーとの意見交換を提案したいと思います。ドッグトレーナーとの連携も位置づけて、ペット支援を具体的に進めてほしいと求めましたが、いかがか尋ねました。","respondent":"舩木生活衛生課長","answer":"日頃からの犬のしつけやマナーにつきましては、犬のしつけ方教室ということを年２回開催しておりまして、約４０人の参加者の方を得ております。どういった専門家の活用が図れるかというところを、引き続き防災課とも連携の上、検討してまいりたいと思います。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、いろいろ進めていただきたいと要望したいと思います。例えば災害協定を結ぶなどの具体化がよいかと思いますけれども、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"今般の能登半島地震におきましても、温かい食事、栄養のある食事というところで、課題が出てきたところです。区といたしましても、様々、飲食業界の方と協力・連携して、そういった食事が提供できるように進めてまいりたいと考えております。","id":"exchange-077"},{"speaker":"ひがし委員","kind":"質問","question":"６９ページ、自立支援給付事務の中の重度訪問介護について、そして７１ページのすまいるスクール運営費についてお伺いいたします。利用者が増えたのか、また利用人数は変わらないが利用時間が増えたなどについて、詳細が分かれば併せて説明を求めました。","respondent":"松山障害者支援課長","answer":"当初、前年度実績の利用者３５人を見込んでおりました。居宅介護に加えて生活全般にわたり、長時間にわたり介護が必要になり、重度訪問介護を利用された経緯があります。","id":"exchange-078"},{"speaker":"ひがし委員","kind":"質問・要望","question":"障害者福祉計画における見込量の算出方法について改めて伺います。グループホーム整備についても進めてほしいと願う一方で、サービスの向上に努めてほしいと求めましたが、区のお考えについても説明を求めました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"現在策定中の第７期品川区障害福祉計画、および第３期品川区障害児福祉計画におけるサービスの見込量は、より多いものを示しております。なお、サービスの見込量は利用量の上限値を示すものではありませんので… 次に、在宅支援についての区の認識と今後の展開についてお答え申し上げます。今後もニーズや状況に応じまして、居宅介護や重度訪問介護など、在宅支援の充実に努めてまいります。","id":"exchange-079"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点を踏まえて確認してみると、令和４年が大体、利用時間数が４,３９３時間と４,４７５時間。予算や実績と計画が連動するように、今後の計画の際には見込量の出し方について再検討してほしいと求めましたが、区の見解を説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"先ほども申したように、直近３年分と５年分の１人当たりの平均利用時間数を算出したものに基づいて、対比してより多いほうを示していると。やはり実際の個別支援において、今後十分な支援量が提供できるように、体制は整えていきたいと考えております。","id":"exchange-080"},{"speaker":"ひがし委員","kind":"質問","question":"区民の方々がこの見込量を見て、何か不安だ、サービスが減らされるのではないかというところ、先ほどからご答弁いただいていますけれども、そういうことではなく、きちんと予算もつけるし、介護のところも力を注いでくれると理解いたしましたが、改めて、その見解で間違いないか尋ねました。","respondent":"松山障害者支援課長","answer":"委員がおっしゃいます、区民の方のご不安な気持ちは受け止めております。策定予定の障害福祉計画の見込量を、事情が変わって超えたとしても、個別支援の中では必要なサービスについては支給してまいりますので。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区民の方々も安心、そして実績・予算ともに差異がないような形になるのではないかと思いますので、この点について改めて要望します。こちらではアレルギー対応なしとなっておりますが、この点、アレルギー対応なしにした経緯というところをお聞かせほしいと求めました。","respondent":"藤村子ども育成課長","answer":"仕出し弁当はアレルギー対応を行わないというところですけれども、実際には、アレルギー対応までカバーしているお弁当の業者が見つからないというところが大きな要因です。","id":"exchange-082"},{"speaker":"ひがし委員","kind":"意見","question":"前回は１人で配達していて、１人で配達できるのか、配達を委託する際の人数というのはどのようにされているのか。すまいるスクールのスタッフが、ここに２名増員となっているのですけれども、この経緯についてもお聞かせほしいと求めました。","respondent":"藤村子ども育成課長","answer":"第一日野小学校で試行実施した際は、こちらは、衛生的にも温度管理などしっかりできる場所に運ぶようにしたいと考えています。委託を２名増員というところなのですが、また食事の際の見守りというところをやっていただくような形で考えております。","id":"exchange-083"},{"speaker":"ひがし委員","kind":"確認","question":"様々検討していただいているということを確認できましたが、学校でどのようにされているのかというところをお聞かせほしいと求めました。学校側なのか、区なのかというところも気になるというようなご意見がありましたので、併せて伺えればと思います。","respondent":"藤村子ども育成課長","answer":"状況によっては救急車を呼んで対応といった形で、所定の対応の方法がありますので、適正に対応してまいりたいと考えております。お弁当を頼んだというところがありますので、その際の状況というところを見て、責任の所在というものを判断していくべきかと考えております。","id":"exchange-084"},{"speaker":"ひがし委員","kind":"確認","question":"身体に被害というか、事前から準備として研修等したほうがいいのではないかと思うので、その点については再度確認させてください。議事録も確認しましたが、せっかく一緒に食べられる機会なのに分けてしまうというのもどうなのかと思ったのですが、聞かせてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"そちらについても今後、仕出し弁当が始まるということであれば、しっかりやっていきたいと考えています。今後実施していく中では、一緒に食べられたほうがというところはありますので、運用のところをしっかり改善していきたいと考えております。","id":"exchange-085"},{"speaker":"つる委員","kind":"質問・要望","question":"３８ページ、特別区民税、特別区財政調整交付金、７５ページ、ベビーシッター利用支援事業について、関連して伺っていきたいと思います。ここにつきましては別の部分で伺っていきたいと思いますので、こうしたところの事務経費の負担軽減というのは、どの程度のものなのか尋ねました。","respondent":"遠藤財政課長","answer":"で、逆にイニシャルコストの部分がかなりかかってくるのかと考えていますので、事務の部分ではそれほど変わらないかと感じているところです。子育て支援ということでお話を頂いて、その後…","id":"exchange-086"},{"speaker":"つる委員","kind":"提案","question":"公明党としても自治体における政策提案等も今後していく予定もあろうかと思いますので、その際はぜひ積極的に参考にしてほしいと求めました。今回質問を準備する中で、これも２０１６年ですか、それをテーマにしたドラマだったかと思うのですとの意見を述べました。","respondent":"佐藤企画課長","answer":"まず委員がご紹介の家庭での労働の捉え方と支援策というところで、女性が７７.５％、女性の比率のほうが圧倒的に大きいというところです。きちんとした根拠を持って、スピード感を持って施策を進めていくというところで、引き続き頑張っていきたいと考えています。","id":"exchange-087"},{"speaker":"つる委員","kind":"提案","question":"例えば私たちは４０人いますが、そういう視点も、ウェルビーイングの施策を推進していくに当たっては必要な観点なのかと思います。施策展開を令和６年度もしっかりと、あした以降、様々な提案をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回、そして次年度は９,０００万円を予定しておりますけれども、どういった見込みで算出されていますでしょうか。内訳を説明を求めました。","respondent":"提坂税務課長、飛田子育て応援課長","answer":"令和６年度はさらにそれを推進させるということで、契約に向けた前向きな話を進めておりまして、流入額を増やそうとしています。補正の部分は、子どもの未来応援事業の分が増額になっているということで補正を組んだと認識しております。 これは子どもの未来応援事業ということでガバメントクラウドファンディングを行いまして、そこで予想を超える多大なご寄附を頂いたということです。こちらを充当しております。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"ぜひ私からも、体験型の、品川区にぴったりのアイデアがあるので提案したいと思います。皆さん、今、一番稼いでいると言われている芸人、つまり一番人気があって勢いのある芸人をご存じか尋ねました。","respondent":"提坂税務課長","answer":"これがまた復活するのと併せて、バックヤードの見学ツアーなど、いろいろな企画を考えているところです。今ご提案の芸人の部分については認識不足で申し訳なかったのですけれども、どんなものか調査させていただいて、研究を重ねてまいりたいと思います。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"我々も４５億円のお金が流出してしまっているので、強くこういったことを要望してまいりますので、お願いいたします。それを確認したいというようなことが発生した場合、そういったものを確認というようなことを、ケーブルテレビ品川にお願いすることは可能か尋ねました。","respondent":"辻広報広聴課長","answer":"ケーブルテレビでは、区で製作を依頼した番組、またケーブルテレビで独自で撮影しているものなど多種多様なものがあります。その前の状態ですと、まだ完全作品ではないので、ケーブルテレビで難しいという場合もあるかと思います。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"確認","question":"やはり、何か問題が起きたときに、議会として確認して、声明を出したり処分を行ったり、いろいろそういった事実確認も必要になる場合もあります。イエスかどうかということだけでも分かるようにしていただけるとありがたいので、ぜひその辺、ご回答をお願いします。","respondent":"久保田企画部長","answer":"メディアのいろいろな規制がありますので、そういったことに対しての対応は、やはり難しいところがあるのではないかと考えております。","id":"exchange-092"},{"speaker":"せお委員","kind":"質問","question":"私からは、７９ページ、出産・子育て応援事業についてお伺いします。この減額補正のご説明を、まずお願いいたします。","respondent":"若生健康課長","answer":"こちらの事業は、事業の仕組みとして、電子クーポンでの支給ということになっております。それがずれ込んでいったという事情で、大きくはその理由で、かなり残額が出ているというところでの減額になります。","id":"exchange-093"},{"speaker":"せお委員","kind":"確認","question":"ということは、妊娠・出産している人がかなり減ったとか、申請している人がすごく少ないなどということではないという理解でよろしいのか。そこだけ確認させてください。","respondent":"若生健康課長","answer":"流産などといったところでご希望されない方も一定数いらっしゃいますけれども、区に統計として頂いているのは、ほぼ申請を頂いているという認識です。","id":"exchange-094"},{"speaker":"せお委員","kind":"質問","question":"まだまだ始めたばかりなのですが、始めてみた中で、改めて出産・子育て応援事業との役割分担をどのように考えていますでしょうか。その会えなかった要支援の可能性があるご家庭には、出産・子育て応援事業、おむつ宅配、それぞれどのようにアプローチしていますか尋ねました。","respondent":"石橋品川保健センター所長","answer":"見守りおむつ定期便につきましては、本年度１１月から開始したばかりの事業となりますので、今後、事業の効果を検証してまいりたいと考えております。その中で、支援が必要なご家庭には、保健師が電話や訪問にて継続した支援を実施している形となります。","id":"exchange-095"},{"speaker":"せお委員","kind":"提案","question":"私も以前から提案してきているのですけれども、改めて、働き方の現在の状況と考え方を教えてください。そこで、庁舎以外の現場に出向くような、もちろん保健師もそうですし、主に専門職の方々の状況はいかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"しかし、保健師が、負担が多くなり、余裕のない状況であると、寄り添った支援ができない状況を生み出しかねないことも認識しております。保健師以外でもできる業務は、ほかの職種で対応するなど、または委託化するなど、各所で適した事務分担を行い…","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問","question":"６３ページほか、基金積立金、併せて８２ページからの土木費に関連して住宅改善工事助成について伺います。何と２８億８,０００万円余ということになりますが、最初に伺いたいのは、伺いたいと思います。","respondent":"遠藤財政課長","answer":"今回、約９億４,７００万円という形になりますので、当初の取崩し額に比べると、まだ少ないというような状況です。いわゆる今回の補正予算の中で、不用額あるいは契約の落差などという部分を集めて、こういう形で積み立てたところです。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問","question":"１点、伺いたいと思います。伺いたいと思います。","respondent":"遠藤財政課長","answer":"期限が短かったりというところで、なかなか新規や、あるいは途中でスキームを変えるというのは難しい部分があります。足りなかったという部分では、現在のところは、それだけ貯金があるということでやらせていただいているという考えです。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問・要望","question":"年度途中で補正予算を組むもの、組まないものの判断基準というのはどうなっているのでしょうか。改めて伺います。","respondent":"遠藤財政課長","answer":"積み増しているものについては、基本的に今回、足りなくなっているというものがほとんどだと考えているところです。判断基準といたしましては、そのときの話、それまでの状況などを聞きながらやらせていただいているです。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問・要望","question":"予算に向けた要望書で、助成額５,０９６万円と、大変好評な結果となったと。伺いますけれども、区はどのように評価しているのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"住宅改善工事助成についてお答えします。区内事業者の振興にも十分役立っていると考えております。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問","question":"今年度予算にも、当初予算には、２１２件で５,２００万円の予算が組まれていました。伺いますけれども、今年度を含む直近３年間の当初予算額と、それぞれ伺いたいと思います。","respondent":"竹田住宅課長","answer":"令和５年度の当初予算額が、４００万円増額いたしまして５,２００万円となっています。それから、新規受付終了日ですが、令和３年度が１２月２４日、令和４年度が１０月２８日、令和５年度が１０月６日となっております。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから私は、一方で基金に、４つの基金で２８億８,０００万円積んでしまっている結果になりました。希望者が全員助成を受けられるように、必要な補正というのをタイムリーに組んでいただきたいと私は思うのですけれども、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"令和５年度は、前年度の４,８００万円に比較しまして４００万円増額しまして、５,２００万円となっております。毎年、着実に当初予算を増額し、当初予算を着実に執行しておりますので、今年度では補正予算は考えておりませんでした。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったのは、機動的に補正予算なども組む必要があるのではないですか、いかがでしょうかという質問ですので。","respondent":"竹田住宅課長","answer":"この事業は、令和６年度予算におきましては、対前年比１,３００万円増の６,５００万円をご提案しています。本事業は耐震性を高める工事にもご利用いただけますので、本事業を通じて安全安心な快適な住環境の促進に向けて尽力していきたいと考えております。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問","question":"区内経済循環ということで、様々な効果があるわけですから、ぜひそういった柔軟な対応を今後お願いしたい。一般会計補正予算に反対を表明して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問","question":"６３ページ、７３ページですか、その件についてお伺いしていきます。こういった事例があったときに、どのような対応をされているのか、また対応・対策についてどのような基準があるのか、説明を求めました。","respondent":"坂野保健予防課長、辻広報広聴課長、崎村人事課長、佐藤経理課長","answer":"これは、委員からお話があったように、予算編成時には、いつ５類になるか分からなかった。これが去年の５月７日までで、５月８日から５類になったの… 広報広聴課の人件費についてのお尋ねかと思います。こちらは、年度途中で育休等が出まして、その分が、会計年度ではなくて……。 まず職員給与費の当初予算の段階では、令和５年４月から会計年度任用職員２名を配置した関係で増額となっているところです。 特定の事業者が、いわゆる不祥事を起こしたときに、契約の関係からですけれども…","id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。なので、情報に対してはやはりもう少し徹底してほしいと求めましたが、改めてその辺のお考えを説明を求めました。","respondent":"辻広報広聴課長、立木保育課長","answer":"広報広聴課で、ハッシュタグはこういったほうが適切ではないかといったことを、所管と話して発信するというような流れになっております。なかなかそういう配慮が足りなかったかと思いますので… 午前中にお答えしました一時保育の関係の件で、令和４年度までがＬＩＮＥで、現在は区の電子申請システムに乗り換えてあります。それで、データ漏えい等がないということは確認していますので…","id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問","question":"様々な会社と、企業と、団体と、いろいろな契約をしている中で、向こう側、相手先の事情があったときに、どういう対応を取っているのですか。何もなかったというのだったら、何もなかったでいいのですけれども、では取っているのか、取っていないのか、まず説明を求めました。","respondent":"佐藤経理課長","answer":"それを受けて、区も指名停止等の処分をするというような形で対応しております。所管はそれぞれ各事業者と事業をやっておりますので、その範囲で確認していると認識しております。","id":"exchange-107"},{"speaker":"石田（し）委員","kind":"確認","question":"今日はここまでにしておきますけれども、これは追及するので、ぜひきちんと確認しておいてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"私からは、これは前にもほかの委員からも質問が少し出ていますけれども、私は初期消火というところについて少し伺いたいと思っています。バリウム、それから胃がんリスク検診と３つあるかと思うのですけれども、内訳について初めにお伺いしたいと思います。","respondent":"若生健康課長","answer":"胃がん検診の減額の内訳です。見込みが１,８０６人、見込みが４,１１２人、予算上の見込み１,２００人のところが８５０人といったことで。","id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"これが経年的に減少傾向なのですか。この点について、胃がんリスク検診の受診者の減少傾向ということについて、区の今の見解ということをお伺いしたいと思います。","respondent":"若生健康課長","answer":"１回検査を受けた後に、実際、受診者数も減少しています。こちらについては同じように継続していく予定ですが、そういったところで、この検診の手法について今後見直していくことを検討しています。","id":"exchange-110"},{"speaker":"塚本委員","kind":"確認","question":"確認できるということで、リスク検診はしなくても大丈夫というような見方が一定できるのかどうかということをお伺いしたいと思うのと、それから今後。その辺も含めたことについて、お伺いしたいと思います。","respondent":"若生健康課長","answer":"一定程度、そこでピロリ菌の感染の有無というのは確認できるものということは、私どもの制度管理の委員会の委員長の先生からも伺っているところです。２年に１回、医師会とも協議しまして、検討を進めてまいりたいと考えています。","id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"一応、都の被害想定では、断水の復旧というのは１７日後となっております。品川区としてはもう少し早く復旧するのだなどという見解があるのかどうかという中で、それをまず伺いたいのと、お伺いしたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"想定の復旧まで１７日ですけれども、ここの評価に関しましては、管理をしている東京都で計画的に整備を進めているものと認識しておりますので。今、Ｃ級・Ｄ級ポンプといったものも配備しておくといったところを…","id":"exchange-112"},{"speaker":"田中委員","kind":"質問","question":"私は、３８ページ、特別区交付金、普通交付金が１１億２,０００万円減額になったことに関してお伺いしたいと思います。その差額が狭まったからなのだろうと、そのときは認識いたしましたが、この１１億２,０００万円の減額の理由について改めてお伺いしたいと思います。","respondent":"遠藤財政課長","answer":"令和５年度につきましては、どちらも増えているというところはあります。他区と比較しての部分で、それから基準財政収入額の伸び率が高かったというところの２つの要因があるというところで考えているところです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"今も改めて伺いましたが、これは全てを反映しているとは思いませんけれども、同じ３８ページに特別区民税が７億円増額になっています。ここでご説明がすとんと落ちないところがありまして、これまでの東京都とのやり取りの中で、いろいろ確認しました。","respondent":"遠藤財政課長","answer":"先ほど、令和４年度に都市計画交付金の関係で算定され、ここの部分で品川区が２０億円ほど去年から減っているような形になります。ですので正式には、去年から０.７％、普通交付金という形では減という形になっておるようなところです。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問","question":"すみません。都市計画交付金が、でもトータルで言えば品川区だけ特別区交付金が減額されてしまっているという、その辺の分析はいかがか尋ねました。","respondent":"遠藤財政課長","answer":"恐らく文京区も、去年までは都市計画費に充当している部分が多かったのが、今年度になったときに少し減ってきたと。品川区の部分も同じような形で、今年度、対象となる部分が少なくなっていると考えているところです。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"今、我々が、まちづくりという観点で積極的に進めている、例えばタワーマンションを造ると、当然、１人当たりの収入が多い人が増えてきます。要は政策と財源確保ということがしっかりと一致するような方向で議論していただきたいし、また財源確保に向けての努力もぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"こしば委員","kind":"質問","question":"私からは、７９ページの各種がん検診についてお伺いいたします。減額の理由、そして区の評価について説明を求めました。","respondent":"若生健康課長","answer":"区で５つのがん、国で推奨されている対策型検診として、受診率の向上については今後取り組んでいかなければいけないと認識しております。こちらについても一定程度、こちらの受診率等が少ないというところは認識しているので、こちらについては今後検討と考えています。","id":"exchange-117"},{"speaker":"こしば委員","kind":"質問","question":"５０％からさらに６０％を超える数値目標を上げておるわけですが、自治体の取組が様々、国の報告書から浮かび上がってきます。お聞きいたしますが、受診率向上をお願いしたいと考えますが、お答えほしいと求めました。","respondent":"若生健康課長","answer":"国民健康保険については４月に、個別で、がん検診の案内を同封して送っているところです。今年度、４０歳から５９歳の国民健康保険加入の対象者、１万９,０００人ほどを対象に再勧奨通知を送るというようなことで対応を行っていく予定です。","id":"exchange-118"},{"speaker":"こしば委員","kind":"質問","question":"がん検診の受診率向上にも当然つながると信じておりますし、そもそもそれが早期発見、早期治療につながると期待しております。自費でがん検診を受診するようなケースの場合、分かる範囲で結構ですので、１人当たり大体どのくらいかかるのか教えてほしいと求めました。","respondent":"若生健康課長","answer":"リスク検診は自己負担７００円、ＣＴコースのみですと３,０００円、喀たん検査を受けるとプラス６００円となっております。乳がん検診につきましては、超音波検査対象の方につきましては５００円、マンモグラフィーも併用される方については１,０００円となっております。","id":"exchange-119"},{"speaker":"こしば委員","kind":"質問","question":"自費で、つまり補助を受けないで検診を受ける場合に、大体どのくらいかかるのでしょうか。分かる範囲で教えてもらいたかったのですが、もう一度お答えをお願いできますか尋ねました。","respondent":"阿部健康推進部長","answer":"区の検診をご利用されない方で検診を受けておられる方の中には、一定数、お勤め先の検診等で受けておられる方がおいでだと思います。この後、少し機会を捉えて、現状把握等に努めてまいりたいと思います。","id":"exchange-120"},{"speaker":"こしば委員","kind":"意見","question":"時間が少なくなったので、手短に言いますと、要はもし完全に自費で受ける場合は、相当な値段になると思います。そういったことも含めて、値段に着目した、受診率の向上に向けた取組をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-121"},{"speaker":"石田（秀）委員","kind":"質問","question":"当初２％ぐらいと言われていたわけだから、次の事業をどうやって区へ、その部分を財政調整交付金から引っ張ってくる。東京都のことを考えると、私は品川区の立場で発言があっていいのだろうと思っていて、そこをまずお聞きしたいと思います。","respondent":"新井副区長","answer":"逆に東京都からの説明を聞いて、憤りを感じているところもあり、財政調整だけではないと思うのです。そういったものをしっかり使って、ある意味、都の制度を最大限フルに活用しながら、区政を前に進めていくことが大事だと思っている次第であります。","id":"exchange-122"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう話もあったりしたものですから、それはぜひ区長会でも頑張っていただきたいと考えていますので、よろしくお願いします。ぜひそういうことも含めて考えてほしいと求めましたが、お考えを説明を求めました。","respondent":"宮澤地域活動課長","answer":"ここ数年で、引き続き宿泊施設としてというような、区民料金でというような条件をつけて譲渡しているという動きというのも認識しています。それら他区の状況や区民ニーズというところを含めまして、今後しっかりと検討していきたいと考えております。","id":"exchange-123"},{"speaker":"松永委員","kind":"質問","question":"６７ページの区民保養所、時間がありましたら８７ページの除却助成、８９ページのいわゆる耐震化について伺いたいと思います。ガスともに単価が安くなって、それぞれ２,５００万円の減額となっているそうですが、なぜこのような大きな差が出たのかお知らせください。","respondent":"佐藤経理課長","answer":"委員もご指摘のとおり、令和４年度の補正予算で、第４回定例会においては追加の補正予算６,０４０万円を計上させていただいたところです。その後、価格が下がりまして、今年度の支出実績から今回の減額補正の要求をしたものです。","id":"exchange-124"},{"speaker":"松永委員","kind":"意見","question":"分かりました。６７ページの区民保養所についてですが、２,６２３万円の減額となっている理由については、どの部分に工事費を充てられたのかをお知らせくださいとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"品川荘の大規模改修の部分というところの中で絞った内容ですけれども、本年度行ったのは設計委託という形になっています。空調設備の更新のための工事、また、あともう一つが温泉用のろ過装置に絞った内容になっているというところです。","id":"exchange-125"},{"speaker":"松永委員","kind":"質問","question":"空調設備とろ過装置ですが、品川荘は今、築年数はどれくらいなのでしょうか。南海トラフ地震が起きそうだという状況の中で、もし大きな地震が起きたときの耐震化の面に関してはどうなのかということをお聞きしたいと思います。","respondent":"小林施設整備課長","answer":"品川荘ですが、築年数としましては、およそ３０年です。この建物につきましては新耐震の基準に基づいて設計していますので、ある一定程度の耐震性能は持っているといったところです。","id":"exchange-126"},{"speaker":"松永委員","kind":"質問・要望","question":"内容といたしましては、護岸の脇の辺りの汚泥を取るということを伺っておりますけれども、その場所について詳しくお知らせほしいと求めました。もう一つは、目黒川の障害物について、どういったものなのかお知らせください。","respondent":"北原河川下水道課長","answer":"しゅんせつを行う場所ですけれども、東京都と品川区で役割分担をしておりまして、品川区は河川の両脇のフーチング部分のしゅんせつを行うものです。障害物撤去につきましては、過去に護岸を整備したとき等に残置されている杭などが船の航行に支障になるため、撤去するものです。","id":"exchange-127"},{"speaker":"松永委員","kind":"質問・要望","question":"しっかりと対策を取っていただきたいのですけれども、こうした中で、そうした近隣住民との対策をどのように取られているのかお知らせください。スケジュール感なのですけれども、汚泥のしゅんせつと障害物について、どのくらいの期間がかかるのかお知らせください。","respondent":"北原河川下水道課長","answer":"そういったものがどのぐらいあるかという調査を行っておりまして、把握した上で実施してきております。今後の予定なのですけれども、令和７年度以降に最上流部でやりまして、全ての区間を完了する予定となっております。","id":"exchange-128"},{"speaker":"松永委員","kind":"質問","question":"次に、８７ページの除却助成、住替え支援事業について伺います。家賃補助は３か月分であると認識しておりますけれども、その利用実績と見込みについてどうだったのか、またその理由についてお知らせください。","respondent":"小川木密整備推進課長","answer":"当初見込んでおりました助成申請の件数が少なかったことによりまして、今回、減額補正をさせていただいたところです。そして、あと移転助成に関しましては、予算計上時の件数が１５９件でございまして、令和６年１月現在が６９件の実績です。","id":"exchange-129"},{"speaker":"松永委員","kind":"意見","question":"要は、それでは除却の件数や住替えの件数、支援の件数というのが少なかったです。どういった形でやられていたのか、ポスティングなり様々な対策は取っているのかと思いますけれども、改めてその方法についてお知らせくださいとの意見を述べました。","respondent":"小川木密整備推進課長","answer":"令和４年度から戸別訪問というものを行いまして、また地区外の権利者に、事業案内をさせていただいたりというところをやってあります。併せて、今年度に関しましては不燃化特区支援事業のＰＲ動画も作成して…","id":"exchange-130"},{"speaker":"松永委員","kind":"質問・要望","question":"私も昨年の第２回定例会で一般質問させていただいたのですけれども、区としてもしっかりとやっていくという回答を頂いております。質問なのですけれども、区としてこの減額についてどのように捉えているのか、お知らせください。","respondent":"長尾建築課長","answer":"おおむね８０件から９０件ほどの申請という予定になっておるのですが、今回、来年度予算で全域に拡大するようなところを提案しています。耐震化がまだ不十分である、木造住宅については特に不十分であるという認識ですので、耐震化をさらに加速していきたいと考えております。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問","question":"なので、この基本方針、要は別物であったとしても、いじめ対策というのは、主導権はどうなっていくのですか。これは、３７校、一斉にやるところがあるのか尋ねました。","respondent":"丸谷教育総合支援センター長、勝亦総務課長、藤村子ども育成課長","answer":"私からは、いじめ対策についての人的支援というところについて回答したいと思います。次年度に向けましては… 頂いた１９件のうち５件は無事終息という形になっておりますけれども、それ以外につきましては、引き続き相談対応に当たっているところです。今後… こちらは８月に１０日間の試行実施を終えまして、今回３７校、全校一斉に実施するということでやっていきたいと考えているところです。…","id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"それから区長部局は、どうして今まで教育委員会でやってきたのに、区長部局がそこに入ってくるのでしょうか。増やしていきたいのだったら数校ずつとか、いきなり３７校やるなど、そういう業者がいるのか尋ねました。","respondent":"勝亦総務課長、丸谷教育総合支援センター長、藤村子ども育成課長","answer":"区長部局における相談員ですけれども、相談員３人が、心理カウンセラー、それから社会福祉士といった資格を持った者が対応しています。… 今回、区長部局と連携してというところで、教育委員会が作成した基本方針について、区長部局とも連携するという意味で協働して取りかかるというものです。 こちらについては他自治体でも実施できているものですので、やっていきたいと思います。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"これについて、区民の方から意見やご要望があったので、ここで取り上げします。そこで、二十歳の集いの案内を出すときのキーホルダーについても含めた、記念品についての区の考え方等をお聞きしたいと思います。","respondent":"豊嶋生活福祉課長、池田国保医療年金課長、勝亦総務課長","answer":"私からは、住居確保給付金の件数等々についてご説明します。世帯人数ですが、ほとんどの方が単身世帯となっておりまして、３９件のうち３０件が単身世帯… 一体的実施についてのマイナスの補正です。実際に対象者が多くいたのですけれども、申込みをされる方が少なかったということでの減額という形になっている… 二十歳の集いをきっかけに知っていただく、いい機会だと考えておりますけれども、伝え方につきましては今後十分考えてまいりたいと思います。…","id":"exchange-134"},{"speaker":"若林委員","kind":"質問・要望","question":"アール・ブリュットにも一生懸命取り組まれている施設もあります。こういった、先ほどの送る側、また受け取った側のお気持ちの２つの視点から記念品を選定し、新成人に心が届くように努めていただきたいと存じます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-135"},{"speaker":"西村委員","kind":"質問","question":"質問が重ならないように伺ってまいりたいと思います。減額の詳細と、近年の申請数の変化を伺います。","respondent":"長尾建築課長","answer":"木造住宅の除却助成が占めている部分についてですけれども、予算上は２１０棟分の除却助成に対応できるような予算を組んでおりました。実績といたしましては約半分程度の申請になる見込みとなっておりますので、約２.２億円の木造住宅の除却助成分を減額する内容となっておりま…","id":"exchange-136"},{"speaker":"西村委員","kind":"質問","question":"費用は、戸建てで１件１５万円程度でしたでしょうか。耐震診断をさらに拡充して促すことでの、区の狙いや期待する効果を伺います。","respondent":"長尾建築課長","answer":"除却助成につきましては、平成２３年度から実施している制度になっております。９６件という実績になっておりまして、令和５年度についても、おおむね同程度の実績になる見込みとなっております。","id":"exchange-137"},{"speaker":"西村委員","kind":"質問・要望","question":"不燃化率を上げていくことは、会派でも、まつざわ委員長を中心に要望してまいりました。どういう経緯があったのか、今後の数値目標はあるのか、伺います。","respondent":"小川木密整備推進課長","answer":"来年度から取組をします、整備地域不燃化加速事業のお尋ねです。品川区不燃化特区支援事業は、助成支援を行わせていただいているところですが、小山二丁目と中延四丁目におきまして同じような助成支援を行いまして。","id":"exchange-138"},{"speaker":"西村委員","kind":"意見","question":"このスキームを活用していただいておりますけれども、令和７年まであと２年というところで、さらに力強い促進をお願いしたいと思います。建て替え助成までしている区が現在８区ありまして、これからこの事業をどこまで広げていくのか、区のお考えを説明を求めました。","respondent":"長尾建築課長","answer":"建て替えに関しましては、２３区の中でも一部の区で除却助成と併せて、もしくは建て替え助成をやっている区があるということは認識しております。他区と比べましても補助率も助成上限額も非常にしっかりと支援している内容になっておりますので…","id":"exchange-139"},{"speaker":"西村委員","kind":"質問","question":"１９８１年の新耐震基準以降の建物も倒壊したということが、震度７クラスの地震に１度だけ耐えられることを前提としていると私は理解しております。この点、能登半島地震のこのような報道を受けましての、担当課のお考えを説明を求めました。","respondent":"長尾建築課長","answer":"旧耐震だけではなくて、住宅の耐震化については幅広く支援できるような状況にしております。建て替えるという選択をされた場合は除却助成も使っていただいて、区全体として耐震化が進むようにしていきたいと考えております。","id":"exchange-140"},{"speaker":"西村委員","kind":"質問","question":"今後の耐震基準も、また地盤のことなども検討しながら、変わっていくようなことがあるのではないかと私は思っております。駄目なところが見つかっても直さない、直せないというような区民の方がいるのではと懸念いたしますが、その点はいかがか尋ねました。","respondent":"長尾建築課長","answer":"木造住宅の除却助成を活用される方に関しましては、その後の建て替えや売却などという道筋が一定、見えている方からの申請や事前相談というのがほとんどですので、そこについては止まらず、そのまま建て替えに向かって進んでいるものと認識しております。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"確認","question":"財政調整基金積立金ほか３つの基金への補正についてお伺いします。補正予算の編成に当たって、歳入との最終調整という形で、こういう金額になっているのかということをもう一回確認します。","respondent":"遠藤財政課長","answer":"財政調整基金の積立額補正につきましては、委員のおっしゃるとおり、最後、歳入と歳出を合わせなくてはいけませんので、その部分での積立額です。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"その一方で財政調整基金の金額、こういった調整した金額だけではなくて、積み立てることは可能だと思っています。その点についてはいかがか尋ねました。","respondent":"遠藤財政課長","answer":"これは令和５年度の資金がそれぞれどういう部分で使われているかで、財政需要という形で出したものですので、その分で結果として積立てということで財政調整にさせていただいたです。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"その件については、また別の機会にお話を伺いたいと思います。今後の庁舎整備に当たり、いろいろなところで議論になっていますが、具体的な財源計画をお伺いいたします。","respondent":"遠藤財政課長","answer":"令和６年度までに３０億円ずつ積み立てまして、１２０億円という形で進ませていただいたところで、金額が変わってきたです。資金計画、実際の実績などが出た段階でも金額が分かってくるかと思いますので、そちらを徐々に見ながらという形になろうかと考えているところです。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、残りの２５％は約１１２億円で、これが令和６年度の庁舎整備基金の、足し算をしていくと１２０億円になるわけです。そうすると、そこの中で、何というか、解決できるという状況で、議会で現状、これからというお話がありましたけれども、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"今、計算式のお話を頂いたとおり、現状では１２０億円で、都や国のところの負担分を引きますと賄えるというような状況では考えているところです。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、起債が３３０億円になるという前提で、それぞれ考えていかなければいけないところになるのかと思います。それについてはいかがか尋ねました。","respondent":"遠藤財政課長","answer":"今後、起債はさせていただきまして、そちらの返済が当然かかってきますので、そこの部分につきましても、減債基金の積立てなども考えながら、返済の計画も立てるべきかと考えているところです。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"意見","question":"そして３番目に、そのほか償還財源を確保すべき公共事業ということなので、減債基金条例の減債基金の中に積み立てることができる。そのためには、起債を現在、できるだけ余裕のあるうちに積み立てていく必要があると思うのですが、その点についてはもう一度お願いしますとの意見を述べました。","respondent":"遠藤財政課長","answer":"積立てといいますか、基金にどんどん積み立てていくというのは、お考えもあろうかと思います。今後またもう少し上がるような形も考えられますので、今後の推移を見ながら、こちらについては様々な手法を検討していきたいと考えているところです。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから減債基金でも、実際、減債基金のほうに、今まで今のような考え方で積み立てていくことはなかったのだと思います。もちろん起債は起債ですけれども置いておいて、基金の中でできるだけ基金を積み重ねておく必要があると思うのですが、改めてお願いします。","respondent":"遠藤財政課長","answer":"様々な手法があると認識しておりますので、こちらの減債基金も含めまして、いろいろと検討させていただければと考えています。","id":"exchange-148"},{"speaker":"松本委員","kind":"確認","question":"８９ページ、職員給与全般について伺いたいので、それに関連して職員研修制度について伺いたいと思います。ここを確認しないといけないのかと思ってお伺いしたいのですけれども、よろしくないのかというところがあると思うのですが、そこはいかがか尋ねました。","respondent":"遠藤財政課長","answer":"この間ずっと執行を１年間やってきた結果、様々な不用額が出てきているです。安定性を含めてという形で、基金に積み置くという形につきましては、よく一般的にやられていることだと考えております。","id":"exchange-149"},{"speaker":"松本委員","kind":"質問・要望","question":"基金に積み立てるのは、私もそれは承知しています。要望を上げるときに、ある程度やはりそこは財政の在り方というのを考えておかないといけないのではないかと思ってお伺いしているのですけれども。","respondent":"遠藤財政課長","answer":"要するに足りない部分について余計に乗せていく、事業として振り分けていくというところもあろうかと思います。ほかの部分につきましては様々な行政需要という形で考えさせていただいて、ある程度、このような形になっているところです。","id":"exchange-150"},{"speaker":"松本委員","kind":"提案","question":"私たち議員も、そうやすやすと提案していいのかというところを思いましたので、こうした質問をさせていただきました。これは昨年、道路課と防災課については２,０００万円規模で減っているというところで、これはどういう要因なのかお伺いできればと思いますとの意見を述べました。","respondent":"崎村人事課長","answer":"まず当初予算の考え方といたしまして、その前年の１０月１日現在の現員現給をもって算定させていただいて、予算編成しています。防災課につきましては、育児休業や病気休職の代替職員として配置した職員が４月１日現在で解消した結果として減額とさせていただいているところです。","id":"exchange-151"},{"speaker":"松本委員","kind":"質問","question":"これでまた財政課に質問を戻するのですけれども、記載が、給与費についてはほかと少し違って１００万円単位で記載されているのです。今こういうふうに１００万円単位で給与についてやられている理由と、千円単位にしたほうがいいのではないかと思うのですが、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"１１月、１２月ぐらいにやりまして、丸めさせていただいているというのが正直なところです。ほかのところで考えながらというか、ある程度、全体を見てという形でさせていただいているところです。","id":"exchange-152"},{"speaker":"松本委員","kind":"確認","question":"パンフレットを確認すると、あるいは、英会話の補助が受けられますというふうな話も載っています。なかなか中身が我々には分かりにくいので、助成の趣旨と具体的な内容、そして実際にどういうものが活用されているのか伺います。","respondent":"田口人材育成担当課長","answer":"教育機関が実施する講座を自発的に受講する職員および指定された研修を実現する職員に対して費用の一部を助成することで、自己啓発の促進を図り。こちらの内容ですが、講座内容や資格試験の種類によって異なりますが、受講料や検定料の８５％から５０％の助成を行っております。","id":"exchange-153"},{"speaker":"松本委員","kind":"意見","question":"すみません。活用状況ということで、どういうものが人気があるか、どういうものが使われているかという具体的なところもお願いしますとの意見を述べました。","respondent":"田口人材育成担当課長","answer":"活用状況につきましては、令和５年度は２月末時点で２３件、約２３万円の助成を行っております。申請が多い主なものとしましては、日商簿記検定や社会保険労務士、宅地建物取引士、語学系に関する講座や検定です。","id":"exchange-154"},{"speaker":"松本委員","kind":"確認","question":"魅力的だと私も思うのですけれども、一方で要綱を確認すると、会計年度任用職員の方たちというのが対象からは外されているかと思います。この理由についてお伺いできればと思います。","respondent":"田口人材育成担当課長","answer":"こちらの制度なのですけれども、会計年度任用職員につきましては１会計年度内での任用となっております。こちらが、翌年度以降も働くということが確定していないということもございまして、対象外としております。","id":"exchange-155"},{"speaker":"須貝委員","kind":"提案","question":"この提案に対して特に目立つのが、上司が部下を評価するのは２５％、４分の１です。本人の提案した、今まで部下の提案を、本人の実績を半年ごとの集計により給与やボーナスに反映させるというものですとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"品川区が実施した事務事業評価に関しましても、今後の改善内容というところまで踏み込んで、評価に反映させたです。品川区が実施した事務事業評価につきましては、行っていく中で、そちらも振り返りながら事業の改善をしていきたいと考えているところです。","id":"exchange-156"},{"speaker":"須貝委員","kind":"提案","question":"これも質問を忘れましたけれども、職員事業提案制度というのは実際あるのかどうか教えてください。子育てなど、数字に表せない仕事をしていると思うのですが、どうか尋ねました。","respondent":"岡秘書担当課長、吉岡政策推進担当課長","answer":"今年度から職員提案事業制度をやりまして、提案数が３３件ありました。そのうち９件を予算化して、来年度に向けてやり始めました。 私から、行政評価についてのお尋ねです。必要性を考えていくですので、必要な政策、必要な効果かと捉えているところです。","id":"exchange-157"},{"speaker":"須貝委員","kind":"提案","question":"それを、こういうふうに、人件費は幾ら、事業費は幾らではないのではないのですか。その職員の方が、「いや、こうしたらいいと思うんだけど」という提案との意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"同じ効果を得るために、そういった部分をしっかり数値を分析していくというところも、行政として必要な部分だと捉えているところです。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"そういう、評価する仕組みというのをつくるべきだと私は思いますが、それがイコール、職員の働きがいにつながるのではないですか。でも、それはできないとして、やはりそういうことを主眼として、行政評価というのはするべきだと私は思うのですが、いかがか尋ねました。","respondent":"吉岡政策推進担当課長、崎村人事課長","answer":"当然ながら、区民の皆様からその事業に対するアンケートも取って、しっかりと進めているようなところもあります。しっかりと、どう事業を実施すれば効率的にできるかというところで、行政評価を実施したです。 区の予算の規模というのは限られておりますので、そうすると、例えば福祉や教育や子育てに回すお金というのがなくなってきてしまいます。ですので…","id":"exchange-159"},{"speaker":"須貝委員","kind":"提案","question":"今、品川区では、ＳＤＧｓ未来都市、それから自治体ＳＤＧｓモデル事業の提案内容が出ました。だけど、今、皆さんに必要なのはこのことか尋ねました。","respondent":"久保田企画部長","answer":"事業手法などといったやり方を見直すことも含めて検討しておりまして、よりよい満足のいくサービスを提供していきたいと考えているところです。誰一人取り残さない、今取り組まなければならないこともありますので…","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"でも新井副区長、側に、年齢が近いのですから、「区長、それはおかしいですよ。違いますよ」ということは、ノーはノーではっきり言って、それでやはりお互いに話し合って、この品川区を改革、改善してほしいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-161"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから２点目に、特別区長会が昨年の１１月１６日に厚生労働大臣宛てに、５項目にわたる要望も出しました。品川区も厚生委員会の中で、同じ認識だと答弁されましたけれども、国民健康保険の危機とは何かについて伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"１人当たりの医療費も増えているということで、先ほど補正額でも、かなりの療養給付費を入れさせていただいているです。医療費、それから所得によって保険料というのは決定してまいりますので、運営するについてはかなり厳しい状況ということで把握しています。","id":"exchange-162"},{"speaker":"鈴木委員","kind":"確認","question":"法定外繰入れは最終補正で幾らかと伺ったのですけれども、２４億円でいいのかということの確認をお願いしたいと思います。総収入で月２５万円の４人世帯から月４万円もの国保料というのは、負担が重いという認識はないかということを伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"実際に今後の医療費、そして所得を計算した上で保険料というものを出していますので、妥当な数字というところになってくるかと思います。東京都、国に支援をお願いしたいということと、また支援のほかに抜本的な改革をやらなければいけないのではないかということを。","id":"exchange-163"},{"speaker":"鈴木委員","kind":"質問・要望","question":"子どもの国民健康保険料の負担軽減ももっと拡大してくれということで要望しているわけですから、その大本には、いかがでしょうか。この点について伺います。","respondent":"池田国保医療年金課長","answer":"各区から出しているような形でやっておりますので、今回の保険料については、ほぼ妥当な数字を出させていただいているのではないかと思ってあります。こちらも国にお任せするという形で考えているところでございまして…","id":"exchange-164"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、ぜひ取り組んでいただきたいと思うのですけれども、その点を１つ伺います。それから、最終補正で４億円を新たに今回積み増して約２０億円になったということで捉えていいのか、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういった現場の声を伺いながら、今回も居住支援手当というところで、現場の声を聞きながら今後も検討していきたいと思っているところです。令和５年度末基金見込額、１９億９,９９６万５,０００円というところで、約２０億円を見込んでいるところです。","id":"exchange-165"},{"speaker":"鈴木委員","kind":"意見","question":"実質賃金もピーク時より７４万円も下がり、年金も下げられている。この補正予算にもこの視点で反映させるべきと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-166"},{"speaker":"大倉委員","kind":"質問","question":"時間があれば、６４ページ、人事管理費について、また区民まつり経費、６７ページについて伺えればと思います。先ほど少しお話を伺っていて思ったのは、令和７年度の予算になると、今後の考え方。","respondent":"吉岡政策推進担当課長、佐藤企画課長、川崎障害者施策推進課長、藤村子ども育成課長","answer":"今年度実施した評価のところで廃止した事業をはじめ、令和６年度予算編成で見直しを行った事業や経費といったものを抽出して削減額を出したです。… 私からは、来年度のウェルビーイングの主な取組についてお答えいたします。総合実施計画、ウェルビーイング予算ではなくてウェルビーイング指標の検… 私からは、障害者グループホーム整備等助成の５,０００万円減額になった理由についてお答えいたします。区独自の補助金になりますので… そういったところを踏まえまして…","id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"運営も既にされているところの助成の費用について件数を伺って、見直し中も含めて検討していただきたいというところで質問をさせていただきました。まだまだ活用されていないという課題もあるように思いますが、それについてどのようにお考えか尋ねました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長、藤村子ども育成課長、吉岡政策推進担当課長","answer":"先ほど、整備補助については、使わずに開設が進んだとご説明しました。この大きな活用の資金を民間事業者に使っていただくべく… 運営面からの支援を行っているところですが、委員がおっしゃられるように、ご活用いただける事業者の実績が少ないことは課題として捉えております。… 今回の試行実施によって、今後、運用の面で配慮してまいりたいと考えています。そういったことが起こらないように細心の注意を払って… 不用額があるからといって、一律に廃止したり縮減したりといったところではございません。…","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問","question":"事業者の声を聞きながら、また国の指針も注視しながらということでありましたが、ぜひよろしくお願いします。以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、７５ページ、私立幼稚園費、私立幼稚園保育料助成、そして８９ページ、防災費から避難所管理費、この２点で質問をします。品川区として私立幼稚園による幼児教育の重要性をどのようにお考えになっているのか、伺います。","respondent":"石井保育支援課長","answer":"現在１８園、昭和２０年代、３０年代からもう品川区の幼児教育をリードしてまいりました。幼児期の貴重な人格形成の基礎ということで、私立幼稚園の果たす役割というのはとても大きいものであると認識しています。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問","question":"無償化開始の際にも議会でも課題となっておりました、保育料の償還払いについて伺っていきます。伺いますけれども、そして月額の平均額、品川区がつかんでいるところを説明を求めました。","respondent":"石井保育支援課長","answer":"私立幼稚園の保育料ですけれども、私が把握している限り、一番低いところは大体２万６,０００円程度、高いところは４万円程度で、平均すると大体３万１,０００円から２,０００円の間であると把握しております。","id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問","question":"そして、私立幼稚園にお子さんが２人在園すれば、当然、２倍の出費となるわけであります。ここで伺いますが、その具体的な方法について各自治体で決定できるのか、まず説明を求めました。","respondent":"石井保育支援課長","answer":"施設等利用費の支給に関しましては、法律上、代理受領について規定がありますので、まずはできるです。各区、各自治体の判断で、そのようなことを実施するか否かについては検討できるものと考えています。","id":"exchange-172"},{"speaker":"あくつ委員","kind":"質問・要望","question":"幼児教育・保育の選択肢の中で私立幼稚園の入園をためらわせる１つの要因になっているのだといったご意見も、保護者、幼稚園側からも直接伺いました。保護者の経済的負担の軽減や利便性を促進する給付方法である法定代理受領をぜひ導入していただきたいと思うのですけれども、ご見解を伺います。","respondent":"石井保育支援課長","answer":"令和元年に幼児教育の無償化が制度化されてから、様々、方法等を検討してまいりました。この間、いろいろ幼稚園ともコミュニケーションを取らせていただきながら、ぜひこちらの実現に向けて、前向きに準備をしています。","id":"exchange-173"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に、園児保護者補助金について伺います。これは、大体どれぐらい差額を負担されているのか、品川区が捉えている金額を説明を求めました。","respondent":"石井保育支援課長","answer":"保護者補助金の予算の算定ベースで考えますと、４,０００円程度の自己負担が生じているのではないかと考えています。","id":"exchange-174"},{"speaker":"あくつ委員","kind":"質問・要望","question":"第１子のお子さんについては、自己負担がなくなって、全額無償化ということも見えてくるということではないでしょうか。可能な限り、全額無償化に近づけてほしいと求めましたが、いかがか尋ねました。","respondent":"石井保育支援課長","answer":"そういった並びも考えながら、東京都もこの補助金については１,８００円から６,２００円のところで補助しており、区はそれに上乗せをしています。第２子、第３子の算定方法の変更といったことで、子育て負担の軽減については適切に検討してまいりたいと考えています。","id":"exchange-175"},{"speaker":"あくつ委員","kind":"提案","question":"具体的には、区民ニーズにかなう施策を提案するよう、各所管からのプレゼンテーションを行って編成作業を行われたということでした。あまたある防災対策の中から多額のトイレ対策を提案した理由、そして災害時のトイレ問題についてどう捉えておられるのか、説明を求めました。","respondent":"平原防災課長","answer":"１月１日に発生いたしました能登半島地震におきましては、災害関連死の増加の懸念も及ぶところです。今回この事業を検討し、防災をさらに考えていただくきっかけとして、携帯トイレを配布するという事業を提案させていただいたところです。","id":"exchange-176"},{"speaker":"あくつ委員","kind":"質問","question":"私はこの方の講演へ２回、実は伺っているのですけれども、教訓をどう活かすべきか。品川区では、災害時のトイレ確保・管理計画の策定をされているのか、伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"地域防災計画を、このたび大規模修正をいたしまして、その中に、トイレの確保ということでうたっております。来年度以降、避難所運営マニュアルや地区防災計画といった中にも、しっかりトイレの確保についてうたってまいりたいと考えております。","id":"exchange-177"},{"speaker":"あくつ委員","kind":"質問","question":"立てている自治体もあるのですけれども、このことについて品川区は計画の中で、トイレ確保・管理の責任者を立てているかどうか。私は立てるべきだと思いますが、この点についてご見解を伺います。","respondent":"羽鳥防災体制整備担当課長","answer":"トイレの責任者についてですけれども、現状設定しておりません。","id":"exchange-178"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"冒頭１点、要望も含めてになりますが、先ほど、ＳＤＧｓ未来都市の話が、補正予算なので、どこからお話が出たのか分かりませんが、出てきました。それに関連して保養所のところをお伺いしますが、行政評価シートで確認すると、まずその認識でいいのか。","respondent":"宮澤地域活動課長","answer":"品川荘は昭和３４年に開設で、光林荘が昭和３６年に開設というところで、区民の保養と健康の増進を目的にということで、保養所事業を実施しています。","id":"exchange-179"},{"speaker":"せりざわ委員","kind":"確認","question":"昭和３６年というと１９６１年になるかと思いますが、世界で何が起こったかと確認していると、ベルリンの壁ができた年だそうであります。いわゆる区民の人が利用していくというのは、今の保養所である必要はないのではないかとまず思うのですが、こちらについてご見解を説明を求めました。","respondent":"宮澤地域活動課長","answer":"区立で保養所を持ち、民間で貸し付けて運用しているというスタイルで、保養所事業を展開しています。伊東市の平均というところが大体１万５,０００円ということだそうなので、安心して利用できるというところで、保養所事業を展開しています。","id":"exchange-180"},{"speaker":"せりざわ委員","kind":"意見","question":"見合っているのかというのは考えていくべきだと思っていて、未来を見据えてというところで言うと、本当に必要なのかと。そういった観点でぜひ一度、見直しをしてほしいと求めましたが、ご見解を説明を求めました。","respondent":"宮澤地域活動課長","answer":"ただ、他区の状況等を見ますと、委員ご指摘のとおり、借上げの手法や、協定を結んでという形等もあります。他区の状況や利用の実績、区民ニーズ等を踏まえて、今後の方向性について検討していきたいです。","id":"exchange-181"},{"speaker":"せりざわ委員","kind":"確認","question":"今朝も事業承継のお話を我々の会派からも確認させていただいて、前向きに事業承継というのは品川区で進めていきたいというお話を頂きました。初めにお伺いしたいのですが、どのように分析されているのか、まず説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"そういった中で、やはり高年齢化というときに、後継ぎがいないと事業所あるいは会社自体が継続できないというようなお話になってまいります。この取組を平成２８年度から進めておりますけれども、事業承継を進めるに当たりまして…","id":"exchange-182"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"１人でやっている店舗の方などというのは、出口戦略と言ったらいいのでしょうか、なかなか考えられずにいると思います。例えば産業ニュースなど、そういったところで事業承継のＰＲというところも含めて手を打ってほしいと求めましたが、ご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"品川区自身、ふだん事業所とお付き合いのある金融機関といったところとも我々は連携しまして、一緒に事業承継のセミナーというものをやっております。あるいは本日ご説明しましたような助成金も使っていただきながら…","id":"exchange-183"},{"speaker":"せりざわ委員","kind":"意見","question":"１回売ってしまって、１つ、選択として残してあげてもいいのかと思っています。ほかの方に事業を譲渡するようなお手伝いをするというのも、品川区としてできればいいと思うのですが、ご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"いろいろ法律の問題、相続の問題、いろいろ複雑な問題が関わってきております。ですので、そういったところの相談も活用していただきながら、少し時間もかけながら進めていくようなお手伝いをできればと考えております。","id":"exchange-184"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"以前、今おっしゃっていただいたようなＭ＆Ａですか、例えばマッチングサイトがあったほうがいいのではないかというようなお話もありました。ぜひご支援ほしいと求めましたが、最後、ご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいま委員からご指摘がございましたように、こういった分野というのは、最初はやはり匿名で進めたほうがいいというようなやり方もあります。ご指摘のようなマッチングサイトのところも含めて、金融機関などともいろいろ連携しながら研究していきたいと考えております。","id":"exchange-185"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6685#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":134818,"voices":431}},{"id":"r06-20240305-3","meetingId":"r06-c-budget","date":"2024年3月5日","dateIso":"2024-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を196件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"増築のために駐車場を一部潰すと伺っておりますが、駐車スペースの確保に問題はないでしょうか。この点、改善できることはないか、ご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"それから南側に１６４台の計２４９台、大型車は１０台駐車できるのですけれども、こちらの北側の８５台のほうはなくなる予定です。その際、組合のほうから、臨海部広域斎場組合と品川区を含めた組織区５区で、今後検討してまいりますという回答をしております。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問・要望","question":"なぎさ会館、こちらは今後どう展開していくのかということも質問させてほしいと求めました。改めて、なぎさ会館はこのまま維持していけるのかという問題は、別の課題があると思うのですが、いかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"採算が取れないという観点もあるのですけれども、一方で、斎場は広域性の観点も必要であると認識しております。区民のニーズですとか、社会情勢とか、そういったところも勘案しまして、今後の検討課題と認識しております。","id":"exchange-002"},{"speaker":"西村委員","kind":"質問","question":"出血していて立て直しが難しい状況にあるのか、行政評価を上げたばかりでありますが、区はどのようにお考えでしょうか。利用料収入の経年変化と併せて伺います。","respondent":"吉野戸籍住民課長","answer":"先ほどの答弁と少し重なってしまうのですけれども、やはり今後の社会情勢等も鑑みまして検討していきたいと思います。","id":"exchange-003"},{"speaker":"西村委員","kind":"質問・要望","question":"次に、桐ケ谷斎場について伺ってまいりますが、民間とはいえ、桐ケ谷斎場の料金に割高感が最近一層あるというご指摘が区民の方からもあります。近隣に住む方たちも、近くの方にお葬式に来てほしいということで、臨海斎場が遠い方は桐ケ谷斎場しか選べないということもあると思います。","respondent":"舩木生活衛生課長","answer":"こうした中、令和４年度に民間企業が経営する火葬場の保有区６区におきまして、現時点で公益目的に反する行為や指摘事項は認められておりません。会計がしっかりと明確に分離されているかなどについて、必要な報告を求め、火葬場の適正運営について確認を行っていく予定です。","id":"exchange-004"},{"speaker":"西村委員","kind":"質問・要望","question":"区と都の役割も改めて伺いたいと思うのですが、立入調査をすることができるというふうに今確認をさせていただきました。桐ケ谷斎場は我が区にありますし、区民の方々が多く使っている施設ですので、どうぞ引き続きの調査計画を行ってほしいと求めました。","respondent":"舩木生活衛生課長","answer":"非常に非営利性といいますか、永続性、こういったものがしっかりと担保されている必要があります。いずれにしましても、しっかりと適正な運営がなされているかと、こういったところを保健所の立場としては確認をしていきたいと考えております。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"葬儀までは生存権や共助の範疇ではないかと私は思っておりますので、公平性が求められるべきだろうと思いますから、よろしくお願いします。これ、構成５区や都市部においては異なるということでしょうか、伺います。","respondent":"吉野戸籍住民課長","answer":"委員のご認識のとおり、日本全体と組織区５区でいきますと、組織区５区のほうは、ちょうど団塊の世代のお子さんが亡くなられるのが２０６０年という形になっております。","id":"exchange-006"},{"speaker":"西村委員","kind":"意見","question":"こういった５区における特別な状況もあると思いますので、引き続きお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、２点お伺いいたします。１４１ページ、幼保一体施設幼稚園運営費、９５ページ、オアシスルーム・ポップンルームの運営について、それぞれお伺いしてまいります。","respondent":"立木保育課長","answer":"令和６年４月一次入園の入園選考結果におきましての認可保育園の不承諾数に関しましては、７４０という数字になってあります。それから、認可外保育施設の保育料助成、ベビーシッターの利用支援事業についてのご案内を同封しています。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"数も７４０ということで確認させていただきました。幼保一体型の幼稚園も就労のための選択肢の１つとなることや、認可外保育事業なども併せて周知することを求めますが、区の見解を求めます。","respondent":"立木保育課長","answer":"幼児教育を中心としている幼稚園と、１日のカリキュラムで若干の違いがありますので、そこの混乱を避けるために記載をしていなかった部分があります。そちらのほうで丁寧なご案内をさせていただいている部分ですが、今後も、より丁寧にご案内をさせていただきたいと考えておりま…","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"こちらは要望で終わります。次に、オアシスルームの運営についてお伺いします。","respondent":"石井保育支援課長","answer":"オアシスルームの稼働率等につきましては、現在、集計中ですけれども、おおむね３割程度の方がリフレッシュで使われております。令和元年度、２万３,０００名程度のご利用があり、今年度についても約２万３,０００名程度のご利用が見込まれるというふうに承知しています。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"２万３,０００名で増加傾向とのことで、また、リフレッシュのためとの理由から、区民のニーズの高さを確認させていただきました。例えば、保護者以外の親戚で本人の確認のできるマイナンバーカード等による事前登録ができて、区の見解をお聞きできればと思います。","respondent":"石井保育支援課長","answer":"事前登録ですとか、あとは利用の開始のときに、どのような方でもお迎えができるのではないかと考えています。どうやって安心安全に引渡しを行うか、こういったところも課題がありますので、現場と相談しながら進めていきたいと考えています。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"一時保育、こども誰でも通園制度の事業展開を今後さらに進めてほしいと求めました。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"私からは、１４１ページの部活動指導員配置経費補助金に関連して、部活動地域移行について伺います。対象部活数や指導日数の具体値を含めて、令和５年度の計画と実績、令和６年度の計画についてお教えください。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"部活動指導員の計画ですけれども、令和５年度は各校２名枠、令和６年度は各校４名枠と考えております。令和５年度の利用実績ですけれども、令和６年２月末の時点で、１３校３０人を任用しています。 地域部活動の民間委託の成果や課題も生かしながら、令和６年度からは段階的に導入することといたしまして、４月から委託業務を開始予定です。現在、各校２種目程度で…","id":"exchange-013"},{"speaker":"山本委員","kind":"意見","question":"役割が異なるので単純に比較はできませんが、コスト的には１.７倍の差があり、民間委託に比べて部活動指導員のほうがコストを抑えることができます。部活動指導員は、令和５年度の利用実績で１３校で３０名と、ある程度進んでいる印象ですが、評価と課題を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"中には地域クラブに移行する部も一部あります。課題といたしましては、今年度以上に地域の方々のご指導をいただき、学校への導入拡大を図る必要があると考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"部活動指導員を１人に限定せずにサークル単位とすることはできませんでしょうか。サークル単位が無理でも、１種目に対して複数人、例えば、三、四名程度を登録して、輪番やシフトで勤務することは可能か尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"ただし、会計年度任用職員となりますので、ある程度、曜日が固定されるということがあります。団体を部活動指導員として登録することは、現状の制度では難しいと考えております。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"複数名を登録することができるということは確認できてよかったです。新たにＮＰＯ法人を設立し、教育総合支援センターの事務負担軽減と、部活動指導員側の利便性向上を図ることを検討してはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"令和６年度からは、勤怠管理につきましては、各学校において行えるよう調整を行っています。まずは国が進めている現在の仕組みの中で充実を図ることが大切だと考えており、次のステップについては今後の話だというふうに考えてあります。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"制度改定と対応できる仕組みづくりの検討を要望し、次の質問に移ります。続いて、ここまで区として実施している地域部活動の取組について伺います。","respondent":"中谷指導課長","answer":"バドミントン、３０名、全１０回、計画どおり実施、様々な練習方法を知ることができた。ダンス、３５名、全５回、計画どおり実施、先生が指導してくれて踊りやすかったなどとなっています。","id":"exchange-017"},{"speaker":"山本委員","kind":"意見","question":"３０名が参加できてよいと思いますが、いいコーチから指導が受けられる、平等性に対する課題があると考えます。それを踏まえた来年度の取組方針について、お教えくださいとの意見を述べました。","respondent":"中谷指導課長","answer":"今後の学校部活動のよりよい民間委託に生かしていくものとして、次年度、実施予定はございません。最後に、ダンスですが、多くのニーズがあることを踏まえまして、参加希望者の受入枠を拡大してまいりたいと考えております。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"予算を有効に使うべく、多くの子どもたちが参加するように取組を進めていただくことを要望して私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"確認","question":"６７ページ、１０９ページ、議事録経費について伺います。名簿を提供するという形をとっているのかいないのか、確認させてください。","respondent":"吉野戸籍住民課長","answer":"自衛官の募集に際しての情報提供ですけれども、こちらは現在行っていない状況です。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問いたしますけれども、これ、何とかオール役所で、工事に伴う期間の活動を保障できるよう対応を求めたいと思いますが、いかがでしょうか。公園課、高齢者地域支援課でしっかり連携して、具体的な対策を検討していただきたいのですけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"昭和４５年に開設以来、もう既に５０年以上もたっているということで、必要な全面改修工事であるというふうに区としては認識しています。説明会のときにも申しましたとおり、今後、前向きに検討していきたいと考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会制民主主義、質問を通して住民要望を実現させる私たち議員にとって重要であることは言うまでもありません。最終的に、会議録検索システムの掲載、それぞれどれぐらいかかるのか伺います。","respondent":"大澤区議会事務局長","answer":"その後のホームページの掲載は、速報版を、本会議は１週間程度、委員会は２週間から３週間程度でアップしています。正式な会議録としましては、掲載まで２か月ほどを要しているのが現状です。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"仮に、議会から要望があれば、議事録作成予算１,２９２万円余ですけれども、これ、民主主義のコストだと思います。予算を増やすことで議事録の作成を早めることは可能だと思うのですけれども、いかがか尋ねました。","respondent":"大澤区議会事務局長","answer":"議会改革推進会議につきましては、平成２９年度から計１６回開催されてあります。反訳の納品についての契約変更ですとか、それぞれに様々課題もありますので、検証が必要だと認識しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"先ほど申し上げましたように、議会制民主主義の根幹に関わるところで支障が出ているわけです。それが私たちの仕事なわけですから、ぜひ区長部局の皆さん、ご検討をしっかりよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"私からは、５０ページ、特別区民税、１５２ページ、財政調整基金、１５１ページ、ふるさと納税寄附金など、歳入全般にわたってお聞きいたします。特別区民税が減っていて、しかし、歳入全体が増えているということについてのご所見をお伺いいたします。","respondent":"遠藤財政課長","answer":"そちらの部分で減収分については国のほうから補填していただけるという流れになっておりますので、減収分については、実質的には変わらないと考えているところです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"引き続き、チャレンジングな事業にも挑戦できる予算に今後なっていくのかどうか、その辺りをお聞きいたします。今後の予算立てをしていくべきかと考えているのですけれども、今述べたことを踏まえまして、今後の予算立てについてのご見解を説明を求めました。","respondent":"遠藤財政課長","answer":"今後の予算立てですけれども、１つは、人口動態がありますけれども、何よりも経済状況の影響が大きいかなと考えているところです。平準化という形で、区民の需要、行政サービスにしっかり応えられるような形で組んでいければなというふうに考えているところです。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。１つ、特に第１条が、それを崩していけばいいのではないかというようなお話をよく伺うのですけれども。","respondent":"遠藤財政課長","answer":"なかなか一言で説明するには難しいところではあるのですけれども、例えば、２１億円ほど繰入れをさせていただいているところがあります。２年に１回、今回、基金の繰入れをさせていただいているという形でさせていただいたところです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"かなり多めに出していくというお考えなのか、また、積立ての目標はあるのでしょうか。順調に令和２年度、令和３年度、令和４年度、増えておりますけれども、幾らぐらいまで積み立てていこうかというお考えが何かあるのか尋ねました。","respondent":"遠藤財政課長","answer":"おおむね標準財政規模の１０％、２年分という形で考えているところがございまして、２００億円という形になるかと思っているところです。特別区の平均で、ここの部分については、何が適正かということは考えていかなければいけないかと思っているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。ふるさと納税を伺いますけれども、令和５年度４５億円ほどということでしたけれども、令和６年度の減収額の見込みをお知らせください。","respondent":"提坂税務課長","answer":"令和６年度につきましては、まだ確定値ではございませんけれども、５０億円を超える見込みです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"そろそろいい加減にしてほしいというような感じなのですけれども、そういう制度の変更を区長会でぜひ提言していただきたいと思っているのですけれども、いかがお考えか尋ねました。","respondent":"提坂税務課長","answer":"中には、返礼品は要らないので寄附をしたいという方も、年間、毎年１０件から２０件程度はあります。今後、クラウドファンディング型ふるさと納税というものをつくっていきたいと思っておりまして、これは区民の方もご寄附ができる形になってあります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"意見","question":"１０件ほどいらっしゃるということなのですけれども、分析でお分かりになれば、お知らせください。ふるさと納税を活用していくべきだと考えておりますけれども、その点、お考えを説明を求めました。","respondent":"提坂税務課長","answer":"返礼品は要らないけれども、寄附をしたいという方、そういうご意見も聞いてあります。クラウドファンディング型ふるさと納税も進めてまいりますし、区の魅力を発信する体験型返礼品も、なお一層拡充してまいりたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"提案","question":"職員の提案でやられるということで、本当に焼け石に水になってしまうかなと思っているのですけれども、ぜひ頑張っていただきたいと考えております。どのように広告を応募していくのか、その辺りをお知らせくださいとの意見を述べました。","respondent":"佐藤経理課長","answer":"こちらは、場所といたしましては、庁内のトイレですとか、あるいは、エレベーター内を検討しています。募集に関しては、来年度、４月以降に、要綱等を定めた上で募集して実施していこうというふうに考えているところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"庁舎内ですから、いわゆる景観的な配慮も含めたものが必要かと思いますけれども、ぜひ積極的に進めていっていただきたいと考えております。今後、ゆくゆくは、庁舎内から庁舎の外に展開していくということも考えておられるのか尋ねました。","respondent":"佐藤経理課長","answer":"今年度は庁舎内の広告ということで、職員提案の中から事業化したところです。今後につきましては、今回のものがテストケースになろうかと思いますので、効果等を十分把握した上で、全庁に展開するようにいたします。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ネーミングライツとか、庁舎内の今回の実績とか影響を見て、ぜひ積極的に有料広告を進めていっていただきたいと考えております。よろしくお願い申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"東京都の事業で、現在実施している学校数と支援員の人数を伺います。併せて、本事業内容では、どのような生徒が利用できるかなど、生徒側の条件を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"現在、校内別室指導支援員の配置ですけれども、区立中学校１校で行っておりまして、支援員は２名おります。学校には登校できますが、教室には入れない生徒を対象に行っている事業です。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"今、１校で実施しているということですけれども、生徒の利用状況はいかがでしょうか。校内別室とマイスクールの選択はどのように、生徒が選んでいらっしゃるのでしょうか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"現在の利用状況ですけれども、教室に入れない生徒が数名利用しているということで確認ができております。学校に登校できない生徒については、マイスクールという選択肢がありますので、ご家庭とよく相談して進めているものです。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"義務教育学校は前期と後期がありますが、それぞれ配置する予定でしょうか。週にどれくらいの配置を考えられますでしょうか、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"令和６年度には、校内別室指導支援員の配置を全校で実施いたします。それから、支援員の配置についてですけれども、１日４時間、週５日、４０週を目指して進めております。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"この校内別室指導の存在を知っておくべきだと思いますが、１校で行われているということですが、どのような周知をしているか伺います。こちらについては、どのように想定されていますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"来年度につきましては全校で実施いたしますので、教育委員会からも広く周知できるよう、今、検討を進めているところです。残りの４日、例えば、そういったものを工夫しながら校内別室指導ができるような体制づくりを各校に求めているところです。","id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"こちらのホームページに記載されている募集要項では、いずれかの要件に該当する方ということで、例えば、保護者でも応募が可能なのでしょうか。そして、募集を３０名程度としていますが、人数について、どのようなお考えで決めているのでしょうか、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"それから、要件を満たしていれば、保護者であっても可能というふうには捉えております。３０名程度というふうな考えですけれども、応募があった場合には、名簿には登載する考えです。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"サポートしたいという多くの方の目に触れていただけるように、応募していただけるような広報、周知をお願いいたします。ホームページ以外でも募集について広報しているかどうか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在、ホームページに掲載しておりますけれども、近隣の大学にも、学生ボランティアとして応募ができるように、今後、周知を図っていく準備を進めているところです。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"校内別室指導の部屋について、最後に伺います。こちらは学校側での判断になるかもしれませんが、この事業の運営上でそういったしつらえにすることは可能か尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"部屋の工夫ですけれども、これは各校の工夫によるものと思います。掲示物ですとか、そういったものを、温かな空間づくりができるように働きかけも行っていきたいと考えております。","id":"exchange-041"},{"speaker":"せらく委員","kind":"質問・要望","question":"区としてもそういった学校発信の独自の取組については、しっかり後押しをしてほしいと求めました。どうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"１点目に、児童虐待防止対策等総合支援事業費補助金についてお伺いいたします。それぞれの会議体の工夫や、コミュニケーションプレイスの設計について、現在の区のご見解をお伺いいたします。","respondent":"長谷川児童相談所開設準備課長、山下新庁舎整備課長","answer":"このため、開設準備段階におきましては、検察や裁判所を含めた各関係機関との綿密な打合せを実施し、顔の見える関係づくりを現在行っております。合同緊急受理会議をオンラインで実施するなど… 場合によりまして、適宜打合せができる職員共用の執務サポートエリアを各フロアへ設置することを考えてあります。会議室におきましては…","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"４月から始まる東京都からのケースの引継ぎはとても大変な作業だというふうに、様々、児童相談所のほうから伺っています。２点目に、健康増進事業費についてお伺いいたします。","respondent":"若生健康課長、榎本荏原保健センター所長","answer":"国の健康増進法の基本方針です「健康日本２１」の第三次におきまして、健康づくりのための睡眠ガイドを取りまとめております。病気が潜んでいる可能性にも留意するとされております。 私からは、睡眠に関する健康相談についてお答えいたします。本人の心の状態に合わせて、そのご相談を受けながらお受けしているという状況です。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"地域振興基金繰入金、協働推進経費についてお伺いいたします。網の目を張り巡らせることなどを事業を通して構築することが求められていますが、マッチングの難しさについて区はどのようにお考えか尋ねました。","respondent":"若生健康課長、宮澤地域活動課長","answer":"私から、睡眠に関しての区の取組というところでお答えいたします。ホームページ等でそうした情報発信をしていくことを検討するとともに、次年度、そちらの検討委員会の中でも睡眠や休養に関して検討してまいります。 機会を創出するというところで、先日も町会とＮＰＯとの意見交換会であったり、企業や団体同士の交流の場の創出も検討しています。すまいるネットでの情報発信というところで…","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"地域づくりについて、人づくりは非常に重要で時間もかかりますので、ぜひ進めていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"お伺いしたいのが、それは２０％増であれば５５億円ぐらいになるのだと思うので、見込みをどれぐらいと考えていらっしゃるのか。昨年の最新状況を分かればお聞かせいただきたいのと、今年については、どういった見込みで予測を立てていらっしゃるのか説明を求めました。","respondent":"提坂税務課長","answer":"今年度１月末現在で、流入が２,４００万円余です。クラウドファンディング型ふるさと納税、それから体験型返礼品の拡充ということをもって、全部で９,０００万円を見込んでいるところです。","id":"exchange-047"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"もう一度確認ですが、当然、この１,９００万円の数字を９,０００万円に上げていくということで間違いがないのかお聞かせほしいと求めました。区の姿勢を改めて確認したいのですが、これが変わっていくのかどうかということと、区民へのＰＲになります。","respondent":"提坂税務課長、佐藤企画課長","answer":"令和４年度、これはあくまでもふるさと納税の寄附金として１,９００万円余のご寄附をいただいたということで、令和４年度は９,８００万円あったです。 区としては初めて方針を強めてやっていくというところで、４５億円の２％で９,０００万円を設定して、まずは目標を設定したところです。区民の共感を得られるよう、方針等もきちんと定めて、より積極的に進めていきたいと考えておりま…","id":"exchange-048"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"今、ふるさと納税でどれぐらいを目指すという計画があるのかお聞かせいただきたいのと、必ず今まで税務課がお答えをされていらっしゃったと思います。これは税務課ではないのではないですかと以前もお話をしながら答弁をいただいていたと思いますが、どこがお答えをされるようになるのか尋ねました。","respondent":"提坂税務課長、佐藤企画課長","answer":"来年度の流入額というか予算額ですけれども、全部で９,０００万円、その中でふるさと納税の寄附という形で２,４００万円を見込んでいるところです。来年度以降は、質問内容によって… 返礼品競争に加担しない方針に基づいてやってきたのですが、税務課のほうで、様々なツール等について情報収集して一定のノウハウを持っています。区として、流出額の抑制と流入の増を図るという方針といたしましたので…","id":"exchange-049"},{"speaker":"せりざわ委員","kind":"提案","question":"質問に応じてということで、事務手続は税務課でないとできないですから、別の形でぜひこのふるさと納税に取り組んでほしいと求めました。それももう１つ、私が提案した屋形船も実現できて大変うれしいのですが、なかなかプレミアがないと言われましたとの意見を述べました。","respondent":"提坂税務課長","answer":"単なる入場券とかチケットということではございませんので、委員のご指摘したように、少しプレミアをつけたようなものをいろいろ工夫してまいりたいと考えています。","id":"exchange-050"},{"speaker":"せりざわ委員","kind":"提案","question":"ほかに幾つかご提案しますが、やはり２３区は特にそうですが、ほかのところも動き出していると思います。デジタル商品券の提案もさせていただきましたが、そういったところも含めて、新たな返礼品の提供もご検討ほしいと求めました。","respondent":"提坂税務課長","answer":"体験型の返礼品に重点を置いて拡充を進めるべく準備を進めているところですけれども、新年度へ向け、電子クーポンの取扱いを図ってまいりたいと考えています。","id":"exchange-051"},{"speaker":"せりざわ委員","kind":"提案","question":"最後に、もう１個だけ提案をしますが、先ほどのシティランのところで、筒井委員からもお話がありました。しながわシティランの広報も含めて、そして財源確保も含めて、ぜひご見解をお聞かせほしいと求めました。","respondent":"三井スポーツ推進課長、佐藤企画課長","answer":"区民が輝く大会ということで、区民中心を考えておりまして、大会のコンセプトから少し外れてしまうようなところもあるかなと考えております。第１回目となりますので、委員からのご提案も踏まえて… ふるさと納税の活用に関するクラウドファンティング事業としてシティランは入っておりますので、様々検討してまいりたいと思います。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"１２７ページ、１４１ページ、１６３ページのマイガーデンについてお伺いしたいと思います。近年、コロナ流行により中止になったと伺いましたが、再開はされたのか尋ねました。","respondent":"河合生活安全担当課長","answer":"パトロール関係の再開等は、こちらのほうでパトロール活動の助成を行っておりまして、再開はされているというお話は聞いております。基本的に歳入のほうの、こちらは防犯カメラ、防犯の対策の助成金となっておりますので、この歳入は、これまでの実績を含めて計上しています。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続きまして、１４１ページ、いじめ防止対策についてお聞きします。最近の区内のいじめ問題の状況と、その対応について説明を求めました。","respondent":"勝亦総務課長","answer":"私から、区長部局の窓口に来る相談と教育委員会との連携について、ご説明します。そういったものに関しまして、事情をお伺いして、学校と状況を１つ１つ確認しながら、打合せ等をしながら対応を図っているという状況です。","id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"教育委員会について、追加でお聞きします。教育委員会の方の人選はどのように行っているのか尋ねました。","respondent":"勝亦総務課長","answer":"教育委員会の人事案件ですけれども、まず、今年度、春に公募させていただきまして、６月に公募した方を候補者とさせていただきまして、９月の第３回定例会において議案提出させていただいて、任命していただいているところです。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"第３回定例会でも、お一人の方が任命されて、着任していただきました。その辺はいかがか尋ねました。","respondent":"勝亦総務課長、堀越総務部長","answer":"教育委員会の任命に関しましては、任命の同意を議会にいただく関係があります。そういった中で丁寧にご説明していくようにしていきたいと考えています。 議会運営委員会でのご説明ですとか、法にのっとって説明させていただき、このように考えているところです。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私たちも判断という部分を任される以上、できれば様々な情報をいただきたいと考えています。今後も品川区の教育のために、一緒になって頑張っていきたいと思いますので、ぜひご協力を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問","question":"私からは、１２５ページ、病児・病後児保育委託、１３１ページ、東京ユースヘルスケア推進事業、不妊治療等支援事業についてお伺いいたします。そして、現状どのように対応されているのかということをお伺いいたします。","respondent":"立木保育課長","answer":"一昨年１２月にクリニックの閉院に伴いまして、今、空白になってあります。もろもろ諸般の事情によりまして、今のところ、まだ開設の見込みが立っていないというような状況です。","id":"exchange-058"},{"speaker":"新妻委員","kind":"質問","question":"諸般の事情、様々ご事情があるかと思いますが、その課題について、品川区がその支援ができるところはないのか尋ねました。","respondent":"立木保育課長","answer":"例えば、町のクリニックで申しますと、開設に当たりましての補助金を出したりとか、運営に当たって、例えば保育士の雇用に関してのサポート等は、今後いろいろ考えていかなければいけないというふうには考えているところです。","id":"exchange-059"},{"speaker":"新妻委員","kind":"質問・要望","question":"具体的に、その課題が解決できますところをしっかり品川区が支援を進めていただきまして、開設に届きますように、よろしくお願いしたいと思います。そして、病児シッターと言われているのでしょうか、需要と供給がしっかり見合っているのかというところを確認させてほしいと求めました。","respondent":"立木保育課長","answer":"ベビーシッターは、今、やはりまだベビーシッターの中で病児対応ができるシッターの数は十分でないというところは聞いているところです。ただ、お願いできるベビーシッターもいる中では…","id":"exchange-060"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、次に、東京ユースヘルスケア推進事業についてお伺いいたします。どこの予算なのかということをお知らせほしいと求めました。","respondent":"若生健康課長","answer":"東京ユースヘルスケアの予算についてですが、こちらは、充当先が不妊治療等支援事業となっていますので、これは１０分の１０で東京都の補助金ですが、こちらを活用いたしまして、今回、不妊治療等の相談事業を行っていくというような予定になってあります。","id":"exchange-061"},{"speaker":"新妻委員","kind":"提案","question":"昨年の第３回定例会の一般質問で、私もこの事業を活用して相談体制を整えてほしいという、そういう趣旨の提案をさせていただきました。今回、職員提案ということで決定されたと聞いておりますけれども、どういう経過でこれに至ったのかということをお知らせほしいと求めました。","respondent":"若生健康課長","answer":"こちらの不妊の相談事業に関して、職員提案の経緯です。予算化に至ったところで、区としては、取り組むことにしております。","id":"exchange-062"},{"speaker":"新妻委員","kind":"意見","question":"ただ、その上で、相談がしたいのだというお声がありました。そこが大事なのだというお声をいただきましたので、品川区がこれから始める相談事業について、少し説明を求めました。","respondent":"若生健康課長","answer":"電話相談と、直接オンラインでの相談、この２パターンを予定しております。専門のカウンセラーが対応するということになりますけれども、月に１組４５分程度で４つの枠でという想定で、準備を進めているところです。","id":"exchange-063"},{"speaker":"新妻委員","kind":"質問・要望","question":"その方は、東京都の相談をした際に、なかなかタイミングが合わなかったというお声がありました。そこもご検討いただく中で、ぜひ進めてほしいと求めましたが、いかがか尋ねました。","respondent":"若生健康課長","answer":"今後、これは新規の事業で、来年度、夏過ぎ頃から開始していく予定です。まだこちらについては準備の時間がありますので、十分中身、相談しやすい環境を検討してまいりたいと考えております。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問","question":"６９ページ、１３１ページ、不妊治療等支援事業について質問をいたします。次年度からの開始になるとは思いますが、区独自の不妊治療助成について、男性不妊の場合も利用できるのかについてお伺いいたします。","respondent":"若生健康課長","answer":"男性でも相談しやすいような環境づくりというところで、これから事業を構築してまいりますけれども、十分検討していきたいと考えております。それから、不妊治療費の助成ですが、こちらについては、男性の不妊症の治療費についても対象とする予定です。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問・要望","question":"どうぞご参加ください。文化センターの意義や役割について説明を求めました。","respondent":"篠田文化観光課長","answer":"文化センターについてのお尋ねです。文化センターの設置につきましては、スポーツ、主に社会教育活動をすることを想定して設置されているものです。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"旗の台の文化センター、２階部分にあって、施設に入るまで階段があるために障害がある方が利用できない。区有施設のバリアフリー化に対する考えや課題、今後の展開についてもお伺いいたします。","respondent":"篠田文化観光課長","answer":"何らかの形で外づけのエレベーターとかがつかないかということで検討はしてきたのですけれども、なかなか古い建物で難しいということがあります。その際には、大幅にバリアフリーに配慮した形での改築ということで対応していますので…","id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問・要望","question":"なかなか、予算も関わってくることがあると思うので、課題があるということは認識しております。もちろんバリアフリー化もしてほしいと求めましたが、障害がある方の声も計画の段階から取り入れてほしいと求めましたが、いかがか尋ねました。","respondent":"篠田文化観光課長","answer":"建物自体の古さ等々がありますので、すぐには難しいところがありますけれども、今、委員からご指摘があったとおり、改築の際の配慮と同時に、日頃からも職員のサポートで対応できる部分があれば、そこについては尽力してまいりたいと考えているところです。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ全ての方が利用できるような施設を区としても目指していただきたいというふうに要望いたしまして、次の質問に移ります。そこでお伺いします。","respondent":"三井スポーツ推進課長","answer":"２月末時点ですが、月平均で大体２４０件ほどあります。最初２か月は、オープン当初は平均して３００件を超えていましたので、現在は少し減少傾向となっております。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"意見","question":"現在、減少傾向ということで把握いたしました。利用の多い年代や利用した方の反応等があれば、説明を求めました。","respondent":"三井スポーツ推進課長","answer":"今年度、初心者教室は７月から実施しまして、現時点で６回ほど開催しております。人数ですが、今、手元になくて、合計ですと６５名の参加となっております。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"利用者がオープン当初に比べて減っているということですが、区としての課題は、どのように認識していますでしょうか。どういうところがよかったのかなど、声を聞くことも有効かと考えますが、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"今後、公園課とも連携しながら、教室開催の際などはＳＮＳ等で積極的に周知を図ってまいりたいと考えております。アンケートについては、今後、教室等でとれないかということは検討してまいりたいと思います。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"意見","question":"特に冬だったりとか、逆に暑過ぎたりするときだと、外だとなかなか利用につながらないのかなというふうに実感として感じております。月１回ぐらいボルダリング教室を開催していると思うのですけれども、そういう工夫もされてはどうかと思うのですけれども、説明を求めました。","respondent":"三井スポーツ推進課長","answer":"やはり委員おっしゃるとおり、夏とか、暑い日、寒い日とかというのは、なかなか教室は集まりづらい状況はありますので、今後、そちらも踏まえて考えてまいりたいと思います。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問・要望","question":"民間の施設だと、まず、品川区のこの中央公園のホールドの位置は変えられるのか。もし変えられるとしたら、どのぐらいの頻度で変えていく予定なのかというところも、分かりましたら、説明を求めました。","respondent":"高梨公園課長","answer":"今年度４月にオープン以来、もう３回、ホールドは変えてあります。年２回、ホールドを購入して、４回変えるというところでやっているところです。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"意見","question":"その４回、来年度以降、実施する際には新しくなりましたというようなところを併せて周知をしていただければなと。それに併せて教室の開催の頻度等も検討していただければいいなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"中塚委員","kind":"提案","question":"所管が予算を提案しても、こうしたやり取りが、企画や区長査定であるのかどうか伺いたいと思います。メニューがあるのか、あっても少ないのではないかと思うのですけれども、いかがか尋ねました。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"一般財源を中心に事業を実施していますが、活用できる国や都の補助は最大限活用する、これは区の方針となっております。防災事業についても同様にそれを活用させていただいておりまして、効率的… 先日も答弁申し上げましたが、来年度に向けて、ペットの備蓄を少し進めていくということで考えております。経費の２分の１の補助率ということで、上限額１４５万円、そういったものを今後備蓄していこうというふうに考えております。","id":"exchange-075"},{"speaker":"中塚委員","kind":"提案","question":"私が伺ったのは、所管が予算を提案しても、こうしたやり取りがあるのかと伺いました。お答えくださいとの意見を述べました。","respondent":"平原防災課長","answer":"そういったものを活用するということで、今、提案側としては要望させていただいているところです。","id":"exchange-076"},{"speaker":"中塚委員","kind":"提案","question":"国や都に財政負担を求めることは必要だと思いますけれども、改めて、その考えを伺いたいと思います。必要性を認めているのですから、積極的に事業展開をしていく必要があると私は思いますが、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"今回、携帯トイレという形で、全て一般財源でやらせていただいているようなところがあります。きちんと措置するという考えで、この間、査定をしています。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、現状としては、一般財源の負担が多いわけですから、区の姿勢もあらわれてくるのかなと考えています。区がなかなか重い腰が上がらないという構造が根底にあるのではないかと思うのですけれども、改めてこの点を伺いたいと思いますが、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"あるいは高齢者、子どもに対する支援など、様々あるところです。今後も一般財源の使い方も含めまして、様々なご意見等を頂戴しながら、こちらの施策をつくっていきたいというふうに考えているところです。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"国がペットの同行支援に言及して、それを受けた形で補助金が出て、ようやく品川区が動き出している。だから区が動けないと、これではいけないと思いますので、区民に寄り添った防災対策を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１５５ページの奨学金貸付金返還金に関わって、区独自の奨学金実施を求めて質問します。現在の返済をしている方の人数を伺います。","respondent":"飛田子育て応援課長","answer":"平成３０年度からは制度改正を行いまして、在学応援資金を創設の上、返還免除型を導入しております。委員のご質問の現在の貸付けの状況ですが、令和６年１月現在で２２４件中７６件ほどの滞納が発生しております。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"制度を始める前と後の公平性を言ってしまったら、どのような制度も始められないと思いますが、いかがでしょうか。伺います。","respondent":"飛田子育て応援課長","answer":"やはりこの間でも、様々なご事情がありながらも、当初予定したように返済をしっかりなされている方もいます。滞納とか返済につきましては、やむを得ない事情がある場合には、こちらも相談に応じて、さらに分割するなど柔軟な対応をとっているところです。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"返済を免除するときには不公平と説明するのはなぜなのか、伺いたいと思います。子どもたちの明るい未来のためにも、返還金の免除に踏み出すべきだと思いますが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"今回、平成３０年度から制度改正ということで、制度自体を変えたというところで在学応援資金をやっております。ここのところですが、制度上の違いというところで最初の枠組みをしっかり守っていきたいと考えています。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"少し説明がよく分からなかったのですけれども、この制度をよくしていくときには、やはり違いが生まれると思うのです。ぜひこの点でも返還免除に踏み出していただきたいと思うのですけれども、改めて伺います。","respondent":"飛田子育て応援課長","answer":"ただ、新しい制度については、応援資金ということで返済免除も頑張ればしますよというところで最初にうたっております。そこのところは、やはり大きな違いではないかと考えております。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、大学生等への給付型奨学金を求めると、国や他区の動向を注視すると答弁されています。注視した現在の結果はどうなっているのか伺います。","respondent":"飛田子育て応援課長","answer":"様々に国や日本学生支援機構、または各大学においても、それぞれ奨学金や授業料免除制度を整えているところです。１人当たりの金額も高額になるため、議論、改善されるものと考えております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"国が全体でやるべきだと思いますけれども、その中で区ができるところで、ぜひ大学生等への給付型奨学金に踏み出してほしいと求めました。実施できない理由はあるのでしょうか、伺います。","respondent":"飛田子育て応援課長","answer":"現在そういった格差是正のために、低所得や成績優秀者などを対象とした給付型の奨学金、主に中間層を対象にした貸付の奨学金については、国や日本学生支援機構、また各大学に多くありまして、近年は一定程度充実してきていると認識しております。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"充実しているということは、もう十分だというふうに感じているのか伺いたいと思います。そうした中では、ウェルビーイングの観点からも、意に反するものだというふうに思うのですけれども、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"確かに委員おっしゃるとおり、子どもの未来、また、夢を応援することは非常に重要だということは認識しております。もろもろ考えますと、区単独で実施するには、まだ課題が多いと感じているところです。","id":"exchange-086"},{"speaker":"澤田委員","kind":"質問","question":"私からは、１１７ページ、高次脳機能障害者支援促進事業について質問します。３８万７,０００円の減額となっていますが、こちらについては、どのような部分が減額されたかについて説明を求めました。","respondent":"松山障害者支援課長","answer":"高次脳機能障害者の専門相談員の配置などを含めまして、事業については変更はなく、専門相談員の人件費分は変わりません。次年度からは、会館内の自立訓練センターの作業療法士が講師を担うことになったため、外部講師の費用を減額したためです。","id":"exchange-087"},{"speaker":"澤田委員","kind":"質問","question":"今まで外部に委託していた講師料の部分を、作業療法士などの方を用いて行うことで削減できたということが分かり安心いたしました。こちらの実績と、実際に参加された方たちからどのようなお声があったのか、もしあれば説明を求めました。","respondent":"松山障害者支援課長","answer":"今年度は５回実施いたしまして、参加者数は延べ２４人でございました。障害や脳機能について初めて知り、理解が深まりましたというお声をいただいております。","id":"exchange-088"},{"speaker":"澤田委員","kind":"質問・要望","question":"今後とも積極的にこちらの活動についても周知していただきたいと思っているのですが、区としては、どのような周知を行っていますでしょうか。私も昨年の決算特別委員会で、リーフレットのリニューアルについて要望させていただきましたが、その件についても併せてご回答をお願いいたします。","respondent":"松山障害者支援課長","answer":"その動画につきましては、ケーブルテレビ品川、しながわホットほっとや、しながわネットＴＶ、ＹｏｕＴｕｂｅで３月中に放映する予定です。委員ご要望のリーフレットも含めまして、指定管理者と協議し、周知を積極的に進めてまいります。","id":"exchange-089"},{"speaker":"澤田委員","kind":"質問・要望","question":"特にケーブルテレビ品川に３月中に動画の放送があるということで、情報を求める方々にも広くお伝えできると思いますので、大変うれしく思います。ＹｏｕＴｕｂｅなどにアップするご予定がまずあるのかということをお聞きしたいのですが、その辺についてのお考えもお聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"さらなる周知ということで、委員ご提案のＳＮＳを使った周知等も積極的に進めてまいります。","id":"exchange-090"},{"speaker":"澤田委員","kind":"質問","question":"それと、先日、ぐるっぽにて、当事者と、その家族と、施設の方々の交流会が開催されたと参加された方から伺いました。ぜひ区としてもサポートしていただけると、より充実したものになるのではないかと考えられますが、区としてのご見解を説明を求めました。","respondent":"松山障害者支援課長","answer":"１０人の方が参加されまして、時間が１時間程度だったので、もっと長くやってほしかった。一緒にどういう形でつくっていくのかということを、指定管理者、区も一緒に考えていければと考えています。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"昨日に続いてなのですけれども、先ほどご答弁がありました９,０００万円、歳入の予定の内訳を改めてもう一度お聞かせいただいてもいいですか。寄附か、ふるさと納税で入る収入かを分けてお願いします。","respondent":"提坂税務課長","answer":"ここに６項目出ていますけれども、それにご賛同いただいた方にご寄附いただくということで、ここに６項目で合計６,６００万円。一般分と合わせて合計９,０００万円という形になってあります。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、ふるさと納税での２,４００万円ということで、今年度は見込みは幾らなのか説明を求めました。","respondent":"提坂税務課長","answer":"１月末の時点で、税務課として返礼品をお返ししている分が４０２万円、子育て応援課の子ども食堂の関連が２,０５０万円余となっています。合計で２,４００万円余です。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、前年度と来年度、同じぐらいのふるさと納税の収入ということか尋ねました。","respondent":"提坂税務課長","answer":"流出額が年々２割増しぐらいで増えているということを懸念しまして、そういうようなものを新たに導入して、かなり増額したいと考えています。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これを待っているよりも、やはり今できる中で我々ができることをしていくべきだと思います。ＩＭＡＧＩＣＡをはじめとして映像クリエーターの方たちもたくさんいらっしゃるところですから、ご意見のほど、お願いいたします。","respondent":"提坂税務課長、佐藤企画課長","answer":"区政にご協力いただいている区内の様々な企業の方のご意見等を聞きながら、体験型、事の体験の返礼品として導入できるものがないかということを模索していきたいと考えています。 もう既に企画課と総務課と税務課と、関係各課でＰＴを組んで、今年度、検討も開始しておりまして、今回、様々な提案をしています。様々な分析をしながら、効率的に歳入を増やしていきたいと考えておりますので…","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"内容としては、例えば、障害者の方とか、性的マイノリティの方とか、外国人の方、そういった方について、例えば人権が守られていると、そういったようなことも当然教育の内容として入っていますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今おっしゃっていただいたような人権課題につきまして、それぞれ学習を進めているところです。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"質問","question":"差別は許さないということで承知しました。人権啓発事業も同じような取組との理解でよろしいか尋ねました。","respondent":"加島人権啓発課長","answer":"５月の健康週間ですとか、それから性的マイノリティを含めた人権尊重のパネル展示を実施したり、多様なルーツを持つ方を講師にお招きしています。そのような取組を、今、行っております。","id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問","question":"改めてお伺いします。品川区として、在日特権はないという理解、そして、そういう教育方針ということでよろしいか尋ねました。","respondent":"加島人権啓発課長、提坂税務課長","answer":"たしか国会での答弁は、税制面での優遇について在日特権はないという答弁であったかと思います。多様性の尊重を進めていくことが大事だと思いまして、その部分で人権尊重教育、啓発事業を進めております。 特別区民税、いわゆる住民税についても、前年の１年間の所得に応じて税額を計算しまして、国籍に関わらず、日本人、外国人の方に等しく課税しています。","id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"質問","question":"このことをしっかりと、それを信じている方が一定おられて、それが差別の温床になっているというような実情があります。２３区唯一の人権尊重都市宣言をされている品川ですから、ヘイトをあおるような誤った情報、デマを教育段階から未然に防いでほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"つる委員","kind":"質問","question":"６１ページ、７１ページ、高齢者多世代交流支援施設使用料について伺っていきたいと思います。この法律に基づく基本計画、品川区が、今、策定している段階なのか、また、その有無についてお知らせください。","respondent":"飛田子育て応援課長","answer":"困難な問題を抱える女性への支援に対する基本的な計画ということで、現在、まずは関係機関との連携の在り方を具体化していきたいと考えております。現段階では、まだ計画は考えてはいないところです。","id":"exchange-100"},{"speaker":"つる委員","kind":"確認","question":"東京都の策定状況を確認してということで、関係機関ということでお話がありました。特別区としてやるべきもの、できる規定とかがあると思いますが、そういう意味である有無について説明を求めました。","respondent":"飛田子育て応援課長","answer":"女性相談支援センターの支援体制が強化されることや、支援、自立に向けた支援に変わっていくなど。今までの「保護」から「自立への支援」ということになりますので、そのためには民間支援団体の協力が必要だと思っていますので。","id":"exchange-101"},{"speaker":"つる委員","kind":"質問・要望","question":"なかなか行政に助けを求められない、また求めようとしても求めることができないという、そうしたニーズのある方もいらっしゃるわけであります。令和３年度ぐらいから、この辺りについて、品川区の受け止めを説明を求めました。","respondent":"飛田子育て応援課長","answer":"委員おっしゃるとおり、若年女性の支援ということでも今後大きく注目を浴びていくと思います。やはり同じように保健部門、そういうところとも連携をとりながら、関係機関と調整の上で検討していきたいと考えております。","id":"exchange-102"},{"speaker":"つる委員","kind":"質問・要望","question":"先日、新妻委員から情報提供をもらって、先ほど午前中もたしか葬儀についてまでの支援ということについての質疑の確認はありました。亡くなられた方がお墓を持っているかどうかという確認をする作業をすることで、千葉などにもたしかあったかと思いますが、そういうところもあります。","respondent":"吉野戸籍住民課長","answer":"私ども戸籍住民課は、委員のご指摘のとおりですけれども、埋・火葬の許可証を実際に窓口でやっているところであります。墓じまいとか、そういったところの支援の在り方に関しましては、今後の検討課題といいますか、研究させていただきたいと考えています。","id":"exchange-103"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひそこまでやってほしいのです。そういう一部事務組合方式なども含めて、このお墓の課題については、ぜひ全庁的にいろいろな観点から検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"石田（し）委員","kind":"質問","question":"１５０ページ、１２９ページの医療保健政策包括補助金の予防接種について、国や都の補助金など全体的な少子化対策についてお伺いします。キャッチアップ接種がいよいよ約１年といった中で、今回男性への助成を開始するとともに、どのような取組をされていくのか説明を求めました。","respondent":"提坂税務課長、佐藤企画課長、坂野保健予防課長","answer":"やはり魅力ある事業を発信して、こちらにご理解をいただいて、少しでも区民の方にそちらに回していただけるということが一番の大きな策かと思います。… 若干補足します。今回、これだけ区のお金が出ているというところ出しながら、流出入に関しまして積極的に対応していきたいと考えております。 令和７年３月末でキャッチアップが終了という形になります。今の予定では、２万２,０００名の対象者の方に個別の接種通知を送ると…","id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜ今日、私がこれを質問したかというと、実は款があまりないのです。情報発信をしてほしいと求めましたが、改めて、その辺のお考えを説明を求めました。","respondent":"佐藤企画課長、坂野保健予防課長","answer":"まずは区といたしまして、流出が４５億円あるという事実を多くの区民の方に感じ取っていただくと。例えば、４５億円ありましたら保育園が複数つくれますとか、まずは事実をはっきりと伝えていきたいというふうに考えております。 ＨＰＶ月間、予防接種の週間のお話がありました。申し訳ございません、なかなかそれは対応できていなかった部分がありますので、次年度以降の課題とさせていただきたいと思います。","id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜそう言っているのに、今日どうしても言いたかったのはなぜかというと、週間中なのです。だから私は発信をしてほしいと言っているのだけれども、なぜ来年度になるのか尋ねました。","respondent":"辻広報広聴課長","answer":"適切な情報発信のタイミングについてのご質問かと思います。来年度からは、戦略広報課となることですし、さらに私どもからもプッシュ式でやっていきたいと考えています。","id":"exchange-107"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区長、区ができないのだったら、区長のＳＮＳでぜひ発信してほしいと求めましたが、ご意見を説明を求めました。","respondent":"久保田企画部長","answer":"私ども、すみません、そこまで情報を知らなかったということで、大変申し訳ないと思ってあります。啓発を進めていきたいと考えていますし、今日この委員会が終わりましたら、早速そういった形で情報発信をしていきたいというふうに考えてあります。","id":"exchange-108"},{"speaker":"えのした委員","kind":"質問","question":"１５１ページ、４８ページ、こころのセルフコントロール講習会についてお伺いいたします。そこでお伺いします。","respondent":"佐藤企画課長","answer":"今回、このように複数充当するのは初めてというところで、区民還元、公益性、独自施策という３本柱で事業選定をしたところです。孤独・孤立は、今年度、国の補助金等もいただいて先進的に行っている事業というところで選定したところです。","id":"exchange-109"},{"speaker":"えのした委員","kind":"確認","question":"広域性、区の独自施策ということで確認がとれました。これまでの複合的課題、隙間の課題、また取組についてお知らせください。","respondent":"東野福祉計画課長","answer":"重層的支援体制整備事業ですが、相談支援、参加支援、地域づくりの体制を整備し、令和７年度の本格実施に向けた検討を進めているところです。相談支援の部分では、様々な視点から支援方法を検討し、事例の集積を行っているところです。","id":"exchange-110"},{"speaker":"えのした委員","kind":"確認","question":"様々な取組を確認できました。今後の取組と、区のご見解をお知らせください。","respondent":"東野福祉計画課長","answer":"区では今年度、国のプラットフォーム事業に参加し取組を進める中で、若者層にターゲットを絞りまして調査検討を進めているところです。若者層への対応などを補いつつ、支援団体、取組を行っていきたいと考えているところです。","id":"exchange-111"},{"speaker":"えのした委員","kind":"質問・要望","question":"こういった解決を要望し、施策を進めていただければと存じます。地域団体、先月の２月２２日までにパブリックコメントを募集していましたが、区民の方からどのようなご意見がありましたか尋ねました。","respondent":"東野福祉計画課長","answer":"第４期品川区地域福祉計画のパブリックコメントについてですが、現在のところ、延べ１８人から４１件のご意見をいただいております。パブリックコメントの結果につきましては、４月の厚生委員会でお示しした後、広報や区ホームページに掲載をしてまいります。","id":"exchange-112"},{"speaker":"田中委員","kind":"提案","question":"区長の提案では、区長の強い思いがあったからこそ、今回載っているのだと思います。２,０３６億円、その中でも３８億円は、こういう受け止め方でいいのかどうかお聞かせほしいと求めました。","respondent":"遠藤財政課長","answer":"ウェルビーイング予算として３８億円という数字がありますけれども、全てウェルビーイングの予算につながることは大変多いかと思っているところです。３月１１日の広報紙でも、引き続き、こちらの部分についても研究していきたいと思っています。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"もう１つ、先ほど言った２,０３６億円がウェルビーイング予算であって、しっかり高齢者福祉にも力を入れていただいているということもあります。より力を入れてほしいと求めましたが、１人会派であった当時の森澤都議にもしっかり対応されていた、ご見解をお聞かせいただきます。","respondent":"新井副区長","answer":"今の話の意味では、私自身がしっかり議会に対して説明を尽くしていくことも非常に大事だと考えています。説明をしっかり尽くしてまいりたいと考えていますし、いつでも参りますので、引き続きよろしくお願いします。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"要は、２０億円が毎年のように出てくるかというと、そうでもない。そういう予算編成の在り方が求められてくると思いますので、そこは、今後の区長のリーダーシップを期待して質問を終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"１２５ページのベビーシッター利用支援事業について、時間がありましたら、７１ページのシルバーセンターについて伺いたいと思います。先ほど少し伺ったのですが、その中で、しながわシティランの１,５００万円についての内訳を教えてほしいと求めました。","respondent":"佐藤企画課長","answer":"先行自治体のほうで流出額の２％を目標に、決して低くない目標だとは思っておりますが、あらゆる手段を使って９,０００万円をまずは確保したいというふうに考えております。","id":"exchange-116"},{"speaker":"松永委員","kind":"質問","question":"改めてですけれども、先ほど、しながわシティランは、区民の方を優先に参加していただくと答弁がありました。近隣区では１,５００万円は妥当だということであったのですけれども、私からすると、ただ寄附をしていただくということでよろしいのか尋ねました。","respondent":"佐藤企画課長","answer":"前例のある子どもの未来応援プロジェクトをベースに、まずは区民の方から区の事業に対してご賛同いただきたいというところをベースにしております。様々な手段を使って、ふるさと納税を増収させたいと思いますので、今後も様々検討していきたいと考えています。","id":"exchange-117"},{"speaker":"松永委員","kind":"確認","question":"現在、定期利用と当日利用の確認をさせていただいたところ、昨年度の９５万台を大きく上回っております。この一時利用について、どのエリアを強化されたのか伺います。","respondent":"工藤交通安全担当課長","answer":"駐輪場の強化についてです。こちらにつきましては、自転車の利用が多いところ、例えば大井町駅前ですとか、西大井等を強化しています。","id":"exchange-118"},{"speaker":"松永委員","kind":"質問・要望","question":"大森駅前住宅の当日利用駐車スペースの利用率について伺いたいのですが、一部を撤去されたということを確認させていただいて、大井水神公園内と。大井水神公園内は、定期利用の方のみで、区道歩道上には一時利用の方のみと分けられているのか、その確認も併せて伺います。","respondent":"工藤交通安全担当課長","answer":"住宅前、南側住宅の真ん前にありますけれども、こちらは駐輪台数６０台程度になりますが、こちらも平均で利用率が８０％です。公園内の地下駐輪場については定期利用、地上の平場については当日利用といった形で運用しています。","id":"exchange-119"},{"speaker":"松永委員","kind":"質問","question":"１００％というのは、公園側のほうが１００％ということで、機械式のほうは１００％ではないのではないかと考えています。多分１０年ぐらい前になるのですが、それからもう１０年がたっておりまして、併せてその辺も伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"当日利用が可能かどうかといったところも含めまして話をしているのですが、やはり機械の性質上、当日利用は難しいとなっています。続いて……。","id":"exchange-120"},{"speaker":"松永委員","kind":"質問","question":"どのくらいまであそこの歩道のところを駐輪場として使われるのかということで先ほど質問させていただいたので、そのことについて伺いたいと思います。次に、１２５ページのベビーシッター利用支援事業について伺います。","respondent":"石井保育支援課長、工藤交通安全担当課長","answer":"ベビーシッター利用支援事業のうち、事業者連携型です。今、令和６年度に向けて継続の勧奨などを行っているのですけれども、４０名程度のご利用がいるというふうに把握しています。 大森駅前の駐輪場の検討の関係ですが、こちらは住宅前の駐輪場、先ほどお話ししたとおり、現在まだ８０％超の利用率があります。大森駅周辺の全体の利用率を確認しながら、撤去については検討してまいりたいと考えています。","id":"exchange-121"},{"speaker":"松永委員","kind":"質問","question":"その次のベビーシッターのところは、お伺いしましたら４０名程度ということであります。この事業の申請方法をもっと簡素化できないのか、そうしたことを図れないのかというふうに思うのですけれども、いかがか尋ねました。","respondent":"石井保育支援課長","answer":"それについて回答いたします。例えば、まず、どういった課題があるのかということをきちんと検討した上で考えていきたいと考えています。","id":"exchange-122"},{"speaker":"松永委員","kind":"意見","question":"１０か所と認識しておりますが、そういったところを調べると、西大井いきいきセンターも含まれると掲載されております。「シルバーセンター」と検索したときに、なぜ西大井いきいきセンターが掲載されていないのか、お知らせくださいとの意見を述べました。","respondent":"川原高齢者地域支援課長","answer":"西大井いきいきセンターについての説明です。支出形態なども少し異なることから、予算書については、シルバーセンター使用料のほうには含まれないという形で表記をしています。","id":"exchange-123"},{"speaker":"松永委員","kind":"質問","question":"こうしたシルバーセンターは、地域で生活する高齢者を対象に、ふれあいの場とか憩いの場ということで無料で活用しているかと思います。団体登録、その中で旗の台のシルバーセンターが昨年度４回となっておりまして、その利用状況について改めて伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"稼働率で７２.８％、１２月末日現在で６４５件、利用があります。今の状況としては１件のみの歳入という形でございまして、すごく差があるのが、近隣などに集会などの利用が多いのではというふうに考えられます。","id":"exchange-124"},{"speaker":"塚本委員","kind":"質問","question":"私からは、８１ページの廃棄物処理手数料、それから、５０ページの特別区民税に関して伺いたいと思います。まず、この点について、何か検討できる部分がないのかということでお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"基本的には、現金でお返しするというような手続をとっておりまして、来ていただくというようなことをやってあります。年に何回もあることではない、数年に１回というような観点から、窓口に来ていただくという対応をとっているところです。","id":"exchange-125"},{"speaker":"塚本委員","kind":"質問・要望","question":"すぐにというわけにはいかないかもしれませんけれども、ついてはどうなのかということで、改めてお伺いしたいと思います。２３区のよその区では、品川区としては、なぜそういった対応になっているのか教えてほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"それから、旧旧券の交換につきましては、こちらはいろいろ２３区、今、委員からお話があったように、非常に対応が違うところがあります。やはり時効という考えはあったほうがいいのではないかというところで…","id":"exchange-126"},{"speaker":"塚本委員","kind":"質問・要望","question":"２３区で形成されているわけですし、お願いしたいと思いますので、これは要望としてお伝えさせてほしいと求めました。６０代の人が減っていく、どういった事情で転出する傾向があるのかということでお答えいただければと思うのですけれども、いかがか尋ねました。","respondent":"佐藤企画課長","answer":"人口の関係のご質問です。詳しく調査をしたわけではありませんけれども、自分のライフサイクルの変更といいますか、そういうところなのかなと認識しているところです。","id":"exchange-127"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう１つがファイナンス、これは経済的に豊かである。６０代、ぜひ考えてほしいと求めましたが、最後に一言お願いいたします。","respondent":"佐藤企画課長","answer":"８割の方が幸福だというふうに回答していただいておりますので、５０代、６０代の方もそういった数字なのかと思っています。来年度、実施計画の改定の中で、また詳しく検討してまいりたいと思っています。","id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"５９ページ、新庁舎整備負担金、これは国・都なのですけれども、新庁舎のことについて関連して伺いたいと思います。そういう品川区の庁舎を私はつくっていくべきだと考えておりますけれども、その外観に対する考え方をもう一度お聞かせほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"新庁舎のデザインの考え方ですけれども、基本設計を進めている段階でございまして、形状がほぼ決まったというところになってあります。実施設計を進めるに当たって、区のシンボルとなるように、区民に長く愛されるデザインを目指して実施設計を進めたいと考えているところです。","id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほどの私の質問は、例えば３つぐらいのパターンをつくる、そういうことを踏まえる。今後それをどうしよう、これは私はそうではないだろうと思っているから質問しているわけで、それに対するお答えを正確にしていただきたい。","respondent":"大友新庁舎建設担当課長","answer":"色とか、材質等々につきましては、今後の検討で選定をしていくものとなっています。今、イメージとして、単色でお示しをさせていただいているものについては、一例という形でご認識をいただければと思ってあります。","id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"確認","question":"それから、もう１個、８２ページの土木手数料から入ろうかと思っているのですが、建築確認等、これ、非常に減っている。５％ぐらいがいいのかなとか、内容から入っていくべきだと思っているけれども、これについて考え方を説明を求めました。","respondent":"長尾建築課長、崎村人事課長","answer":"私からは、技術職、特に建築職に関しての育成に関わるご質問にお答えいたします。品川区独自の、また２３区の研修に参加する、そういった技術を磨いていくといったようなことをして育成をしています。 経験者採用につきましては、この間、建築職、土木職を含めて、技術職、また児童相談所の関係で数名採用しておりまして、引き続き採用してまいります。確かに、他団体と比べると、構成比はかなり低い部分がありますので、適正数について…","id":"exchange-131"},{"speaker":"せお委員","kind":"質問","question":"私からは、１６１ページ、庁舎内広告料等、１３５ページ、無電柱化推進事業についてお伺いします。なぜ庁舎内としたのかということと、初めは６３万円という予算額にしたという、そこを含めて今後の有料広告の方向性を説明を求めました。","respondent":"佐藤経理課長","answer":"全庁を挙げて取り組んでいる、検討していますので、貴重な財源の１つとなり得るのではないかというふうに考えておりますので。そういったところを検証いたしまして、効果として全庁で共有しまして、今後について考えていくことになろうかと思います。","id":"exchange-132"},{"speaker":"せお委員","kind":"提案","question":"少しだけ提案するならば、ＳＮＳを活用したり、さらにはネーミングライツもあるわけです。このような今した提案だったり、都市ブランディングのところに含めるという形、そういったことについて区の見解を説明を求めました。","respondent":"佐藤経理課長、三井スポーツ推進課長、辻広報広聴課長","answer":"私のほうからは、最初の広告を募集するに当たって、ヒアリングをするかどうかということについてお答えいたします。４月から準備に入りまして… しながわシティランにつきましては、今、協賛金の募集を開始しようと検討しているところです。協賛企業につきましては… 来年度から都市ブランディングを開始するに当たりまして、全ての中で将来の品川を考えていこうというブランディングをしていく予定です。企業との連携は…","id":"exchange-133"},{"speaker":"せお委員","kind":"質問","question":"安全、円滑な交通の確保、防災性の向上とあります。目的の中での優先順位を教えてほしいと求めました。","respondent":"森道路課長","answer":"無電柱化の目的の優先順位ですけれども、今行っております競馬場通りや文庫の森の周辺ですけれども、そちらは防災性がやはり一番重要だろうというふうに考えているところです。","id":"exchange-134"},{"speaker":"せお委員","kind":"提案","question":"区民の方の理解、協力が第一なので、無電柱化について区民が理解する機会をさらにつくっていただきたいです。このような提案を含めて、今後の方向性を説明を求めました。","respondent":"森道路課長","answer":"区といたしましては、重要な路線ですので、進めていきたいのはやまやまではありますけれども、時間と費用がなかなかかかってまいります。しっかりと進めていきたいというふうに考えているとともに、しっかりと計画の見直しには、お話を聞きながら進めていきたいと考えています。","id":"exchange-135"},{"speaker":"せお委員","kind":"質問・要望","question":"費用面ですと、東京都がすごく強力に進めていただいているので、東京都もご協力いただいて進めていただきたいなとは思っています。そういったこともさらに進めていただいて、新しいものが見えてきて、そういった視点で取り組んでいただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１１４ページの都補助金から、東京都が実施を決定した学校給食費無償化について伺いたいと思います。そして、それは今後、都の補助金として入ることになるのでしょうか、伺います。","respondent":"柏木学務課長","answer":"一応２分の１ということで説明はされておりますけれども、給食の上限単価を設定するというふうに聞いてあります。都立特別支援学校の給食費補助の件ですが、品川区の予算計上の分は減額をするのかということは、調整しながら検討していきたいと思います。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"現在どういう検討がされているのでしょうか。私立や国立に通う人数、改めて伺いたいと思いますけれども、把握されているか尋ねました。","respondent":"柏木学務課長","answer":"私立の人数ですが、資料を今持っておりませんので、すぐお答えできませんけれども、前回答弁した内容で変わりはないと思ってあります。給食の無償化をし始めて、各自治体等でもそういう部分で議論が進んでおりますので、そちらを見てまいりたいと思います。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、実施に向けての検討はされていないということか尋ねました。","respondent":"柏木学務課長","answer":"実質的な検討といたしましては、教育委員会のほうではまだしていない状況です。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"憲法２６条などが言われて、そして全国へ広がるといいなと、充実を求めて質問をしたいと思います。伺います。","respondent":"柏木学務課長","answer":"来年度予算で計上しております補助教材費の保護者負担軽減事業ですが、こちらは今回の事業評価でやっているウェルビーイング予算での計上になりますので、全て品川区の予算となります。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問","question":"特別支援学校がどうなるのかという声が上がって、給食費でそういう経験をしているのに、なぜ当初から特別支援学校を対象にしないのか。当初からぜひそこは対象にすべきではないかと思いますし、しっかり対象にしていくべきと思うのですけれども、いかがか尋ねました。","respondent":"柏木学務課長","answer":"ですので、給食費のように、特別支援学校についてこのまま一律で実施できるかどうかというのは、非常に難しい部分があると考えています。まずは品川区立学校で実施いたしまして、今後、研究してまいります。","id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ実施に向けて検討してほしいと求めました。憲法の立場、そしてウェルビーイングの立場からも、区内に住む子どもたち全てが格差なく教育が受けられるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-142"},{"speaker":"西本委員","kind":"質問","question":"１０９ページの自衛官等募集事務費、そして、９５ページのぷりすくーる西五反田の件、３つ目が、１１７ページの公設民営保育園費をお聞きします。区のお考えについてお聞きします。","respondent":"伊藤災害対策担当課長","answer":"午前中の回答にありますとおり、区としては、名簿を見ていただいて書き写すということはやっていますが、名簿提供はやってございません。ただ、そういった形で、しっかりと地域のために貢献をしていただける自衛隊の皆様にも、採用に協力できるように頑張ってまいります。","id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"次に、ぷりすくーる西五反田ですが、これ、指定管理者制度という形で運営しているのですが、社会福祉法人化もやっていなければおかしくないですか。いつやるのか尋ねました。","respondent":"立木保育課長","answer":"指定管理の運営者は、ＮＰＯ法人から社会福祉法人に切り替わっております。それに向けて、ここを検討していくという、そういうような形になってあります。","id":"exchange-144"},{"speaker":"西本委員","kind":"質問","question":"ですから、あそこは、ぷりすくーるだけではなくて、隣に西五反田保育園があります。もうそろそろ結論を出してください。","respondent":"立木保育課長","answer":"ぷりすくーる西五反田の認定こども園化に関しましては、隣り合っている敷地の西五反田保育園も老朽化が進んでおります。そういうような形で、今、検討を進めているところです。","id":"exchange-145"},{"speaker":"西本委員","kind":"質問","question":"なぜ隣と一緒に考えて、次の世代の保育園、幼保一体施設、今、こども家庭庁ができておりますので、それも含めて考えないのでしょうか。いかがか尋ねました。","respondent":"立木保育課長","answer":"様々検討の中でも、そういった案も検討してきているところですが、やはりぷりすくーる西五反田、まだ１６年という形になってあります。後々転用ということも今後考えられるところではありますが、両方の施設を運用していくという、そういうような考え方です。","id":"exchange-146"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなると、品川区の保育園、私立、公立を含めて、補助金の関係がどうなっていくのか。そして、保育園の全体像がよく見えないので、そこを説明を求めました。","respondent":"今井保育教育運営担当課長","answer":"よって、財政的なところで言うと、公設民営だからといって財政的なメリットが高いというところはございませんというのが１点目です。年度ごとに実施していただくというところで、民設民営を実施いたしますと、より一層民間活力を活用できるというふうに考えているところです。","id":"exchange-147"},{"speaker":"西本委員","kind":"意見","question":"この基本方針の中に書いてあったのが、公私連携型保育所制度、これは児童福祉法第５６条の８ということを書いてありました。やはりこれは協力し合いながら、次の品川区の保育をどうしていくかということになると思うので、そこはどう考えられていますかとの意見を述べました。","respondent":"今井保育教育運営担当課長","answer":"公私の連携の部分ですけれども、先ほどお話し差し上げました協定のところで、区の基本的な保育の理念の部分については引き継がせていただきまして、それ以上のところについては、連携しながらきちんとした保育を提供していただくという意味です。","id":"exchange-148"},{"speaker":"若林委員","kind":"提案","question":"一般のふるさと納税の流入という言い方なのですか、どういうふうにお知らせしていくかということを１つお聞きしておきたいと思います。たばこ等のポイ捨てで刑罰が科せられた事例はありますかということが１つと…","respondent":"提坂税務課長、河合生活安全担当課長","answer":"ふるさと納税の減収額がどこに出てくるかですけれども、目に見えて予算書を見ても分からないのですが、特別区民税の収入見込額、ここの部分がふるさと納税による流出額を見込んで算出したものになってあります。 申し訳ありません、悪質性とか常習性を踏まえた上で法の適用等になりますので、個別の検討になると考えております。その代わり、いろいろトラブル等もありますので、警察で認知したときには…","id":"exchange-149"},{"speaker":"若林委員","kind":"質問・要望","question":"一歩強く、抑止力になるのであれば、ぜひご検討いただきたいという要望です。","respondent":"遠藤財政課長、河合生活安全担当課長","answer":"先ほど委員からお話がありました事務事業評価で２０億円とか、それの２.５倍という形で、かなりの金額だと考えています。大体学校が１校５０億円ぐらいと考えていますので… 他法令の抵触に関する表示につきましては、主管の機関と警察のご意見を聞きながら、効果的な広報啓発ができるように検討してまいります。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"増額の要素こそありますが、マイナスの要素と言えば、令和５年度の財調再鑑定においての約３９７億円というところだと思います。前年度比マイナス１１億円は、どのように見積もっていらっしゃったのか、財政の専門的な視点でお伺いいたします。","respondent":"遠藤財政課長","answer":"その分につきましては、対応補正という形で６か月分が算定になっておりまして、３.５億円程度が入ってくるような形で考えているところです。あるいは、会社の利益があるというところで、大体今年と同じぐらいだろうというふうに見込んで今回の数字を出したところです。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"提案","question":"これは、先日も質疑がありましたけれども、改めて確認したいのですが、令和６年度も５５.１％を維持するということで確認できるでしょうか。この０.１％の中でやっていくのか、私も不勉強なのですが、その辺りはどういう形になるのか尋ねました。","respondent":"遠藤財政課長","answer":"５５.１％という部分につきましては、現在、東京都のほうで予算の審議とともに条例改正という形でやっているところです。児童相談所の０.１％でやるのかですが、ある程度、その中で品川区の場合はこれだけの金額になりますよという形でいただく形になっているところです。","id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問","question":"それが先ほどお話があった対応補正ということになるのかなと思いますが、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"委員おっしゃるとおり、対応補正で対応する形になります。","id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問","question":"その練馬区で、今年の４月１日以降に、練馬区立子ども家庭支援センター内に、練馬区内のみを所管する都立の児童相談所が設置されることになった。これに対し、区長会の一員として、どのように思われているのか、感想をお伺いいたします。","respondent":"遠藤財政課長","answer":"私のほうで、財政の部分でという形になりますけれども、そこの部分について、今まで２３区一緒にやってきたところです。今でも特別区長会を通じまして、様々都と協議していますので、そちらについては継続してやっていくものかと考えているところです。","id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"質問","question":"それに対して品川区がどうこうということではないですが、やはり２３区として足並みをそろえて、これから進んでいってもらいたいというところです。区長は区長会において、ぜひ前向きの姿勢でこれへ臨んでいただきたく、改めて心意気をお伺いいたします。","respondent":"森澤区長","answer":"先ほどお話がありましたけれども、やはり区によって大分状況が違ってきているということは正直あるとは思います。品川区としては、しっかり児童相談所を設置していくという中で財源は確保していく、その点は変わらないと考えています。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区としてしっかりと財源を確保し、品川区のお子さん、そして保護者の方々のために、きちんと現在進めている区立児童相談所をさらなるしっかりしたものに進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-156"},{"speaker":"こしば委員","kind":"質問","question":"私からは、１３９ページ、持続可能な地域公共交通実現に向けた事業補助金について質問します。そこで、まず、こちらの歳入となります事業の補助金が充当される本区の事業について説明を求めました。","respondent":"鈴木都市計画課長","answer":"まずはコミュニティバスの実施に、行う委託の検討経費に歳入で充てるとともに、こうした実証実験に向けた検討も行ってまいります。そうした金額の検討経費に充当していくものです。","id":"exchange-157"},{"speaker":"こしば委員","kind":"質問・要望","question":"今、課長がお答えになりましたコミュニティバスの事業についてお伺いしたいと思います。基本的ですが、誰もが移動しやすい利便性の高さを求めていくのがコミュニティバスと捉えておりますが、お聞きします。","respondent":"鈴木都市計画課長","answer":"品川区、鉄道、バス、非常に交通の利便性が高いと。そうしたところもしっかり検討しながらしていくことで、移動の頻度の、区民のウェルビーイングにつながっていくというふうに感じているところです。","id":"exchange-158"},{"speaker":"こしば委員","kind":"確認","question":"このシルバーパス利用者も１人当たり２２０円を充当した運賃収入、今後、判断するということなのでしょうか。確認をお願いします。","respondent":"鈴木都市計画課長","answer":"ご指摘のとおり、令和６年度の運行実績に基づいて判断をしていくですが、その判断基準が５０％という設定をしています。シルバーパスを金額換算した数字を使うかどうかも含めて、総合的な判断を来年度の結果も精査をして、していくというようなことです。","id":"exchange-159"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ公益の観点、また、社会状況を踏まえて判断をお願いしたいと思います。運転士の不足について、何か状況について聞き取りを行っているのか、教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"全国的なバス、タクシーも含めてですが、運転士不足の動向については、区でも承知しています。減便ですとか、そうした地域の足を今後も継続して行っていきたいというところから、様々な企業努力をしていただいているというようなところです。","id":"exchange-160"},{"speaker":"こしば委員","kind":"提案","question":"西大井の循環ルート、具体的に言いますと、西大井二丁目から六丁目区間、そのエリアを回るルートについて、質問・提案をさせていただきました。５ｍ程度の箇所も複数あり、道も蛇行を繰り返し、対向車を遠くから目で確認することが難しい道路事情もありますとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"利便性の向上を目指し実施に向けて取り組んでいくもので、検討を進めまして、秋頃には実証実験を開始したいというふうに考えてあります。","id":"exchange-161"},{"speaker":"こしば委員","kind":"質問・要望","question":"バスが走っていないエリアに、オンデマンド交通の網が広がっていくことを、ぜひ検討をお願いしたいと思います。ぜひ実証実験、オンデマンド交通の実証実験で取り入れていただきたいということを願いまして、質問は終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-162"},{"speaker":"松本委員","kind":"提案","question":"１４９ページ、１５１ページ、職員提案制度について伺います。今回の区の職員提案について、何か提案してくださった方に対してインセンティブを与える考えはあるか、お伺いいたしますとの意見を述べました。","respondent":"岡秘書担当課長","answer":"職員提案制度のインセンティブなどについての質問についてお答えします。人事異動に関しまして、人事課で実施しております庁内公募を活用して、積極的に庁内公募制度の利用を進めるように声かけを行ってきました。","id":"exchange-163"},{"speaker":"松本委員","kind":"提案","question":"これは、提案された方が実際に事業に関われるかどうかというところで変わってくるのかなと。今回提案された方たちが手を挙げた際に、異動が可能かどうかというふうな、いかがでしょうとの意見を述べました。","respondent":"崎村人事課長","answer":"秘書担当課長から、今年度の異動について、庁内公募でそのような職員の提案制度と連動した取組は行っておりません。庁内公募を昨年度から試行的に実施しておりまして、令和６年度以降、検討していきたいというふうに考えているところです。","id":"exchange-164"},{"speaker":"松本委員","kind":"提案","question":"職員提案制度自体は、これは過去にも品川区で実績があるというふうに聞きまして、当時は人事課が所管だったというふうに伺いました。一般質問でもあったかもしれませんが、審査基準についてもお伺いできればと思いますとの意見を述べました。","respondent":"岡秘書担当課長","answer":"区長へ直接プレゼンを行うことにより、職員の仕事に対してのやりがいやモチベーションを上げるということにより、今年度は秘書担当が実施しました。この区長プレゼンですけれども、区長はもちろんのこと、両副区長、企画部長、総務部長…","id":"exchange-165"},{"speaker":"松本委員","kind":"提案","question":"創業支援の際に事業計画を出したりすることがあると思いますけれども、そういったレベルの提案までなされたのか、その辺りはいかがか尋ねました。","respondent":"篠田文化観光課長","answer":"カプセルトイについては７２０億円ぐらいというふうに言われておりますし、限られたイベント等での販売で、かなり売上げを上げているというような状況を見てきた職員から出てきているものです。","id":"exchange-166"},{"speaker":"松本委員","kind":"提案","question":"時間も限られておりますので、さらにカプセルトイについて伺いたいのですが、かなり研究されてご提案されたということは理解いたしました。紙といいますか、こういったものを使うということも１つ考え方としてはあると思うのですが、いかがか尋ねました。","respondent":"篠田文化観光課長","answer":"今、委員ご指摘のあったとおり、カプセルトイもいろいろ進化をしているというふうには聞いています。いわゆる税外収入確保の観点からいくと、少しまたなかなか難しいのかなということで、これから先を検討してまいりたいと思います。","id":"exchange-167"},{"speaker":"松本委員","kind":"質問・要望","question":"なかなか課題もいろいろあると思いますが、ぜひ前向きにいろいろなことを進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-168"},{"speaker":"藤原委員","kind":"質問","question":"だから、私は、この後、ふるさと納税を伺いますが、課長、ふるさと納税、もう答弁しないでいいですよ。今、品川区は、２３区で徴収率は何位か尋ねました。","respondent":"提坂税務課長","answer":"令和４年度決算で申し上げますと、２３区中１位です。","id":"exchange-169"},{"speaker":"藤原委員","kind":"質問・要望","question":"だって、２３区の試験を受けて品川区と来てくださるのですから。税務課長、いいですからね。","respondent":"佐藤企画課長、堀越総務部長","answer":"職員に努力義務を課すかは別として、様々な手法を使って、ふるさと納税の流出・流入の対応を一生懸命頑張ってやっていきたいと考えています。 委員がご発言なさった内容についても、それは職員の個人の判断にはなりますけれども、そういうことも大切だというふうには思ってあります。","id":"exchange-170"},{"speaker":"藤原委員","kind":"質問","question":"だからどうなのかと、品川区には伺わないですけれども、私は、これが現実だと思って、ありがとうございました。それで、これこそ１４６ページ、配当金で伺いたいのですけれども、会計管理室、出番ですよ。","respondent":"大串会計管理者","answer":"それから、運用の基本方針です。こういったものを確実にといったところで、今後も運用をしていければというふうに考えているところです。","id":"exchange-171"},{"speaker":"藤原委員","kind":"質問","question":"ほかの２３区の中で、０.２５２と言いましたか、０.３ぐらい平均で出しているところがあるのです。勉強するなりして、大きく利率を取れるほうがいいと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"大串会計管理者","answer":"金利の低い時代に購入したものもありますので、それをひっくるめて平均化したものが、先ほど紹介した０.２５２という数字になってまいります。情報収集を行いまして、かつ、有利なものを購入していこうというふうに考えているものです。","id":"exchange-172"},{"speaker":"藤原委員","kind":"質問","question":"最初に区民税を伺って、この基本になる人口動態についてお伺いしたいと思うのですけれども、２０４０年か４５年ぐらいかなと思ったのです。だから、そこも含めて、人口動態を、企画課としてはどういうふうに捉えているか説明を求めました。","respondent":"佐藤企画課長","answer":"令和６年、コロナ禍の前のピークだった４０万８,０００人を超えておりますので、大分早いペースで人口が戻ってきているなと感じているところです。ここで生産年齢人口がたくさん多い都市をあらわしている形にも近いようになってまいりますので、今現在、認識しているところです。","id":"exchange-173"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、今日、財調を伺おうと思っていました。総括質疑で思い切り伺いますので、もう長く答弁してくださって結構ですから、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-174"},{"speaker":"鈴木委員","kind":"質問・要望","question":"９１ページの介護保険負担金、１２３ページの介護人材緊急確保対策事業費補助金、処遇改善について伺いたいと思います。全員に無料券を出していただきたいと思うのですけれども、それから、要望に対してお聞かせほしいと求めました。","respondent":"篠田文化観光課長","answer":"現在、駐輪場は７２台分ということで、非常に少ない状況ですので、区の施設だけで大幅に使うということがなかなか難しい状況があります。ホームページ等では、ご案内が今まで漏れていたところがありますので、こちらについては早急に対応するようにしたいと考えているところです。","id":"exchange-175"},{"speaker":"鈴木委員","kind":"質問・要望","question":"リハビリ関係、看護師とかは対象にならないのか、その確認をお願いしたいと思います。それから、品川区としては、この対象をどう考えられているのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区の居住支援手当についてということなのですけれども、国の介護報酬６,０００円、全体的なところなのかなと捉えております。予算の説明会が開かれまして、対象者について、さらに検討していきたいと思っているところです。","id":"exchange-176"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、それ以外のところは対象にならないのかと思ったのですけれども、そこのところの確認をもう１回お願いしたいと思います。そういうところからすると、介護の現場で働く職種全てを対象にして１万円の支給はぜひしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"それをいろいろ足していくと、結果、大体１人当たり６,０００円アップすると捉えているところです。区においては、ではどうしようかというところで、限られた予算の中で、どういった対象者にするかというのは、今後検討していきたいと考えています。","id":"exchange-177"},{"speaker":"大倉委員","kind":"質問・要望","question":"１１７ページ、区内私立保育園経費に関連して、不審者の対応や保幼小連携について伺えればと思います。１４１ページ、時間があれば、６１ページのシルバー人材センターについて伺いたいと思います。","respondent":"立木保育課長、石井保育支援課長、中谷指導課長","answer":"は定期的な暗証番号の変更、もし仮に不審者が園内に入った場合には、学校１１０番という警察に直接つながるボタン等を設置しています。… 私立保育園に関しても、区立保育園でやっている対策と同様のものをやってあります。通知レベルではあるのですけれども… 協議会を運動部で３回、文化部については２回ということで開催いたしまして、その中で検討を重ねてきました。各学校には…","id":"exchange-178"},{"speaker":"大倉委員","kind":"質問・要望","question":"こうした訓練や対策についての実施検討について伺いたいと思います。地域移行に向けての方針について伺いたいのですが、最終的には、地域のスポーツ団体への部活動移行ができるということが非常に重要だと考えています。","respondent":"立木保育課長、石井保育支援課長、中谷指導課長、三井スポーツ推進課長","answer":"お散歩等での不審者対応ですけれども、ヒヤリハットのところをしっかり事前に確認し、周辺を観察しながらというところでやってあります。… 補助金として、お散歩時の見守り要員に対する補助なども令和５年度から創設した上で、児童の安全に対してきちんと対処してまいりたいと考えています。 教育委員会としての回答をさせていただきたいと思います。地域とのつながりというところで、関係部局と連携しながら… スポーツ推進課では…","id":"exchange-179"},{"speaker":"大倉委員","kind":"質問","question":"次の保幼小の連携について伺いますが、平成２２年に、幼児期教育と小学校教育をシームレスにつなぎ。学ぶ力の３つの観点１０項目からまとめというところで意義が書いてありまして、この効果というか、成果をぜひ教えてほしいと求めました。","respondent":"中谷指導課長、三井スポーツ推進課長","answer":"部活動の地域移行ですが、教育委員会としましては、今後も協議会を継続して開催してまいりたいと考えています。 既に自主的にアンケートを実施していただいた地域スポーツクラブを中心に、今後、人材リストができないかということを話し合っていきたいと思います。 平成２２年度当時に発行した際にご指導いただいた白梅学園大学の名誉教授の無藤先生に、幼児教育研修会で講師としてご指導いただいているところです。今年…","id":"exchange-180"},{"speaker":"大倉委員","kind":"質問・要望","question":"今もしっかりと続けられているというところで確認がとれました。改めて別のところで伺いたいと思いますが、保育園もこういった学校で教えてくれているのだなという相互の理解が進むというところでは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-181"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１３９ページ、区民交通傷害保険について伺ってまいります。なぜ歳入の款で伺うかと申しますと、保険会社である損保ジャパンから一定の割合で手数料が還付される、いわゆるキックバックがあります。","respondent":"工藤交通安全担当課長","answer":"次に、予算書の記載部分ですけれども、こちらは１６９ページ、雑入、処分自転車等売却費等の中に含まれてあります。令和６年度の見込みですけれども、おおむね３,２００名、令和５年度と同等額の約９０万円ということで見込んでいるところです。","id":"exchange-182"},{"speaker":"あくつ委員","kind":"提案","question":"２０１９年７月の実施までに、２０１７年から、私、これ、何度か議会でこの導入を求めてまいりました。本制度の意義について、品川区はどのようにお考えになっているのか説明を求めました。","respondent":"工藤交通安全担当課長","answer":"もう１つ、リピーターの方も多いということで、おおむね８割程度がリピーターというような状況になってあります。先ほど委員ご説明のとおり、不幸にしないといったところで非常に重要なものだと考えておりますので、引き続きやってまいりたいと考えています。","id":"exchange-183"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本制度の課題についても伺ってまいります。それに伴う職員の事務負担があると聞きましたが、その点も説明を求めました。","respondent":"工藤交通安全担当課長","answer":"この送付に基づきまして、区では、職員がデータ入力、通知書のスキャン、または印刷した通知書を保険会社に送るといったような作業が発生します。これが所定の大きさ、この形の大きさに切らないと…","id":"exchange-184"},{"speaker":"あくつ委員","kind":"提案","question":"これは今のものを伺うと、今、かなりの数のＡＩ－ＯＣＲと連携したＲＰＡ化が進んでいるということになっています。これは情報戦略担当に伺いたいのですけれども、事務を軽減してはいかがでしょうかということで提案をしたいと思うのですが、いかがか尋ねました。","respondent":"河西情報戦略担当課長","answer":"検討したかどうかというご質問に対してですが、区の取組といたしまして、毎年８月にデジタル人材育成研修を実施しております。区民の利便性向上と業務の効率が図れる可能性がありますので、所管課の皆さんと検討を進めさせていただきたいと考えています。","id":"exchange-185"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４月段階で、さっき申し上げたように５月から６月しかできないので、１年中通年で申し込めるから拡大するわけです。これをぜひやっていただきたいのですけれども、この辺、検討していただきたいと思うのですけれども、交通安全担当課長のご見解を伺います。","respondent":"工藤交通安全担当課長","answer":"委員ご提案のウェブ申請の導入も含めまして、よりよい商品を提供できるように検討してまいりたいと思います。最後に１つ、全日本交通安全協会のほうで実施しているサイクル安心保険、そちらのご案内はさせていただいているところです。","id":"exchange-186"},{"speaker":"あくつ委員","kind":"質問","question":"サイクル安心保険の話も伺いましたけれども、これは残念ながらもらい事故には対応していないのです。いわゆる自転車専門の保険ですから、紙で書けるというところもあるので、ぜひ二本立てでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-187"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１３１ページ、商店街活性化推進事業助成金、１２９ページ、健康増進事業費、８０ページ、使用料手数料についてお伺いします。区に何らかの形で活用方法が何かあるのかということを、賛成なのですけれども、この件に対する区の見解をお尋ねしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"具体的には、地域のにぎわい創出、そして防災の拠点機能、この２つの観点を念頭に置きまして、区のほうで活用してほしいという内容でございました。そして防災機能の強化、こちらの２点につきましては非常に重要と考えていますので、活用について前向きに検討しています。","id":"exchange-188"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"前向きに検討されるということで、具体的にどういった活用方法を想定しているのかということをお伺いしたいと思います。様々な活用の用途が考えられると思いますけれども、区の見解をお聞かせほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"委員ご案内のとおり、様々な用途が考えられますので、要望をいただきまして、にぎわいの創出、こういったものに寄与できるように、地域の方々のご意見も伺いながら、引き続き検討を進めていきたいと思います。","id":"exchange-189"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"様々な活用方法があると思うので、ぜひ地元の方々の要望を聞いていただいて、活用方法を検討してほしいと求めました。今現在、禁煙外来治療の今年の取組、来年度の取組、何か変化があったのかどうかをまず最初にお尋ねしたいと思います。","respondent":"若生健康課長","answer":"その禁煙外来治療を実施している医療機関が行う治療について、今年度１月末時点で、件数は６４名となっています。来年度、変化があるのかというところですが、こちらの事業については、引き続き同様に実施していく予定です。","id":"exchange-190"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"販売が休止になっていると思うのですけれども、これもまだ今、休止の状態に恐らくなっていると思うのです。私、聞いたのですけれども、それを確認させてほしいと求めました。","respondent":"若生健康課長","answer":"令和３年６月から、その特定のロットを含めて、全世界で全ての出荷が停止状態になっているです。問題なく出荷されておりますので、そういったところも含めて治療薬の補助は、そのまま継続しています。","id":"exchange-191"},{"speaker":"高橋（伸）委員","kind":"提案","question":"そうすると、私が提案したいのは、パネルフェンス等で囲っている喫煙所が近隣区の大田区でも見受けられます。特に、受動喫煙に対して、その辺のことをどういうふうに認識されているのかということをお尋ねしたいと思いますとの意見を述べました。","respondent":"河合生活安全担当課長","answer":"確かに、今、既存のコンテナ型のほうは、財政負担が大きくて課題が大きいと認識しております。委員ご指摘のとおり、トレーラー型とか、コストダウンの商品の発掘も含めて、そういった検討をしてまいりたいと思います。","id":"exchange-192"},{"speaker":"高橋（伸）委員","kind":"意見","question":"もし試験的に実証実験をやっていただくということも検討してみてはいかがなものかと思うのですけれども、西大井に対してのお話を聞きたいと思います。お願いしますとの意見を述べました。","respondent":"河合生活安全担当課長","answer":"今、既存の場所のところが樹木等があって検討課題がありますので、場所の移動とかも含めて関係部署と調整中です。引き続き、適正な設置に向けて検討してまいりたいと思います。","id":"exchange-193"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"粗大系のごみ、いずれも令和５年度よりも回収率の見込みを減らしているのですけれども、その理由と考え方をお尋ねしたいと思います。これが減収の主な要因になっているかと私は思うのですけれども、お尋ねをしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"やはりコロナの時期に、それがだんだん少し緩くなってきまして、粗大ごみの量も徐々に毎年毎年減っているというような状況が来ております。予算は、ある程度一定に抑えていたのですけれども、そういった状況も見まして、今年度…","id":"exchange-194"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、ごみの量が減るということは、当然、私も評価すべきと考えております。不法投棄防止対策に対する今後の見込みというか、見通しはどういうふうに思われているのかということをお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"基本的にやはり一番発生しやすい場所が、資源ごみを回収するところの資源ステーション、こちらに全体的に９割近く置かれているような状況です。ステーションに看板等、いろいろな啓発活動をして、不法ごみについては対策を練っているところです。","id":"exchange-195"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当にこれ、パトロールしていただいて、不法投棄をなくしてほしいと求めました。近年は、廃棄物の観点から、サーキュラーエコノミーの確立に向けた今後の取組をお尋ねしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"現在、ペットボトル、缶が、やはり皆さん、周知が徹底してきていまして、リサイクルが非常によく進んでいるところです。今後は、新たなリサイクル品目を探して、少しでもごみ量を減らしていきたいと考えております。","id":"exchange-196"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6687#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":129266,"voices":449}},{"id":"r06-20240305-10","meetingId":"r06-cm03","date":"2024年3月5日","dateIso":"2024-03-05","committee":"議会運営委員会","time":"午後 ６時０４分～午後 ６時１１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=5542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2367,"voices":22}}]);
